function favState(s,o){
  if(s.disp)return {cls:'fst-weak',txt:'⚠ 處置中·管制交易'};
  const tt=(o&&o.length>=40)?turtleCalc(o,s.price):null;
  if(tt&&tt.sigType)return {cls:'fst-brk',txt:`🚀 突破訊號(${tt.sigType}日)·帶量可追蹤`};
  if(tt&&s.price&&tt.l10&&s.price<tt.l10)return {cls:'fst-weak',txt:`🔻 出場訊號·跌破10日低 ${tt.l10}`};
  let ma20=null,ma60=null,ma20p=null;
  if(o&&o.length>=65){
    const cl=o.map(x=>x[3]),av=a=>a.reduce((x,y)=>x+y,0)/a.length;
    ma20=av(cl.slice(-20));ma60=av(cl.slice(-60));ma20p=av(cl.slice(-25,-5));
  }
  if(ma60!=null&&s.price<ma60)return {cls:'fst-weak',txt:`🔻 季線 ${ma60.toFixed(0)} 之下·弱勢防守`};
  if(tt&&s.f&&s.f.score>=72&&tt.gap20>=2){
    const hot=(()=>{try{return zt8Hot();}catch(e){return new Set();}})();
    const g=gemDiag(s,o,tt,hot);
    if(g)return {cls:'fst-gem',txt:`💎 蓄勢待發·訊號 ${g.lit}/8·確認點 ${g.h20}`};
  }
  if(ma20!=null&&s.price>ma20&&ma20p!=null&&ma20>ma20p)
    return {cls:'fst-up',txt:'📈 多頭順勢·月線上且翻揚'};
  return {cls:'fst-wait',txt:'⏳ 區間整理·等訊號'};
}
