function t3RenderRows(sid,rows,slot,src){
  // YoY:與往前4季比(在集合內才算)
  const revOf=r=>r&&r.v&&r.v.rev?r.v.rev:null;
  const tds='padding:5px 8px;border-bottom:1px dashed var(--line);text-align:right;font-family:var(--mono);font-size:13px;white-space:nowrap';
  const arrowC=(cur,prev)=>prev==null?'var(--txt)':cur>prev?CT.up2:cur<prev?CT.dn2:'var(--mut)';
  const yoyAt=i=>{const r=rows[i],y4=rows[i+4];
    return (revOf(r)&&y4&&revOf(y4))?((revOf(r)/revOf(y4)-1)*100):null;};
  const body=rows.map((r,i)=>{
    if(!r.v)return `<tr><td style="${tds};text-align:left;color:var(--mut)">${r.q}</td><td style="${tds};color:var(--dim)" colspan="4">無資料</td></tr>`;
    const yoy=yoyAt(i), pv=rows[i+1]&&rows[i+1].v;
    return `<tr>
      <td style="${tds};text-align:left;color:var(--txt2)">${r.q}</td>
      <td style="${tds};line-height:1.4"><b>${r.v.rev?(r.v.rev/100).toFixed(0):'—'}</b><br><span style="font-size:11.5px;font-weight:800;color:${yoy==null?'var(--mut)':yoy>0?CT.up2:CT.dn2}">${yoy==null?'YoY —':'YoY '+(yoy>0?'+':'')+yoy.toFixed(1)+'%'}</span></td>
      <td style="${tds};color:${arrowC(r.v.gm,pv&&pv.gm)}">${r.v.gm.toFixed(1)}%</td>
      <td style="${tds};color:${arrowC(r.v.om,pv&&pv.om)}">${r.v.om.toFixed(1)}%</td>
      <td style="${tds};color:${arrowC(r.v.nm,pv&&pv.nm)}">${r.v.nm.toFixed(1)}%</td></tr>`;
  }).join('');
  const cid='t3c'+Math.random().toString(36).slice(2,8);
  slot.innerHTML=`<div id="${cid}" style="height:240px;margin:2px 0 6px"></div>
    <div style="overflow-x:auto"><table style="border-collapse:collapse;width:100%;min-width:440px;margin-top:2px">
    <tr>${['季度','營收(億)/YoY','毛利率','營益率','淨利率'].map((h,i)=>`<th style="text-align:${i===0?'left':'right'};padding:4px 8px;color:var(--mut);font-size:12px;border-bottom:1px solid var(--line);white-space:nowrap">${h}</th>`).join('')}</tr>
    ${body}</table></div>
    <div style="font-size:11.5px;color:var(--dim);margin-top:4px">圖:長條=季營收(柱頂標 YoY)、折線=三率(右軸);表:紅=較上季升、綠=降;資料:${src}。</div>`;
  try{
    const asc=[...rows].reverse().filter(r=>r.v);
    const el=document.getElementById(cid);
    if(el&&asc.length<2){el.style.height='auto';el.innerHTML='<div class="dim-note">趨勢圖需至少兩季資料,目前僅取得一季——上表照常顯示,下一季公布後圖會自動出現。</div>';}
    else if(el){
      if(!window.echarts)el.innerHTML='<div class="dim-note">📊 圖表引擎載入中…</div>';
      let tries=0;
      const draw=()=>{
      try{
      if(!el.isConnected)return;
      if(el.clientWidth<40||el.clientHeight<40){
        setTimeout(draw,++tries<16?250:900);return;        // r701:面板隱藏時無限慢速等待——章節分頁後隱藏可長於數秒,元素移除(isConnected=false)自然停止
      }
      const ch=echarts.init(el);
      el.dataset.drawn='1';
      setTimeout(()=>{try{ch.resize();}catch(e){}},350);
      // 🛡 r383:季報圖「不」登記進 chipCharts——籌碼區重繪時會 disposeChipCharts() 把本圖一起銷毀(圖白表在的元兇)
      try{if(window.__t3Chart&&window.__t3Chart!==ch)window.__t3Chart.dispose();}catch(e){}
      window.__t3Chart=ch;
      const idxMap=asc.map(r=>rows.indexOf(r));
      ch.setOption({
        grid:{left:46,right:44,top:30,bottom:24},
        legend:{data:['營收(億)','毛利率','營益率','淨利率'],top:0,textStyle:{color:CT.legend,fontSize:11.5}},
        tooltip:{trigger:'axis',backgroundColor:CT.ttBg,textStyle:{color:CT.ttText,fontSize:12.5}},
        xAxis:{type:'category',data:asc.map(r=>r.q),axisLabel:{color:CT.axis,fontSize:11},axisLine:{lineStyle:{color:CT.border}}},
        yAxis:[{type:'value',name:'億',axisLabel:{color:CT.axis,fontSize:10.5},splitLine:{lineStyle:{color:CT.split}}},
               {type:'value',name:'%',axisLabel:{color:CT.axis,fontSize:10.5,formatter:'{value}%'},splitLine:{show:false}}],
        series:[
          {name:'營收(億)',type:'bar',data:asc.map(r=>+(r.v.rev/100).toFixed(0)),barMaxWidth:26,
            itemStyle:{color:'rgba(230,168,60,.55)',borderColor:'var(--amber)',borderRadius:[3,3,0,0]},
            label:{show:true,position:'top',fontSize:10,fontFamily:'monospace',
              color:CT.legend,
              formatter:p=>{const y=yoyAt(idxMap[p.dataIndex]);return y==null?'':(y>0?'+':'')+y.toFixed(0)+'%';}}},
          {name:'毛利率',type:'line',yAxisIndex:1,data:asc.map(r=>r.v.gm),symbol:'circle',symbolSize:4,lineStyle:{width:2.2,color:CT.up2},itemStyle:{color:CT.up2}},
          {name:'營益率',type:'line',yAxisIndex:1,data:asc.map(r=>r.v.om),symbol:'circle',symbolSize:4,lineStyle:{width:2,color:CT.ttBg==='#FFFFFF'?'#2E62C9':TONE.blue},itemStyle:{color:CT.ttBg==='#FFFFFF'?'#2E62C9':TONE.blue}},
          {name:'淨利率',type:'line',yAxisIndex:1,data:asc.map(r=>r.v.nm),symbol:'circle',symbolSize:4,lineStyle:{width:2,color:CT.dn2},itemStyle:{color:CT.dn2}}]
      });
      }catch(err){
        el.innerHTML='<div class="dim-note">季報圖表繪製失敗:'+(err&&err.message||err)+'——請截圖回報,一截就能修</div>';
      }
      };
      ensureECharts().then(ok=>{
        if(!el.isConnected)return;
        if(!ok){el.style.height='auto';el.innerHTML='<div class="dim-note">圖表引擎載入失敗(三個 CDN 均不通,可能是網路暫時問題)——上表資料不受影響,重新整理通常就好。</div>';return;}
        el.innerHTML='';
        draw();
      });
      setTimeout(()=>{   // 🐶 看門狗:6秒沒畫出來就把原因寫在空白處(不再讓人對著空白猜)
        try{
          const el2=document.getElementById(cid);
          if(!el2||el2.dataset.drawn==='1'||el2.textContent.trim())return;
          el2.style.height='auto';
          el2.innerHTML='<div class="dim-note">⚠ 圖表 6 秒內未完成繪製——診斷:引擎 '
            +(window.echarts?'已載入':'未載入')+' · 容器 '+el2.clientWidth+'×'+el2.clientHeight
            +' · 連線 '+(el2.isConnected?'正常':'已脫離')
            +'。上表資料不受影響;請把本訊息截圖回報,一次就能修。</div>';
        }catch(e){}
      },6000);
    }
  }catch(e){}
}
function ensureECharts(){   // 📊 圖表引擎保險絲:head 的 cdnjs 沒載到時,自動換備援 CDN 補載
  if(window.echarts)return Promise.resolve(true);
  if(window.__ecP)return window.__ecP;
  window.__ecP=new Promise(res=>{
    const urls=['https://cdnjs.cloudflare.com/ajax/libs/echarts/5.4.3/echarts.min.js',
                'https://cdn.jsdelivr.net/npm/echarts@5.4.3/dist/echarts.min.js',
                'https://unpkg.com/echarts@5.4.3/dist/echarts.min.js'];
    let i=0;
    const nx=()=>{
      if(window.echarts)return res(true);
      if(i>=urls.length)return res(false);
      const sc=document.createElement('script');
      sc.src=urls[i++];
      sc.onload=()=>{window.echarts?res(true):nx();};
      sc.onerror=nx;
      document.head.appendChild(sc);
    };
    nx();
  });
  return window.__ecP;
}
function t3QNow(){                                       // 依申報時程推測最新可得季
  const d=new Date(), y=d.getFullYear(), m=d.getMonth()+1, day=d.getDate();
  if(m>11||(m===11&&day>=15))return y+'Q3';
  if(m>8||(m===8&&day>=15))return y+'Q2';
  if(m>5||(m===5&&day>=16))return y+'Q1';
  return (y-1)+'Q4';                                       // Q4/年報 3/31 前後,保守用前一年Q4(4/1 起可得)
}
async function t3qBlock(s){
  try{await t3qBlockCore(s);}catch(err){
    const sl=document.getElementById('t3qSlot');
    if(sl)sl.innerHTML='<div class="dim-note">季報載入發生例外('+String(err).slice(0,60)+')——<a href="javascript:void 0" onclick="try{t3qBlock(window.__t3qS)}catch(e){location.reload()}" style="color:var(--amber);font-weight:800">點我重試</a></div>';
  }
}

function finQBlock(s,e){                    // 🏛️ 財務體質:ROE(近四季)+負債比——獲利品質與安全邊際
  const box=document.getElementById('finQBox');
  if(!box)return;
  try{
    if(!e||!e.bsq||e.debt==null){box.innerHTML='';return;}
    let roe=null;
    if(e.eqv>0&&Array.isArray(e.fq)&&Array.isArray(e.nm)&&Array.isArray(e.qr)){
      let ni=0,nq=0;
      for(let i=e.fq.length-1;i>=0&&nq<4;i--){
        if(e.qr[i]!=null&&e.nm[i]!=null){ni+=e.qr[i]*e.nm[i]/100;nq++;}
      }
      if(nq>=3)roe=+(ni/e.eqv*100).toFixed(1);
    }
    const isFin=/金|銀行|保險|證券/.test(s.sector||'');
    const roeSt=roe==null?null:roe>=15?['優異','pos']:roe>=8?['穩健','flat']:roe>=0?['偏低','flat']:['虧損','neg'];
    const dSt=isFin?['金融業高槓桿屬常態','flat']:e.debt>=70?['偏高,留意利率與景氣風險','neg']:e.debt>=50?['中等','flat']:['低,財務保守','pos'];
    box.innerHTML=`<div class="dim-block" style="border-left:4px solid #6FA8DC"><h3>🏛️ 財務體質 <span class="ds">${e.bsq}</span></h3>
      <div class="earn-metrics" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))">
        <div class="em-card"><div class="em-v ${roeSt?roeSt[1]:'flat'}">${roe!=null?roe+'%':'—'}</div><div class="em-l">ROE 股東權益報酬(近四季年化)${roeSt?' · '+roeSt[0]:''}</div></div>
        <div class="em-card"><div class="em-v ${dSt[1]}">${e.debt}%</div><div class="em-l">負債比 · ${dSt[0]}</div></div>
        <div class="em-card"><div class="em-v flat" style="font-size:15px;padding-top:5px">${e.eqv?e.eqv.toLocaleString()+' 億':'—'}</div><div class="em-l">股東權益</div></div>
      </div>
      <div class="dim-note" style="margin-top:6px">ROE=近四季稅後淨利÷權益;>15% 屬資本效率優異、<8% 偏低。負債比${isFin?'對金融業不適用一般標準(高槓桿為商業模式)':'>70% 遇升息或景氣反轉壓力大'}。自由現金流官方無免費彙總表,暫以 ROE+負債比把關獲利品質。</div></div>`;
  }catch(err){box.innerHTML='';}
}

async function t3qBlockCore(s){
  window.__t3qS=s;
  const box=document.getElementById('t3qBox');
  if(!box)return;
  clearTimeout(window.__t3qWd);
  window.__t3qWd=setTimeout(()=>{                        // ⏱ 看門狗:15秒後仍空白/卡載入 → 顯示重試,不留白
    const sl=document.getElementById('t3qSlot');
    if(sl&&(!sl.innerHTML.trim()||/載入中|讀取/.test(sl.textContent)))
      sl.innerHTML='<div class="dim-note">季報載入逾時(免費代理路徑偶爾塞車)——<a href="javascript:void 0" onclick="try{t3qBlock(window.__t3qS)}catch(e){location.reload()}" style="color:var(--amber);font-weight:800">點我重試</a>;後端每日排程補齊後改走站內來源,即可秒開。</div>';
  },15000);
  if(s.market!=='TW'||s.etf||!/^\d{4}$/.test(s.id)){box.style.display='none';return;}
  box.style.display='';
  box.innerHTML=`<h3>📊 季報三率與營收 <span class="ds">近兩年</span></h3><div id="t3qSlot"></div>`;
  const slot=document.getElementById('t3qSlot');
  if(!slot)return;
  slot.innerHTML='<div class="dim-note" style="color:var(--dim)">📊 季報資料載入中…</div>';   // 保底:任何情況都不留純空白
  // 主源:後端 c/ 分片(每日排程以官方 OpenAPI 抓好 8 季三率,零代理、秒開、不看免費代理臉色)
  let backRows=[];                                       // r401:三源聯集——後端+瀏覽器快取+線上抓取,一季都不浪費
  try{
    const e=await loadChips(s);
    try{finQBlock(s,e);}catch(err){}
    try{finHealth(s,e);}catch(err){}   // r539:財報健檢(月營收+三率白話判讀)
    if(e&&Array.isArray(e.fq)&&e.fq.length){
      backRows=e.fq.map((q,i)=>({q,v:{gm:(e.gm||[])[i],om:(e.om||[])[i],nm:(e.nm||[])[i],rev:(e.qr||[])[i]??null}}))
        .filter(r=>[r.v.gm,r.v.om,r.v.nm].every(x=>x!=null&&isFinite(x)));
    }
  }catch(err){}
  {
    const map={};
    backRows.forEach(r=>{map[r.q]=r.v;});               // 後端優先(官方 OpenAPI)
    const qs=t3Qlist(t3QNow(),8);                       // 依申報時程列到最新可得季(如 2026Q1)
    const missing=[];
    qs.forEach(q=>{
      if(map[q])return;
      try{const c2=JSON.parse(localStorage.getItem('t3h_'+q)||'null');   // 瀏覽器7天快取,同步可得
        if(c2&&c2.exp>Date.now()&&c2.d&&c2.d[s.id]){map[q]=c2.d[s.id];return;}}catch(e2){}
      missing.push(q);
    });
    const paint=src=>{
      const rows=qs.map(q=>({q,v:map[q]||null}));
      if(rows.some(r=>r.v))t3RenderRows(s.id,rows,slot,src);
      return rows.some(r=>r.v);
    };
    const painted=paint(missing.length?'後端排程+本機快取(缺的季度背景補抓中…)':'本站後端每日排程・官方彙總');
    for(let i=0;i<missing.length;i++){                  // 背景逐季補抓缺的(不阻塞畫面)
      if(location.hash!==KHASH&&location.hash!=='#stock/'+s.id)break;
      const d2=await t3HistQ(missing[i]);
      if(d2&&d2[s.id])map[missing[i]]=d2[s.id];
    }
    const done=paint('後端排程+官方彙總(缺漏季已補抓)');
    try{                                                   // r701:把瀏覽器抓到的八季合回籌碼物件,重畫摘要橫幅(獲利體質/獲利外推不再「資料累積中」)
      const e2=(curChips&&curChips.e&&curChips.s&&curChips.s.id===s.id)?curChips.e:((CCACHE[chipShardOf(s.id)]||{})[s.id]||null);
      if(e2){
        const have=(e2.fq||[]).length;
        const rows2=qs.slice().reverse().map(q=>({q,v:map[q]})).filter(r=>r.v&&[r.v.gm,r.v.om,r.v.nm].every(x=>x!=null&&isFinite(x)));
        if(rows2.length>have){
          e2.fq=rows2.map(r=>r.q);
          e2.gm=rows2.map(r=>+r.v.gm);e2.om=rows2.map(r=>+r.v.om);e2.nm=rows2.map(r=>+r.v.nm);
          e2.qr=rows2.map(r=>r.v.rev!=null?+r.v.rev:null);
          try{fundAlertUI(s);}catch(x){}
        }
      }
    }catch(x){}
    if(!done&&!painted){
      slot.innerHTML='<div class="dim-note">季報資料源暫時連不上(官方與代理路徑皆未回應)——稍後重開此頁通常就好;後端每日排程補齊後將秒開。</div>';
    }
    return;
  }
  
  if(!slot.querySelector('table')&&rows1)               // 八季回補也失敗:至少把後端那1季擺回來
    t3RenderRows(s.id,rows1,slot,'本站後端每日排程・證交所/櫃買官方 OpenAPI(八季歷史回補中)');
}
function t3Render(items,note){
  const box=document.getElementById('t3Box');
  if(!box)return;
  if(note||!items.length){
    box.innerHTML=`<div class="r-card" style="cursor:default"><span class="r-desc">${note||'本季暫無同時符合「營收成長+三率齊揚」的個股(條件較嚴格,屬正常現象),財報陸續公布後會自動更新。'}</span></div>`;
    return;
  }
  const byId={};(DATA.stocks||[]).forEach(s=>byId[s.id]=s);
  const list=items.map(x=>({s:byId[x.id]||{id:x.id,name:x.id,chg:0,f:{score:50},c:{score:50},t:{score:50}},t3:x.t3}))
    .sort((a,b)=>total(b.s)-total(a.s));
  const arrow=(a,b)=>`${a.toFixed(1)}→<b style="color:var(--up)">${b.toFixed(1)}%</b>`;
  box.innerHTML=list.slice(0,24).map(({s,t3:t})=>
    `<div class="r-card" data-id="${s.id}" tabindex="0" role="button">
      <span class="r-tag tg-strong">三率三升 ${t.q}</span>
      <span class="r-name">${s.name} <span class="c-code">${s.id}</span> <b class="rpx">${s.price??'—'}</b> <span style="font-family:var(--mono);font-size:13px">${chgHtml(s.chg)}</span><span class="mini-candle" data-candle="${s.id}"></span><span class="c-code" style="flex:none">綜合 ${total(s)}</span></span>
      <span class="r-desc">毛 ${arrow(t.gm[0],t.gm[1])} · 營益 ${arrow(t.om[0],t.om[1])} · 淨利 ${arrow(t.nm[0],t.nm[1])}${t.ry!=null?` · 月營收 <b style="color:var(--up)">${t.ry>0?'+':''}${t.ry}%</b>`:''}
        <button class="t3-hist" data-sid="${s.id}" data-q="${t.q}" style="margin-left:8px;background:none;border:1px solid var(--line);border-radius:7px;color:var(--txt2);cursor:pointer;padding:2px 10px;font-size:12px">📊 兩年數據 ▾</button></span>
      <span class="t3-slot" style="display:block;width:100%"></span>
    </div>`).join('')
    +(list.length>24?`<div class="r-card" style="cursor:default;justify-content:center"><span class="r-desc">共 ${list.length} 檔符合,顯示綜合分前 24 名</span></div>`:'');
  box.querySelectorAll('[data-id]').forEach(c=>c.onclick=()=>{location.hash='#stock/'+c.dataset.id;});
  box.querySelectorAll('.t3-hist').forEach(b=>b.onclick=e=>{
    e.stopPropagation();
    const slot=b.closest('.r-card').querySelector('.t3-slot');
    if(slot.dataset.open){slot.dataset.open='';slot.innerHTML='';b.textContent='📊 兩年數據 ▾';return;}
    slot.dataset.open='1';b.textContent='📊 收合 ▴';
    t3HistShow(b.dataset.sid,b.dataset.q,slot);
  });
}
function renderT3(){
  if(!(DATA.stocks||[]).some(s=>s.t3)&&!(window.__T3||[]).length)t3Fallback();
  return;
  /* 以下舊碼保留不執行 */
  const box=document.getElementById('t3Box');
  if(!box)return;
  const list=(DATA.stocks||[]).filter(s=>s.t3).sort((a,b)=>total(b)-total(a));
  if(!list.length){
    t3Fallback();
    return;
  }
  const arrow=(a,b,u)=>`${a.toFixed(1)}→<b style="color:var(--up)">${b.toFixed(1)}${u||'%'}</b>`;
  box.innerHTML=list.slice(0,24).map(s=>{
    const t=s.t3;
    return `<div class="r-card" data-id="${s.id}" tabindex="0" role="button">
      <span class="r-tag tg-strong">三率三升 ${t.q}</span>
      <span class="r-name">${s.name} <span class="c-code">${s.id}</span> <b class="rpx">${s.price??'—'}</b> <span style="font-family:var(--mono);font-size:13px">${chgHtml(s.chg)}</span><span class="mini-candle" data-candle="${s.id}"></span><span class="c-code" style="flex:none">綜合 ${total(s)}</span></span>
      <span class="r-desc">毛 ${arrow(t.gm[0],t.gm[1])} · 營益 ${arrow(t.om[0],t.om[1])} · 淨利 ${arrow(t.nm[0],t.nm[1])}${t.ry!=null?` · 月營收 <b style="color:var(--up)">+${t.ry}%</b>`:''}</span>
    </div>`;}).join('')
    +(list.length>24?`<div class="r-card" style="cursor:default;justify-content:center"><span class="r-desc">共 ${list.length} 檔符合,顯示綜合分前 24 名;其餘可在選股清單搜尋</span></div>`:'');
  box.querySelectorAll('[data-id]').forEach(c=>c.onclick=()=>{location.hash='#stock/'+c.dataset.id;});
}

/* 📊 期貨籌碼先行指標表(近14個交易日,盤後資料) */
function renderFutTab(){
  const el=document.getElementById('futTab');
  if(!el)return;
  const rows=((DATA.macro||{}).futtab)||[];
  if(!rows.length){
    el.innerHTML='<div class="dim-note" style="border:1px dashed var(--line);border-radius:9px;padding:10px 12px">📊 期貨籌碼先行指標表(外資期OI・選擇權PCR・散戶多空比):將於下一次「每日資料更新」執行後出現(需 update_data.py r144+)。</div>';
    return;
  }
  const mono='font-family:var(--mono);text-align:right;padding:6px 8px;border-bottom:1px solid var(--line);white-space:nowrap';
  const num=(v,dec=0)=>v==null?'<span style="color:var(--dim)">—</span>':
    `<span class="${v>0?'pos':v<0?'neg':''}">${v>0?'+':''}${(+v).toLocaleString(undefined,{minimumFractionDigits:dec,maximumFractionDigits:dec})}</span>`;
  const plain=(v,dec=0,suf='')=>v==null?'<span style="color:var(--dim)">—</span>':((+v).toLocaleString(undefined,{maximumFractionDigits:dec})+suf);
  const H=['日期','成交值(億)','外資','投信','自營','外資期OI','前五大留倉','前十大留倉','選PCR','外(選)千元','韭菜%','大台總OI'];
  const hd=H.map(t=>`<div style="color:var(--mut);font-size:12px;padding:5px 8px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap">${t}</div>`).join('');
  const body=rows.map((r,i)=>{
    const last=i===rows.length-1;
    const bg=last?'background:var(--panel2);':'';
    const leek=r.leek==null?'<span style="color:var(--dim)">—</span>':
      `<b style="color:${r.leek>=15?'var(--amber)':r.leek<=0?'var(--dim)':'inherit'}">${r.leek.toFixed(1)}%</b>`;
    const pcr=r.pcr==null?'<span style="color:var(--dim)">—</span>':
      `<b style="color:${r.pcr>=120?'var(--amber)':'inherit'}">${r.pcr.toFixed(1)}</b>`;
    return `<div style="${mono};${bg}text-align:left;color:var(--txt2)">${r.d.slice(5).replace('-','/')}${last?' ★':''}</div>
      <div style="${mono};${bg}">${plain(r.amt,0)}</div>
      <div style="${mono};${bg}">${num(r.f,1)}</div>
      <div style="${mono};${bg}">${num(r.t,1)}</div>
      <div style="${mono};${bg}">${num(r.dl,1)}</div>
      <div style="${mono};${bg}">${num(r.txf)}</div>
      <div style="${mono};${bg}">${num(r.t5)}</div>
      <div style="${mono};${bg}">${num(r.t10)}</div>
      <div style="${mono};${bg}">${pcr}</div>
      <div style="${mono};${bg}">${num(r.txo)}</div>
      <div style="${mono};${bg}">${leek}</div>
      <div style="${mono};${bg}">${plain(r.oi)}</div>`;
  }).join('');
  el.innerHTML=`<div style="background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:10px 12px">
    <div style="font-size:13.5px;font-weight:900;color:var(--amber);letter-spacing:.05em;margin-bottom:6px">📊 期貨籌碼先行指標 <span style="font-weight:400;color:var(--dim);font-size:12px">近 ${rows.length} 個交易日・盤後資料</span></div>
    <div style="overflow-x:auto"><div style="display:grid;grid-template-columns:repeat(12,minmax(68px,auto));min-width:920px;font-size:13px">${hd}${body}</div></div>
    <div class="dim-note" style="margin-top:8px">現貨買賣超單位:億元;期OI/留倉:口(正=淨多、負=淨空);<b>外(選)</b>=外資選擇權未平倉淨契約金額(千元,買方−賣方)——外資慣做選擇權賣方收權利金,此值常態為負,重點看「增減方向」:負值快速擴大=避險/壓空加重;<b>前五大/前十大留倉</b>=買方最大5/10家合計−賣方最大5/10家合計(全月份・全部交易人)——市場最大咖的淨方向,常比外資總部位更早轉向;<b>選PCR</b> >100 通常偏多氛圍;<b>韭菜%</b>=小台散戶淨多單佔總未平倉比例——散戶越樂觀(數字越高)行情反轉風險越常抬頭,慣用作反指標。期交所盤後 15:00~16:30 陸續公布,本站每日排程自動抓,★=最新;「—」=該欄當日尚未公布或該來源尚在累積(隔日排程會自動補)。</div>
  </div>`;
}
/* ══ r738:指數即時快照層 —— data.json 重載會把 DATA.macro.idx 覆蓋回昨收,
      這層把最後一筆即時值記在 window 上,重畫前先蓋回去,畫面不再降級 ══ */
window.RTIDX=window.RTIDX||{};
function rtIdxSave(key,val,chg){
  if(!key||val==null||!isFinite(val))return;
  window.RTIDX[key]={val:+(+val).toFixed(2),chg:+chg,ts:Date.now()};
}
function rtIdxApply(){
  const list=((DATA.macro||{}).idx)||[];
  Object.keys(window.RTIDX).forEach(k=>{
    const r=window.RTIDX[k];if(!r||r.val==null)return;
    const it=list.find(x=>String(x.name||'').includes(k));
    if(it){it.val=r.val;if(r.chg!=null&&isFinite(r.chg))it.chg=r.chg;}
  });
}
function rtIdxStale(){          // 即時值超過 90 秒沒進來 → 卡片標出最後更新時刻
  const row=document.getElementById('idxRow');if(!row)return;
  const cards=[...row.querySelectorAll('.idx-card')];
  Object.keys(window.RTIDX).forEach(k=>{
    const r=window.RTIDX[k];if(!r||!r.ts)return;
    const card=cards.find(c=>String((c.querySelector('.nm')||{}).textContent||'').includes(k));
    if(!card)return;
    let tag=card.querySelector('.rt-age');
    if(Date.now()-r.ts>90000){
      if(!tag){tag=document.createElement('div');tag.className='rt-age';
        tag.style.cssText='font-size:10px;color:var(--dim);margin-top:2px;letter-spacing:.2px';
        card.appendChild(tag);}
      tag.textContent='\u23f1 '+new Date(r.ts).toLocaleTimeString('zh-TW',{hour12:false,timeZone:'Asia/Taipei'}).slice(0,5)+' \u5f8c\u672a\u66f4\u65b0';
    }else if(tag)tag.remove();
  });
}
function renderMacro(){
  try{rtIdxApply();}catch(e){}   // r738:先把即時值蓋回去,再重畫
  const m=DATA.macro||{};
  {                                                  // r701:跑馬燈等主執行緒閒下來再掛,首屏不跟它搶
    const go=()=>{try{tvTape();}catch(e){}};
    if('requestIdleCallback'in window)requestIdleCallback(go,{timeout:4000});
    else setTimeout(go,2500);
  }
  const _skipUS={gspc:1,ixic:1,dji:1,sox:1};   // 📺 美股四卡改 TradingView 即時小部件(見 ensureUsTvCards)
  const _cards=(m.idx||[]).map(i=>{
    const k=mkKeyIdx(i.name);
    if(k&&_skipUS[k])return '';
    return `<div class="idx-card"${k?` data-mk="${k}"`:''}><div class="nm">${i.name}</div><div class="vl">${Number(i.val).toLocaleString()}</div><div class="ch">${chgHtml(i.chg??0)}</div></div>`;}).filter(Boolean);
  document.getElementById('idxRow').innerHTML=_cards.length?_cards.join('')
    :'<div class="idx-card" id="idxEmpty"><div class="nm">台股指數載入中…</div></div>';
  try{ensureUsTvCards();}catch(e){}
  try{rtIdxStale();}catch(e){}   // r738
  const fx=m.fx||{};
  const items=[["美元/台幣","usdtwd","FX_IDC:USDTWD"],["日圓/台幣","jpytwd","FX_IDC:JPYTWD"],["美元指數(DXY 即時)","dxy","CAPITALCOM:DXY"]];   // r488:三卡改 TV 迷你即時卡(價+%+走勢線);Fed廣義序列保留在 dxy 詳細頁
  document.getElementById('fxRow').innerHTML=items.map(([n,k])=>
    `<div class="idx-card" style="position:relative;padding:10px 12px 8px"><div class="nm">${n}<span style="color:var(--dim)"> ›</span></div><div id="fxTv_${k}"><div class="dim-note" style="padding:10px 0">載入中…</div></div><div data-fxgo="${k}" style="position:absolute;inset:0;height:24px;cursor:pointer" title="點我看詳細"></div></div>`).join('');
  items.forEach(([n,k,tvs])=>{
    try{tvMiniQuote('fxTv_'+k,tvs);}catch(e){}
    const go=document.querySelector(`[data-fxgo="${k}"]`);
    if(go)go.onclick=()=>{location.hash='#macro/'+k;};
  });
  const tone=fx.USDTWD?(fx.USDTWD>=32.8?'台幣偏弱(外資匯出壓力,出口有匯兌收益但指數易承壓)':fx.USDTWD<=31.5?'台幣偏強(外資匯入,易走資金行情)':'台幣區間震盪'):null;
  window.__noteFx=tone?`匯率:美元/台幣 ${fx.USDTWD},<b>${tone}</b>。`:'';
  composeMacroNote();
  ensureOtcCard();
  renderFut();
  setTimeout(()=>{try{refreshUS();refreshFutCards();}catch(e){}},800);
}
function renderFut(){
  const row=document.getElementById('futRow');
  const f=DATA.macro&&DATA.macro.fut;
  if(!row)return;
  if(!f){return;}
  const oi=(v)=>`<span class="${v>=0?'pos':'neg'}" style="font-family:var(--mono);font-weight:700">${v>=0?'+':''}${Number(v).toLocaleString()}</span>`;
  const dl=(c)=>c==null?'':` <span class="${c>=0?'pos':'neg'}" style="font-size:12px">(${c>=0?'+':''}${Number(c).toLocaleString()})</span>`;
  const cards=[];
  (f.inst||[]).forEach(x=>cards.push(`<div class="idx-card" data-mk="fut"><div class="nm">${x[0]}期貨淨OI ›</div><div class="vl" style="font-size:17px">${oi(x[1])}${dl(x[2])}</div><div class="ch" style="color:var(--dim)">口(多正/空負)</div></div>`));
  if(f.pcr){   // r707:選擇權 P/C 未平倉比(>100 = Put OI 較多,常視為偏多氛圍)
    const p=f.pcr,tone=p.v>=110?'偏多':p.v<=90?'偏空':'中性';
    cards.push(`<div class="idx-card" data-mk="fut"><div class="nm">選擇權 P/C 比 ›</div><div class="vl" style="font-size:17px">${p.v}%<span class="${p.chg>=0?'pos':'neg'}" style="font-size:12px"> (${p.chg>=0?'+':''}${p.chg})</span></div><div class="ch" style="color:var(--dim)">未平倉比・${tone}</div></div>`);
  }
  if(f.big){
    cards.push(`<div class="idx-card" data-mk="fut"><div class="nm">十大交易人淨部位 ›</div><div class="vl" style="font-size:17px">${oi(f.big[0])}</div><div class="ch" style="color:var(--dim)">台指全月份</div></div>`);
    if(f.big[1]!=null)cards.push(`<div class="idx-card" data-mk="fut"><div class="nm">十大特定法人 ›</div><div class="vl" style="font-size:17px">${oi(f.big[1])}</div><div class="ch" style="color:var(--dim)">內含於十大</div></div>`);
  }
  if(f.ret)cards.push(`<div class="idx-card" data-mk="fut"><div class="nm">散戶小台淨部位 ›</div><div class="vl" style="font-size:17px">${oi(f.ret[0])}${dl(f.ret[1])}</div><div class="ch" style="color:var(--dim)">反向法人近似</div></div>`);
  if(cards.length)row.innerHTML=cards.join('');
}
/* 台指期夜盤 + 美股期貨動態(直連 Yahoo,60秒更新) */
const FUT_SYMS=[['台指期(參考EWT)','EWT','美掛台灣ETF,夜盤情緒參考'],['標普期貨','ES=F',''],['那指期貨','NQ=F','']];
async function refreshFutCards(){
  const row=document.getElementById('idxRow');
  if(!row)return;
  for(const [nm,sym,tip] of FUT_SYMS){
    let d=await yChart(sym,'1d','5m');
    if(!d||!d.c)continue;
    const last=[...d.c].reverse().find(x=>x!=null);
    if(!last||!d.prev)continue;
    const chg=+(((last-d.prev)/d.prev)*100).toFixed(2);
    let el=document.getElementById('fut_'+sym.replace(/[^A-Za-z]/g,''));
    if(!el){
      el=document.createElement('div');
      el.className='idx-card';
      el.id='fut_'+sym.replace(/[^A-Za-z]/g,'');
      el.dataset.mk={'EWT':'ewt','ES=F':'esf','NQ=F':'nqf'}[sym]||'';
      if(tip)el.title=tip;
      row.appendChild(el);
    }
    el.innerHTML=`<div class="nm">${nm}</div><div class="vl">${last>=100?Number(last.toFixed(0)).toLocaleString():last.toFixed(2)}</div><div class="ch">${chgHtml(chg)}</div>`;
  }
}
setTimeout(refreshFutCards,4000);
setInterval(()=>{if(!uiBusy())refreshFutCards();},60000);   // r719:防跳動
/* 美股大盤即時動態(直連 Yahoo,60秒;收盤時顯示最後收盤) */
const US_LIVE=[['^GSPC','gspc','S&P 500'],['^IXIC','ixic','那斯達克'],['^SOX','sox','費城半導體'],['^DJI','dji','道瓊工業']];
async function refreshUS(){
  // 📺 r382 起美股四卡由 refreshUsCards 自家渲染;本函式保留供 __usCache(詳情頁等)使用,usChg_ slot 已不存在(null 安全)
  window.__usCache=window.__usCache||{};
  for(const [sym,mk,nm] of US_LIVE){
    try{
      const d=await yChart(sym,'1d','5m');
      if(!d||!d.c)continue;
      const last=[...d.c].reverse().find(x=>x!=null);
      if(!last||!d.prev)continue;
      const chg=+(((last-d.prev)/d.prev)*100).toFixed(2);
      window.__usCache[mk]={last:+last.toFixed(2),chg};
      const slot=document.getElementById('usChg_'+mk);
      if(slot)slot.innerHTML=chgHtml(chg);
    }catch(e){}
  }
}
