/* 匯率即時化:Yahoo FX 直連(er-api 免費版一天一值,僅作開站底圖) */
async function refreshFX(){
  if(!window.DATA||!DATA.macro){return;}   // 🛡️ DATA 尚未載入(boot 未完成)→ 跳過,避免 null.macro 爆掉中斷渲染
  const fx=DATA.macro.fx;
  if(!fx)return;
  let hit=0;
  try{  // 匯率:open.er-api.com——免金鑰、原生 CORS、不經任何代理(約每小時更新)
    const r=await fT('https://open.er-api.com/v6/latest/USD',7000);
    if(r.ok){
      const j=await r.json();
      if(j&&j.rates&&j.rates.TWD){
        fx.USDTWD=+(+j.rates.TWD).toFixed(3);hit++;
        if(j.rates.JPY)fx.JPYTWD=+((+j.rates.TWD)/(+j.rates.JPY)).toFixed(4);
      }
    }
  }catch(e){}
  try{  // DXY:後端 yext.json(伺服器端抓,約20分鐘一更)
    const d=await yChart('DX-Y.NYB','1d','5m');
    if(d&&d.c){const last=[...d.c].reverse().find(x=>x!=null);if(last){fx.DXY=+(+last).toFixed(2);hit++;}}
  }catch(e){}
  window.__fxLive=hit>0;
  if(!location.hash)renderMacro();
}
setTimeout(refreshFX,5000);
setInterval(()=>{if(!uiBusy())refreshFX();},60000);   // r719:防跳動
