function tvMiniQuote(domId,tvsym){                     // r701:懶掛載修正——r701 在觀察器裡把旗標清掉又呼叫自己,
  try{                                                //      重入時又看到「未武裝」而再掛一次觀察器 → 永遠延後、卡在「載入中…」
    const host=document.getElementById(domId);         //      正解:觸發後直接呼叫 Now(),絕不重入本函式
    if(host&&'IntersectionObserver'in window&&!host.__tvArmed&&!host.__tvDone){
      const r=host.getBoundingClientRect();
      const near=r.top<innerHeight+300&&r.bottom>-300;  // 已在畫面內(或很近)就別繞路,立刻掛
      if(!near){
        host.__tvArmed=true;
        const io=new IntersectionObserver(es=>{
          if(es.some(e=>e.isIntersecting)){io.disconnect();host.__tvDone=true;tvMiniQuoteNow(domId,tvsym);}
        },{rootMargin:'300px'});
        io.observe(host);
        setTimeout(()=>{                                // 保險:3.5 秒後若仍未掛(容器隱藏/量測不到)就直接掛,寧可多載也不要空白
          try{ if(!host.__tvDone){io.disconnect();host.__tvDone=true;tvMiniQuoteNow(domId,tvsym);} }catch(x){}
        },3500);
        return;
      }
    }
    if(host)host.__tvDone=true;
  }catch(e){}
  return tvMiniQuoteNow(domId,tvsym);
}
