/* 🏷️ 卡片漲跌%徽章:TradingView 部分資料源在嵌入版不給漲跌值 → 用自家 yext.json 疊上,保證每張卡都有 % */
const CARD_PCT={copper:'HG=F',nickel:'NI=F',alum:'ALI=F',gold:'GC=F',silver:'SI=F',
  wti:'CL=F',brent:'BZ=F',natgas:'NG=F',
  gspc:'^GSPC',ixic:'^IXIC',dji:'^DJI',sox:'^SOX',         // r770:原本只列 ixic/dji,gspc 與 sox 漏了 → 那兩張卡永遠沒有漲跌%
  usdtwd:'TWD=X',jpytwd:'JPYTWD=X',dxy:'DX-Y.NYB'};
async function refreshCardPct(){
  if(!document.getElementById('usTvCards')&&!document.getElementById('cmdGrid')&&!document.getElementById('fxRow'))return;
  const j=await yextData();
  if(!j||!j.series)return;
  Object.entries(CARD_PCT).forEach(([mk,sym])=>{
    const host=document.getElementById('tvC_'+mk)||document.getElementById('tvCmd_'+mk)||document.getElementById('fxTv_'+mk);
    if(!host||!host.parentNode)return;
    const e=j.series[sym];
    if(!e)return;
    const src=e.m||e.d;
    if(!src||!Array.isArray(src.c)||!src.c.length)return;
    const last=[...src.c].reverse().find(x=>x!=null&&isFinite(+x));
    const prev=(src.prev>0?src.prev:null)??(e.d&&e.d.c&&e.d.c.length>1?e.d.c[e.d.c.length-2]:null);
    if(!(last>0&&prev>0))return;
    const chg=+((last-prev)/prev*100).toFixed(2);
    if(Math.abs(chg)>25)return;                       // 🛡 壞基準防呆
    const nm=host.parentNode.querySelector('.nm');
    if(!nm)return;
    let b=nm.querySelector('.card-pct');
    if(!b){
      b=document.createElement('span');b.className='card-pct';
      b.style.cssText='margin-left:auto;font-family:var(--mono);font-size:13px;font-weight:800;letter-spacing:0';
      nm.style.display='flex';nm.style.alignItems='center';nm.style.gap='5px';
      nm.appendChild(b);
    }
    b.innerHTML=chgHtml(chg);
    b.title=(e.m?'即時':'日線源(約15分鐘延遲)')+' · 對前收漲跌';
  });
}
setTimeout(()=>{try{refreshCardPct();}catch(e){}},2600);
