function ownCmdQuote(domId,ysym){       // 🧱 無免費 TV 嵌入源的商品(鋁):自家後端報價卡
  const box=document.getElementById(domId);
  if(!box)return;
  yextData().then(j=>{
    const e=j&&j.series&&j.series[ysym];
    const src=e&&(e.m||e.d);
    if(!src||!Array.isArray(src.c)||!src.c.length){
      box.innerHTML='<div class="dim-note" style="padding:22px 4px;color:var(--dim)">鋁無免費即時嵌入源——後端日線源回補中,稍後自動出現。</div>';
      return;
    }
    const last=[...src.c].reverse().find(x=>x!=null&&isFinite(+x));
    const prev=(src.prev>0?src.prev:null)??(src.c.length>1?src.c[src.c.length-2]:null);
    const chg=(last>0&&prev>0)?+((last-prev)/prev*100).toFixed(2):null;
    box.innerHTML=`<div style="padding:8px 2px 4px">
      <div class="vl" style="font-size:26px;font-weight:900;font-family:var(--mono)">${(+last).toLocaleString()}</div>
      <div class="ch" style="margin-top:2px">${chg!=null?chgHtml(chg):''}
        <span style="font-size:11.5px;color:var(--dim);margin-left:6px">COMEX 鋁 · 日線源約15分鐘延遲</span></div></div>`;
  });
}
