const US_CARD_SYM={gspc:'^GSPC',ixic:'^IXIC',dji:'^DJI',sox:'^SOX'};
async function refreshUsCards(){        // r487:已退役——四卡改 TradingView 迷你卡(tvMiniQuote),自帶即時串流
  return;
  if(!document.getElementById('usTvCards'))return;
  const j=await yextData();
  if(!j||!j.series)return;
  Object.entries(US_CARD_SYM).forEach(([mk,sym])=>{
    const host=document.getElementById('tvC_'+mk);
    if(!host)return;
    const e=j.series[sym],src=e&&(e.m||e.d);
    if(!src||!Array.isArray(src.c)||src.c.filter(x=>x!=null).length<2){
      host.innerHTML='<div class="dim-note" style="padding:10px 0">資料回補中…(後端每20分鐘更新)</div>';return;}
    const cs=src.c.filter(x=>x!=null&&isFinite(+x));
    const last=cs[cs.length-1];
    const prev=(src.prev>0?src.prev:null)??(e.d&&e.d.c&&e.d.c.length>1?e.d.c[e.d.c.length-2]:null);
    const chg=(prev>0)?+((last-prev)/prev*100).toFixed(2):null;
    const seq=cs.slice(-120);
    const mn=Math.min(...seq),mx=Math.max(...seq),rg=(mx-mn)||1;
    const W=220,H=42;
    const pts=seq.map((v,i)=>`${(i/(seq.length-1)*W).toFixed(1)},${(H-3-(v-mn)/rg*(H-8)).toFixed(1)}`).join(' ');
    const col=chg==null?'#97938A':chg>=0?CT.up2:CT.dn2;
    host.innerHTML=`<div style="display:flex;align-items:baseline;gap:8px;flex-wrap:wrap">
        <span class="vl" style="font-size:22px;font-weight:900;font-family:var(--mono)">${(+last).toLocaleString(undefined,{maximumFractionDigits:2})}</span>
        <span style="font-family:var(--mono);font-size:13.5px;font-weight:800">${chgHtml(chg)}</span></div>
      <svg viewBox="0 0 ${W} ${H}" style="width:100%;height:${H}px;display:block;margin-top:4px" preserveAspectRatio="none">
        <polyline points="${pts}" fill="none" stroke="${col}" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round"/>
      </svg>
      <div style="font-size:11px;color:var(--dim);margin-top:2px">${e.m?'當日走勢 · 即時':'日線走勢 · 日更'}</div>`;
  });
}
