function fhDetailLive(key,def){          // 指數詳情頁秒級層(約10秒一跳)
  if(!FH_ETF[key])return;
  const stat=document.getElementById('mkIntraStat');
  const hash=location.hash;
  if(!fhKey()){
    if(stat){
      stat.innerHTML='<a href="#" id="fhOn" style="color:var(--amber);text-decoration:none">⚡ 啟用秒級即時(免費金鑰)</a>';
      const a=document.getElementById('fhOn');
      if(a)a.onclick=e=>{e.preventDefault();
        const k=prompt('秒級即時設定:\n1. 到 finnhub.io 免費註冊(免綁卡,一分鐘)\n2. Dashboard 複製 API Key 貼到下面\n金鑰只存在這台裝置的瀏覽器;留空並確定=停用。');
        if(k===null)return;
        try{localStorage.setItem('fh_key',(k||'').trim());}catch(_){}
        if((k||'').trim())fhDetailLive(key,def);else if(stat)stat.textContent='';
      };
    }
    return;
  }
  const dg=def.dg??2;
  let miss=0;
  const tick=async()=>{
    if(location.hash!==hash)return;
    const r=await fhLiveIdx(key);
    if(location.hash!==hash)return;
    if(r&&!r.err){
      const px=document.getElementById('mkPx'),cg=document.getElementById('mkChg');
      if(r.val!=null&&px)px.textContent=Number(+r.val.toFixed(dg)).toLocaleString();
      if(cg)cg.innerHTML=chgHtml(r.chg)+' <span style="font-size:11px;color:var(--amber)">⚡ETF即時換算</span>';
      if(stat)stat.textContent='⚡ 秒級即時:'+FH_ETF[key][0]+' 換算,約10秒一跳';
      miss=0;
    }else{
      const er=r&&r.err;
      if(er==='盤前盤後無成交'){
        if(stat)stat.textContent='⚡ 即時層待命:美股未開盤(台北 21:30 開盤;夏令時間),開盤後自動開跳';
        miss=0;
      }else if(++miss>=2&&stat){
        stat.textContent='⚡ 即時層失敗:'+(er||'不明')
          +(String(er).includes('401')?'——金鑰無效,請檢查 finnhub 金鑰':
            String(er).includes('429')?'——本分鐘額度用盡,稍後自動恢復':'')
          +';圖表仍為站台20分鐘更新';
      }
    }
    setTimeout(tick,10000);
  };
  tick();
}
