/* ── 📜 頭部機率回測:滾動視窗跑七腳印,對照之後20日實際報酬 ── */
async function headBacktest(){
  const out=document.getElementById('headBtOut');
  const btn=document.getElementById('headBtBtn');
  if(!out)return;
  if(window.__headBt){paintHeadBt(window.__headBt);return;}
  if(btn)btn.textContent='回測中…';
  try{
    const y=await yextData();
    const dl=y&&y.series&&y.series['^TWII']&&y.series['^TWII'].dl;
    if(!dl||!dl.c||dl.c.length<400){
      out.innerHTML='<div class="dim-note">長期日K尚未就緒(後端下一班會建 3 年歷史檔),稍後再試。</div>';
      if(btn)btn.textContent='📜 回測驗證:機率 vs 之後20日實際表現(3年)';
      return;
    }
    const N=dl.c.length,WIN=130,FWD=20;
    const bks=[{t:'0~19%',lo:0,hi:20,r:[]},{t:'20~44%',lo:20,hi:45,r:[]},
               {t:'45~69%',lo:45,hi:70,r:[]},{t:'70%以上',lo:70,hi:101,r:[]}];
    for(let i=WIN;i<N-FWD;i++){
      const sl=k=>dl[k].slice(i-WIN,i);
      const hp=headprints({c:sl('c'),o:sl('o'),h:sl('h'),l:sl('l')});
      if(!hp)continue;
      const fwd=(dl.c[i+FWD]/dl.c[i-1]-1)*100;
      const b=bks.find(x=>hp.prob>=x.lo&&hp.prob<x.hi);
      if(b)b.r.push(fwd);
      if(i%120===0)await new Promise(r=>setTimeout(r,0));   // 讓出主執行緒,不卡UI
    }
    window.__headBt={ts:Date.now(),n:N,bks:bks.map(b=>({t:b.t,n:b.r.length,
      avg:b.r.length?+(b.r.reduce((a,x)=>a+x,0)/b.r.length).toFixed(2):null,
      dn:b.r.length?Math.round(b.r.filter(x=>x<0).length/b.r.length*100):null,
      worst:b.r.length?+Math.min(...b.r).toFixed(1):null}))};
    paintHeadBt(window.__headBt);
  }catch(e){out.innerHTML='<div class="dim-note">回測異常:'+String(e).slice(0,60)+'</div>';}
  if(btn)btn.textContent='📜 回測驗證:機率 vs 之後20日實際表現(3年)';
}
function paintHeadBt(bt){
  const out=document.getElementById('headBtOut');
  if(!out||!bt)return;
  const cell=v=>v==null?'—':`<span class="${v>0?'pos':v<0?'neg':'flat'}" style="font-weight:800">${v>0?'+':''}${v}%</span>`;
  out.innerHTML=`<div style="margin-top:10px;padding:11px 14px;background:var(--panel2);border-radius:10px">
    <b>📜 回測:頭部機率 → 加權指數之後 20 日表現</b><span style="color:var(--dim);font-size:12px">(樣本 ${bt.n} 個交易日,滾動 130 日視窗)</span>
    <div class="bt5" style="margin-top:8px">
      <div style="text-align:left;color:var(--mut)">機率區間</div><div style="color:var(--mut)">樣本日</div><div style="color:var(--mut)">平均報酬</div><div style="color:var(--mut)">下跌機率</div><div style="color:var(--mut)">最差一次</div>
      ${bt.bks.map(b=>`<div style="text-align:left;font-weight:800">${b.t}</div><div>${b.n}</div><div>${cell(b.avg)}</div><div>${b.dn==null?'—':b.dn+'%'}</div><div>${cell(b.worst)}</div>`).join('')}
    </div>
    <div class="dim-note" style="margin-top:7px">判讀:若高機率區間的「平均報酬更差、下跌機率更高」,代表模型有鑑別力;樣本重疊(逐日滾動)會高估顯著性,僅供權重校準參考,非交易保證。</div></div>`;
}
/* ── 🔍 全市場頭部掃描:每一檔台股跑七腳印,列出做頭名單與跡象 ── */
async function scanHeadAll(){
  const out=document.getElementById('headScanOut');
  const btn=document.getElementById('headScanBtn');
  if(!out)return;
  if(window.__headScan&&Date.now()-window.__headScan.ts<30*60*1000){paintHeadScan(window.__headScan);return;}
  if(btn)btn.textContent='掃描中…載入日K 0/10';
  const res=[];
  const stocks=(DATA.stocks||[]).filter(x=>x.market==='TW'&&!x.etf);
  const __ks=await shardList('k');let __i=0;
  for(const sh of __ks){
    const __k=sh.replace(/^k\/tw|\.json$/g,'');
    await loadShard(KCACHE,sh);
    if(btn)btn.textContent=`掃描中…載入日K ${++__i}/${__ks.length}`;
    stocks.filter(x=>twShardKey(x.id)===__k).forEach(x=>{
      const e=(KCACHE[sh]||{})[x.id];
      if(!e||!e.o||e.o.length<50)return;
      try{
        const K={o:e.o.map(b=>b[0]),h:e.o.map(b=>b[1]),l:e.o.map(b=>b[2]),c:e.o.map(b=>b[3])};
        const r2=headprints(K);
        if(r2)res.push({id:x.id,name:x.name||x.id,chg:x.chg,front:r2.front,back:r2.back,prob:r2.prob,
          lit:r2.S.map(v=>v.on?1:0),s4:r2.S[3].on?1:0,tone:r2.tone});
      }catch(err){}
    });
    await new Promise(r=>setTimeout(r,60));
  }
  const scan={ts:Date.now(),n:res.length,res};
  window.__headScan=scan;
  if(btn)btn.textContent='🔍 重新掃描全市場個股頭部';
  renderHeadMacro();          // 重畫整區:指數機率會吃到市場廣度加成,名單由快取直接重繪
}
function paintHeadScan(scan){
  const out=document.getElementById('headScanOut');
  if(!out||!scan)return;
  try{window.__ptIds=new Set(portGet().map(p=>p.id));}catch(e){window.__ptIds=new Set();}
  const res=scan.res;
  if(!res.length){out.innerHTML='<div class="dim-note">日K資料尚未就緒,稍後再掃。</div>';return;}
  const pct=k=>Math.round(res.filter(x=>x[k]).length/res.length*100);
  const s4p=pct('s4'),bear=res.filter(x=>x.back>=3),conf=res.filter(x=>x.s4&&x.back>=1&&x.back<3),
        warn=res.filter(x=>!x.s4&&x.front>=2);
  const chip=x=>x.lit.map((v,i)=>`<span style="display:inline-block;width:17px;height:17px;line-height:17px;text-align:center;border-radius:4px;font-size:11px;font-weight:800;margin-right:2px;${v?`background:${i<3?TONE.orange:TONE.red};color:#fff`:'background:var(--panel2);color:var(--dim)'}">${i+1}</span>`).join('');
  const row=x=>`<div class="earn-row" data-hs="${x.id}" style="cursor:pointer;padding:8px 12px;margin:6px 0;display:flex;flex-wrap:wrap;gap:6px 12px;align-items:center">
    <b style="min-width:96px">${(window.__ptIds&&window.__ptIds.has(x.id))?'💼 ':''}${x.name} <span style="color:var(--dim);font-weight:400">${x.id}</span></b>
    <span>${chip(x)}</span>
    <span data-hspx="${x.id}" style="font-family:var(--mono);font-size:12.5px;color:var(--mut)"></span>
    <span style="font-family:var(--mono);font-size:13px;font-weight:800;color:${x.prob>=70?TONE.red:x.prob>=45?TONE.orange:'var(--mut)'}">${x.prob}%</span></div>`;
  const grp=(t,arr,cap)=>arr.length?`<div class="earn-sub" style="margin-top:12px">${t}(${arr.length} 檔)</div>`
    +arr.sort((a,b)=>(b.prob-a.prob)||(b.back-a.back)).slice(0,cap).map(row).join('')
    +(arr.length>cap?`<div class="dim-note">…僅列前 ${cap} 檔(依亮燈數排序)</div>`:''):'';
  out.innerHTML=`
    <div style="margin-top:10px;padding:10px 13px;background:var(--panel2);border-radius:10px">
      <b>市場廣度</b>:全市場 ${scan.n} 檔中,<b style="color:var(--t-red)">${s4p}%</b> 已跌破末升低(第4步質變)
      ——${s4p>=50?'半數以上個股多頭骨架已鬆動,大盤頭部風險偏高':s4p>=30?'質變比例升溫,結構轉弱中':'多數個股結構仍健康'}。掃描時間:${new Date(scan.ts).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'})}
    </div>
    ${grp('🟥 空頭浪確立(後段≥3燈)',bear,30)}
    ${grp('🟠 頭部確認進行中(已破末升低)',conf,30)}
    ${grp('🟡 前段警告區(警告早但不可靠)',warn,20)}
    <div class="dim-note" style="margin-top:8px">燈號=七腳印:①背離 ②缺口不補 ③破趨勢線 ④破末升低 ⑤反彈不創高 ⑥再破前低 ⑦空頭浪。點任一列進該股個股頁看完整判讀。</div>`;
  out.querySelectorAll('[data-hs]').forEach(el=>{el.onclick=()=>{location.hash='#stock/'+el.dataset.hs;};});
}

const FOLD_CFG=[
  ['boxHead7',()=>{const h=window.__headStkC;return h?`機率 ${h.prob}% · ${h.trend}`:'點開看七步檢核';}],
  ['boxTurn',()=>{const t=window.__turnStkC&&window.__turnStkC.r;
    if(!t)return '點開看節奏與價位';
    let leg=t.upLeg?'上漲段':'下跌段';                       // r701:徽章反映結構狀態——ZigZag 未確認新轉折前,價格已破壞結構就要說實話
    try{
      const pocket=t.near&&t.near[2]&&t.near[2].px;
      if(t.upLeg&&t.px<t.legBase)leg='<b>上漲段結構已破・轉折進行中</b>';
      else if(t.upLeg&&pocket&&t.px<pocket)leg='上漲段・<b>已破黃金口袋</b>';
      else if(!t.upLeg&&t.px>t.legBase)leg='<b>下跌段結構已破・轉折進行中</b>';
      else if(!t.upLeg&&pocket&&t.px>pocket)leg='下跌段・<b>已突破黃金口袋</b>';
    }catch(x){}
    return `${leg} · ${t.due?'已達轉折週期⚠':`轉折窗 ${Math.max(0,t.winLo)}~${t.winHi} 日`}`;}],
  ['turtleBox',()=>'點開看進出檢核'],
  ['zt8Box',()=>'點開看八招檢核'],
  ['gemBox',()=>'點開看蓄勢診斷']];
function foldSync(){                          // r582:摘要徽章即時重刷——轉折循環每次重算後同步(原本只在佈線時渲染一次)
  FOLD_CFG.forEach(([id,sf])=>{
    try{
      const box=document.getElementById(id);
      const sum=box&&box.querySelector('.fold-sum');
      if(sum){const t=sf();if(t&&sum.innerHTML!==t)sum.innerHTML=t;}   // r753:摘要含 <b> 強調,textContent 會把標籤當文字印出來
    }catch(e){}
  });
}
function foldInit(){                          // 📦 分析卡收合:標題列顯示一行摘要,點開才看細節
  FOLD_CFG.forEach(([id,sf])=>{
    try{
      const box=document.getElementById(id);
      if(!box||box.dataset.foldWired)return;
      const h3=box.querySelector('h3');
      if(!h3)return;
      box.dataset.foldWired='1';
      const body=document.createElement('div');
      body.className='fold-body';
      while(h3.nextSibling)body.appendChild(h3.nextSibling);
      box.appendChild(body);
      const key='kfold_'+id;
      const closed=localStorage.getItem(key)!=='0';
      const arw=document.createElement('span');
      arw.className='fold-arw';arw.textContent=closed?'▸':'▾';
      h3.insertBefore(arw,h3.firstChild);
      const sum=document.createElement('span');
      sum.className='fold-sum';
      h3.appendChild(sum);
      body.style.display=closed?'none':'';
      h3.style.cursor='pointer';h3.title='點我展開/收合';
      h3.onclick=()=>{
        const c=body.style.display==='none';
        body.style.display=c?'':'none';
        arw.textContent=c?'▾':'▸';
        localStorage.setItem(key,c?'0':'1');
        if(c)try{box.querySelectorAll('canvas,div[_echarts_instance_]').forEach(el=>{const ch=echarts.getInstanceByDom(el);if(ch)ch.resize();});}catch(e){}
      };
      box.__foldSum=sf;
    }catch(e){}
  });
  foldSync();
}
setInterval(()=>{                             // 摘要即時更新(機率/轉折窗算好後自動補上)
  FOLD_CFG.forEach(([id])=>{
    try{
      const box=document.getElementById(id);
      if(!box||!box.__foldSum)return;
      const el=box.querySelector('.fold-sum');
      if(!el)return;
      const t=box.__foldSum();
      if(t&&el.innerHTML!==t)el.innerHTML=t;                          // r753:同上
    }catch(e){}
  });
},2500);

async function renderHeadStock(s){
  const box=document.getElementById('headStk');
  if(!box||!s)return;
  try{
    const sh=shardOf(s);
    await loadShard(KCACHE,sh);
    const e=withLiveBar((KCACHE[sh]||{})[s.id],s);         // r701:頭部機率以盤中價評
    if(!e||!e.o||e.o.length<50){box.innerHTML='<div class="dim-note">日K資料不足(需50根以上),此檔暫無法判讀。</div>';return;}
    const K={o:e.o.map(x=>x[0]),h:e.o.map(x=>x[1]),l:e.o.map(x=>x[2]),c:e.o.map(x=>x[3])};
    const hp=headprints(K);
    window.__headStkC={id:s.id,prob:hp.prob,trend:hp.trend};   // 快取:警示條重繪時由 renderStkAlerts 自帶
    box.innerHTML=headHtml(hp,s.name||s.id);
    try{                                                    // 頁首警示條:目前趨勢常駐;頭部機率≥50%升級警告
      const al=document.getElementById('stkAlerts');
      if(al&&hp&&location.hash==='#stock/'+s.id&&!al.querySelector('[data-hd]')){
        const lv=hp.prob>=70?'red':hp.prob>=50?'amb':'ok';
        const pill=document.createElement('span');
        pill.className='alert-pill alert-'+lv;pill.dataset.hd='1';
        pill.style.cursor='pointer';pill.title='點我看七腳印完整判讀';
        pill.innerHTML=`<span class="ico">${hp.prob>=50?'🔺':'📈'}</span><span>趨勢:${hp.trend} · 頭部機率 ${hp.prob}%${hp.prob>=70?'——證據齊備,紀律減碼/停損':hp.prob>=50?'——做頭風險偏高,反彈視為減碼機會':''}</span>`;
        pill.onclick=()=>{try{document.getElementById('headStk').scrollIntoView({behavior:'smooth',block:'center'});}catch(e){}};
        const ok=al.querySelector('.alert-ok');
        if(ok&&lv!=='ok')ok.remove();                       // 有警告時把「無警示」拿掉
        al.style.display='';al.prepend(pill);
      }
    }catch(e){}
  }catch(err){box.innerHTML='<div class="dim-note">判讀引擎異常:'+String(err).slice(0,60)+'</div>';}
}


/* ══ 🌡️ 市場溫度區:台股恐貪(站內合成)+量能溫度計+台積電RS+類股輪動 ══ */

async function mtRateCard(){                 // 🧮 融資維持率估算:融資增量加權成本法(非官方,趨勢參考)
  const box=document.getElementById('mtCard');
  if(!box)return;
  try{
    const cr=(DATA.macro||{}).credit;
    const y=await yextData();
    const dd=y&&y.series&&y.series['^TWII']&&y.series['^TWII'].d;
    if(!cr||!cr.h||!cr.h.d||!dd||!dd.c){box.style.display='none';return;}
    const idxMap={};
    (dd.t||[]).forEach((ts,i)=>{idxMap[tpDay(ts)]=dd.c[i];});
    const D=cr.h.d,F=cr.h.fin;
    let cost=0,sh=0;
    for(let i=1;i<D.length;i++){
      const df=(F[i]??0)-(F[i-1]??0),ix=idxMap[D[i]];
      if(df>0&&ix){cost+=df*ix;sh+=df;}
    }
    const idxNow=dd.c[dd.c.length-1];
    if(!(sh>0&&idxNow)){box.style.display='none';return;}
    const mt=Math.round(166*idxNow/(cost/sh));
    window.__mtRate=mt;
    const st=mt<130?['追繳風暴區',TONE.red,'融資戶大面積跌破維持率,斷頭賣壓隨時引爆——多殺多加速器']:
             mt<140?['斷頭邊緣',TONE.red,'再跌一段就進入追繳潮,反彈也容易被融資賣壓壓回']:
             mt<155?['偏低警戒',TONE.orange,'融資戶普遍套牢,大跌日留意斷頭賣壓放大跌勢']:
             ['安全區',TONE.green,'融資戶整體有緩衝,斷頭連鎖風險低'];
    box.style.display='';
    box.innerHTML=`<div class="nm">大盤融資維持率(估算)${frBadge('day')}</div>
      <div style="display:flex;align-items:baseline;gap:9px"><b style="font-size:27px;font-family:var(--mono);color:${st[1]}">${mt}%</b><b style="color:${st[1]};font-size:15px">${st[0]}</b></div>
      <div style="font-size:11.5px;color:var(--dim);margin-top:4px;line-height:1.55">${st[2]}</div>
      <div style="font-size:10.5px;color:var(--dim);margin-top:3px">站內以「融資增量×當日指數」加權成本估算(初始166%),非官方數字,看趨勢與區間即可;130% 為追繳線。</div>`;
    try{renderMacroAlerts();}catch(e){}
  }catch(e){box.style.display='none';}
}
setTimeout(mtRateCard,6800);setInterval(mtRateCard,1800000);


/* ══ 📌 下週關注五檔:兩階段規則化選股(綜合評分+籌碼 → K線技術+頭部排雷) ══ */
async function weeklyPicks(){
  const box=document.getElementById('pickBox');
  if(!box)return;
  try{
    const ttl=(typeof marketOpen==='function'&&marketOpen())?5*60*1000:30*60*1000;   // 盤中5分鐘重算
    if(window.__picks&&Date.now()-window.__picks.ts<ttl){paintPicks(window.__picks);return;}
    // 第一階段(r701 改版):漲停體質粗篩——投機動能+籌碼認養為主;「穩健績優」反而不是這裡要的
    const cand=[];
    (DATA.stocks||[]).forEach(x=>{
      if(x.market!=='TW'||x.etf||x.disp||!x.price||x.price<10||x.chg==null||x.chg>=9)return;
      const sc=(x.c&&x.c.score)||0;
      if(sc<40)return;                                     // 底線防雷,不再用高分當主軸
      const r=chipRaw(x);
      let pts=sc*0.35,why=[];
      if(r.t5!=null&&r.t5>0){pts+=10;why.push('投信5日買超');}          // 投信認養=漲停常客的第一籌碼特徵
      if(r.bigw!=null&&r.bigw>=0.5){pts+=9;why.push(`大戶週增 +${r.bigw}pp`);}
      if(r.f5!=null&&r.f5>0){pts+=5;why.push('外資5日買超');}
      if(x.dtp!=null&&x.dtp>=30&&x.dtp<60){pts+=7;why.push(`當沖熱度 ${x.dtp}%`);}   // 漲停需要投機盤;過熱(≥60)有處置風險不加
      if(+x.price<=120)pts+=4;                             // 低價慣性:漲停頻率統計上偏高
      cand.push({s:x,pts,why});
    });
    cand.sort((a,b)=>b.pts-a.pts);
    const top=cand.slice(0,60);
    if(top.length<5){box.style.display='none';return;}
    // 第二階段:載入候選的日K,做技術確認與頭部排雷
    const shards=[...new Set(top.map(c=>`k/tw${twShardKey(c.s.id)}.json`))];
    for(const sh of shards){
      await loadShard(KCACHE,sh);
    }
    const final=[];
    for(const c of top){
      const e=(KCACHE[`k/tw${twShardKey(c.s.id)}.json`]||{})[c.s.id];
      if(!e||!e.o||e.o.length<50)continue;
      const cl=e.o.map(b=>b[3]),hi=e.o.map(b=>b[1]);
      const px=c.s.price,ma20=cl.slice(-20).reduce((a,b)=>a+b,0)/20;
      const bias=(px/ma20-1)*100;
      if(bias>12)continue;                                // 過熱不追
      let pts=c.pts,why=[...c.why];
      const hp=headprints({o:e.o.map(b=>b[0]),h:hi,l:e.o.map(b=>b[2]),c:cl});
      if(hp){
        if(hp.prob>=50)continue;                          // 頭部排雷照舊
        if(hp.prob>=35)pts-=8;
      }
      // ① 漲停慣性(最強單一因子):近一年單日漲幅 ≥9% 的次數——會漲停的股票才會再漲停
      let lim=0;
      for(let i=1;i<cl.length;i++)if(cl[i-1]>0&&(cl[i]/cl[i-1]-1)*100>=9)lim++;
      if(lim>=5){pts+=16;why.unshift(`近一年漲停 ${lim} 次`);}
      else if(lim>=2){pts+=10;why.unshift(`近一年漲停 ${lim} 次`);}
      else if(lim===1){pts+=4;why.unshift('近一年漲停 1 次');}
      else pts-=10;                                       // 一年零漲停的牛皮體質,下週突然漲停機率極低
      // ② 波動體質:牛皮股直接大扣
      const rets=[];for(let i=1;i<cl.length;i++)if(cl[i-1]>0)rets.push((cl[i]/cl[i-1]-1)*100);
      const mu=rets.reduce((a,b)=>a+b,0)/rets.length;
      const volA=Math.sqrt(rets.reduce((a,b)=>a+(b-mu)*(b-mu),0)/rets.length)*Math.sqrt(252);
      if(volA>=45)pts+=6;else if(volA<28)pts-=10;
      // ③ 量能升溫:5日均量 vs 20日均量
      const V=e.o.map(b=>b[4]||0);
      const v5=V.slice(-5).reduce((a,b)=>a+b,0)/5,v20=V.slice(-20).reduce((a,b)=>a+b,0)/20;
      if(v20>0&&v5/v20>=1.3){pts+=8;why.push(`量能升溫 ${(v5/v20).toFixed(1)}×`);}
      else if(v20>0&&v5/v20<0.7)pts-=5;
      // ④ 蓄勢位置:距 20 日高 ≤3%(引爆點就在頭上)或剛創高
      const h20=Math.max(...hi.slice(-21,-1));
      const gap=(h20/px-1)*100;
      if(Math.max(...hi.slice(-3))>=h20){pts+=7;why.push('剛創20日新高');}
      else if(gap<=3&&gap>=0){pts+=8;why.push(`距20日高僅 ${gap.toFixed(1)}%`);}
      if(bias>=0&&bias<=8)pts+=3;
      else if(bias<0)pts-=6;
      final.push({id:c.s.id,name:c.s.name||c.s.id,sector:c.s.sector||'',price:px,chg:c.s.chg,
        pts,why:why.slice(0,4),prob:hp?hp.prob:null});
    }
    final.sort((a,b)=>b.pts-a.pts);
    const picks=[],secN={};
    for(const f of final){                                // 產業多樣性:每產業最多2檔
      if((secN[f.sector]||0)>=2)continue;
      secN[f.sector]=(secN[f.sector]||0)+1;
      picks.push(f);
      if(picks.length>=5)break;
    }
    if(picks.length<3){box.style.display='none';return;}
    window.__picks={ts:Date.now(),picks};
    paintPicks(window.__picks);
  }catch(e){box.style.display='none';}
}
function paintPicks(p){
  const box=document.getElementById('pickBox');
  if(!box||!p)return;
  const wd=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Taipei'})).getDay();
  const title=(wd===5||wd===6||wd===0)?'下週漲停潛力五檔':'近期漲停潛力五檔';
  const medal=['🥇','🥈','🥉','4','5'];
  box.style.display='';
  const stamp=new Date(p.ts).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'});
  const _gmh=(window.GMKT==='US')?' gm-hide':'';   // r545:台股專屬區,美股模式渲染即隱藏(重繪也不會冒出)
  box.innerHTML=`<div class="sec-title tap${_gmh}" data-sec="mk_pick">🚀 ${title} <span style="font-weight:400;font-size:13px;letter-spacing:0">規則化雙階段篩選・報價即時・榜單盤中每5分鐘重算(${stamp})</span></div>
  <div class="sec-body${_gmh}" id="sb-mk_pick">
    <div class="pick-grid">
      ${p.picks.map((x,i)=>`<div class="pick-card" data-pk="${x.id}">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:5px">
          <span class="pick-medal">${medal[i]}</span>
          <b style="font-size:16px">${x.name}</b>
          <span style="color:var(--dim);font-family:var(--mono)">${x.id}</span>
          <span class="pick-sec">${x.sector}</span>
          <span style="margin-left:auto;font-family:var(--mono);font-weight:800" data-ppx="${x.id}">${(+x.price).toLocaleString()}</span>
          <span data-pch="${x.id}">${chgHtml(+x.chg)}</span>
        </div>
        <div style="display:flex;flex-wrap:wrap;gap:5px">${x.why.map(w=>`<span class="pick-chip">${w}</span>`).join('')}</div>
      </div>`).join('')}
    </div>
    <div class="dim-note" style="margin-top:8px">篩選邏輯(漲停體質模型):<b>漲停慣性</b>(近一年漲停次數,最強因子——會漲停的才會再漲停)+ 投信認養/大戶週增 + 當沖熱度 + 量能升溫 + 蓄勢位置(距20日高≤3%)+ 高波動體質;排除處置股、乖離>12% 已噴段、頭部機率≥50%。每產業至多2檔。<b>漲停是極端事件,本榜找的是「具備漲停體質且站在引爆位置」的候選,不是預言,非投資建議</b>;點卡片進個股頁看股性分析與防守價位。</div>
  </div>`;
  box.querySelectorAll('[data-pk]').forEach(el=>{el.onclick=()=>{location.hash='#stock/'+el.dataset.pk;};});
  try{wireTapSecs&&wireTapSecs(box);}catch(e){}
}
lazyRun('#pickBox',weeklyPicks,5*60*1000);               // r701                       // 盤中每5分鐘檢查是否重算(快取壽命內直接沿用)
setInterval(()=>{                                          // 📶 報價即時:6秒把最新價/漲跌同步到卡片(不重算榜單)
  try{
    const _n=new Date(),_h=_n.getHours()+_n.getMinutes()/60;
    if(!((typeof marketOpen==='function'&&marketOpen())||_h>=21.4||_h<5.2))return;   // r474:台股盤中或美股時段才同步,收盤後不空轉
    if(document.hidden)return;                             // r513:分頁隱藏休眠
    if(!document.querySelector('[data-ppx],[data-pch],[data-hspx]'))return;   // r473:修「被 pickBox 綁架」——最愛頁/任何頁有標記就同步
    document.querySelectorAll('[data-ppx]').forEach(el=>{   // r465:全頁即時同步(最愛/清單/所有卡片)
      const st=(DATA.stocks||[]).find(x=>x.id===el.dataset.ppx);
      if(!st||!st.price)return;
      const t=(+st.price).toLocaleString();
      if(el.textContent!==t){el.textContent=t;
        el.style.transition='color .3s';el.style.color='var(--amber)';
        setTimeout(()=>{el.style.color='';},350);}          // 價格變動閃一下,看得見「活著」
    });
    document.querySelectorAll('[data-pch]').forEach(ch=>{
      const st=(DATA.stocks||[]).find(x=>x.id===ch.dataset.pch);
      if(st&&st.chg!=null)ch.innerHTML=chgHtml(+st.chg);
    });
    document.querySelectorAll('[data-hspx]').forEach(el=>{      // 頭部掃描/持股體檢:現價+漲跌同步
      const st=(DATA.stocks||[]).find(x=>x.id===el.dataset.hspx);
      if(!st||st.price==null)return;
      const t=`${(+st.price).toLocaleString()} ${st.chg>0?'+':''}${st.chg}%`;
      if(el.textContent!==t){el.textContent=t;el.style.color=st.chg>0?'var(--up)':st.chg<0?'var(--down)':'var(--mut)';}
    });
  }catch(e){}
},3000);   // r511:全頁報價同步 3 秒一拍(純DOM零請求)


function frBadge(kind){                     // 資料時點徽章:讓每張卡都標明即時/延遲/日更
  const m={live:['即時',TONE.green],min20:['20分鐘',TONE.gold],day:['日更·收盤後',TONE.grey],mix:['盤中估算',TONE.green]};
  const v=m[kind]||m.day;
  return `<span style="font-size:10px;font-weight:800;color:${v[1]};border:1px solid ${v[1]}55;border-radius:5px;padding:1px 6px;margin-left:6px;vertical-align:1.5px">${v[0]}</span>`;
}


/* ══ 🌏 亞洲股市:日經225・韓國KOSPI・香港恆生(收盤日線;台股開盤前的亞股風向) ══ */

async function asiaChart(sym,host){          // 🌏 亞股 60 日日K(點卡展開;有OHLC畫K棒,否則畫線)
  try{
    const y=await yextData();
    const d=((y&&y.series||{})[sym]||{}).d;
    if(!d||!d.c)return;
    let el=host.querySelector('.asia-k');
    if(!el){el=document.createElement('div');el.className='asia-k';
      el.style.cssText='height:200px;margin-top:8px';host.insertBefore(el,host.firstChild);}
    const ok=await ensureECharts();
    if(!ok){el.innerHTML='<div class="dim-note">圖表引擎載入失敗</div>';return;}
    const n=d.c.length,S=Math.max(0,n-60);
    const xs=(d.t||[]).slice(S).map(t=>new Date(t*1000).toLocaleDateString('zh-TW',{month:'numeric',day:'numeric'}));
    const hasK=Array.isArray(d.o)&&Array.isArray(d.h)&&Array.isArray(d.l)&&d.o.length===n;
    const ch=echarts.init(el);
    (window.__asiaCh=window.__asiaCh||[]).push(ch);
    const ser=hasK
      ?{type:'candlestick',data:d.c.slice(S).map((c2,i)=>[d.o[S+i],c2,d.l[S+i],d.h[S+i]]),
        itemStyle:{color:CT.up2,color0:CT.dn2,borderColor:CT.up2,borderColor0:CT.dn2}}
      :{type:'line',data:d.c.slice(S),showSymbol:false,lineStyle:{width:2,color:'#8A6D3B'},
        areaStyle:{color:'rgba(138,109,59,.14)'}};
    const ma=(p)=>d.c.slice(S).map((_,i)=>{const j=S+i;if(j<p-1)return null;
      let t=0;for(let k2=0;k2<p;k2++)t+=d.c[j-k2];return +(t/p).toFixed(1);});
    ch.setOption({animation:false,grid:{left:8,right:8,top:14,bottom:22,containLabel:true},
      tooltip:{trigger:'axis'},
      xAxis:{type:'category',data:xs,axisLabel:{fontSize:10,color:TONE.grey}},
      yAxis:{scale:true,axisLabel:{fontSize:10,color:TONE.grey},splitLine:{lineStyle:{opacity:.35}}},
      series:[ser,
        {type:'line',name:'MA5',data:ma(5),showSymbol:false,lineStyle:{width:1,color:TONE.orange}},
        {type:'line',name:'MA20',data:ma(20),showSymbol:false,lineStyle:{width:1,color:TONE.blue}}]});
    setTimeout(()=>{try{ch.resize();}catch(e){}},120);
  }catch(e){}
}


async function asiaDetail(sym,host){          // 🌏 亞股詳細:全寬K線+均線+統計+白話說明(等同大盤詳情規格)
  const NM={'^N225':['日經 225','🇯🇵','日本'],'^KS11':['韓國 KOSPI','🇰🇷','韓國'],'^HSI':['香港恆生','🇭🇰','香港']}[sym]||['指數','',''];
  host.innerHTML='<div class="dim-note" style="padding:16px">載入中…</div>';
  try{
    const y=await yextData();
    const d=((y&&y.series||{})[sym]||{}).d;
    if(!d||!d.c||d.c.length<20){host.innerHTML='<div class="dim-note" style="padding:16px">此市場資料尚未回補——下一班資料更新後自動出現。</div>';return;}
    const c=d.c,n=c.length,px=c[n-1];
    const ch1=(c[n-1]/c[n-2]-1)*100;
    const st=(p)=>n>p?((px/c[n-1-p]-1)*100):null;
    const ma=(p)=>{if(n<p)return null;let t=0;for(let i=0;i<p;i++)t+=c[n-1-i];return t/p;};
    const m20=ma(20),m60=ma(60);
    const hi=Math.max(...c.slice(-60)),lo=Math.min(...c.slice(-60));
    const posR=((px-lo)/((hi-lo)||1)*100);
    const f=(v,dg)=>v==null?'—':(+v).toLocaleString(undefined,{maximumFractionDigits:dg==null?0:dg});
    const pct=v=>v==null?'—':`<b class="${v>0?'pos':v<0?'neg':'flat'}">${v>0?'+':''}${v.toFixed(2)}%</b>`;
    host.innerHTML=`
      <div style="display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:8px">
        <b style="font-size:19px">${NM[1]} ${NM[0]}</b>
        <b style="font-family:var(--mono);font-size:22px">${f(px)}</b>${pct(ch1)}
        <a href="javascript:void 0" onclick="const h=document.getElementById('asiaDetail');h.style.display='none';h.dataset.sym='';" style="margin-left:auto;color:var(--dim);font-size:13px">收合 ×</a></div>
      <div class="earn-metrics" style="grid-template-columns:repeat(auto-fit,minmax(120px,1fr))">
        <div class="em-card"><div class="em-v ${st(5)>0?'pos':'neg'}">${st(5)!=null?(st(5)>0?'+':'')+st(5).toFixed(1)+'%':'—'}</div><div class="em-l">近 5 日</div></div>
        <div class="em-card"><div class="em-v ${st(20)>0?'pos':'neg'}">${st(20)!=null?(st(20)>0?'+':'')+st(20).toFixed(1)+'%':'—'}</div><div class="em-l">近 20 日(月)</div></div>
        <div class="em-card"><div class="em-v ${st(60)>0?'pos':'neg'}">${st(60)!=null?(st(60)>0?'+':'')+st(60).toFixed(1)+'%':'—'}</div><div class="em-l">近 60 日(季)</div></div>
        <div class="em-card"><div class="em-v flat" style="font-size:16px;padding-top:5px">${f(m20)}</div><div class="em-l">月線(20MA)${px>m20?' · 站上':' · 跌破'}</div></div>
        <div class="em-card"><div class="em-v flat" style="font-size:16px;padding-top:5px">${f(m60)}</div><div class="em-l">季線(60MA)${px>m60?' · 站上':' · 跌破'}</div></div>
        <div class="em-card"><div class="em-v flat">${posR.toFixed(0)}%</div><div class="em-l">位於近60日高低區間</div></div>
      </div>
      <div id="asiaBigK" style="height:${innerWidth<640?260:340}px;margin-top:10px"></div>
      <div class="dim-note" style="margin-top:8px;line-height:1.75">
        <b>怎麼看</b>:${NM[2]}股市與台股同屬亞洲時區,收盤時間相近,常同步反映外資對亞洲資產的態度——${NM[2]}股大跌時台股隔日容易承壓,反之亦然。<br>
        <b>目前結構</b>:指數${px>m20?'站上':'跌破'}月線、${px>m60?'站上':'跌破'}季線,位於近 60 日高低區間的 ${posR.toFixed(0)}% 位置(0%=區間最低、100%=區間最高)。${m20&&m60?(m20>m60?'月線在季線之上,中期結構偏多。':'月線在季線之下,中期結構偏空。'):''}<br>
        <b>資料說明</b>:官方收盤價(FRED／Stooq),<u>盤中不跳動</u>;圖為近 120 日日K與 MA5／MA20。`;
    const ok=await ensureECharts();
    const el=document.getElementById('asiaBigK');
    if(!ok||!el)return;
    const S=Math.max(0,n-120);
    const xs=(d.t||[]).slice(S).map(t=>new Date(t*1000).toLocaleDateString('zh-TW',{month:'numeric',day:'numeric'}));
    const hasK=Array.isArray(d.o)&&Array.isArray(d.h)&&Array.isArray(d.l)&&d.o.length===n;
    const mline=p=>c.slice(S).map((_,i)=>{const j=S+i;if(j<p-1)return null;let t=0;for(let k=0;k<p;k++)t+=c[j-k];return +(t/p).toFixed(1);});
    const chart=echarts.init(el);
    chart.setOption({animation:false,grid:{left:8,right:10,top:16,bottom:26,containLabel:true},
      tooltip:{trigger:'axis'},legend:{show:true,top:0,textStyle:{fontSize:11}},
      dataZoom:[{type:'inside'},{type:'slider',height:16,bottom:2}],
      xAxis:{type:'category',data:xs,axisLabel:{fontSize:10,color:TONE.grey}},
      yAxis:{scale:true,axisLabel:{fontSize:10,color:TONE.grey},splitLine:{lineStyle:{opacity:.35}}},
      series:[hasK
        ?{name:'K線',type:'candlestick',data:c.slice(S).map((c2,i)=>[d.o[S+i],c2,d.l[S+i],d.h[S+i]]),
          itemStyle:{color:CT.up2,color0:CT.dn2,borderColor:CT.up2,borderColor0:CT.dn2}}
        :{name:'收盤',type:'line',data:c.slice(S),showSymbol:false,lineStyle:{width:2,color:'#8A6D3B'},areaStyle:{color:'rgba(138,109,59,.14)'}},
        {name:'MA5',type:'line',data:mline(5),showSymbol:false,lineStyle:{width:1.2,color:TONE.orange}},
        {name:'MA20',type:'line',data:mline(20),showSymbol:false,lineStyle:{width:1.2,color:TONE.blue}}]});
    setTimeout(()=>{try{chart.resize();}catch(e){}},120);
  }catch(e){host.innerHTML='<div class="dim-note" style="padding:16px">載入失敗:'+String(e).slice(0,60)+'</div>';}
}

