function tldrCard(){
  const box=document.getElementById('tldrBox');
  if(!box)return;
  try{
    const L=[];const M=(DATA.macro||{});
    // 1 大盤現況
    try{
      const iw=(IDX.misD&&IDX.misD.tw)||null;
      const st=window.__idxStat&&window.__idxStat.tw;
      const pc=(iw&&iw.c&&iw.c.length&&iw.prev)?((iw.c[iw.c.length-1]/iw.prev-1)*100):null;
      if(pc!=null)L.push(['📊','大盤',`加權指數${pc>0?'上漲':pc<0?'下跌':'持平'} <b class="${pc>0?'pos':pc<0?'neg':'flat'}">${pc>0?'+':''}${pc.toFixed(2)}%</b>`
        +(Math.abs(pc)>=1.5?`,波動偏大,今天不是適合追價的日子。`:Math.abs(pc)<0.3?`,幾乎平盤,方向不明時多看少做。`:`。`)]);
    }catch(e){}
    // 2 內部結構(廣度)
    try{
      const tw=(DATA.stocks||[]).filter(x=>x.market==='TW'&&!x.etf&&typeof x.chg==='number');
      if(tw.length>500){
        const up=tw.filter(x=>x.chg>0).length,r=Math.round(up/tw.length*100);
        L.push(['🔎','市場內部',`全市場 <b>${r}%</b> 的股票上漲(${up}/${tw.length} 檔)——`
          +(r>=65?'普漲格局,個股容易賺錢。':r>=45?'漲跌互見,選股比選市場重要。':r>=30?'多數股票在跌,想買要更挑剔。':'幾乎全面下跌,現金為王、勿接刀。')]);
      }
    }catch(e){}
    // 3 頭部風險
    try{
      const hs=Object.values(window.__headIdx||{});
      if(hs.length){
        const t=hs[0];
        L.push(['🔺','做頭風險',`${t.nm}目前<b>${t.trend}</b>,頭部機率 <b>${t.prob}%</b>——`
          +(t.prob>=70?'證據齊備,手上有股票該考慮減碼,別跟趨勢作對。':t.prob>=50?'風險偏高,反彈當作減碼機會,不要越跌越買。':t.prob>=25?'有零星警訊,續抱可以但要設好停損。':'結構健康,回檔通常是機會不是危機。')]);
      }
    }catch(e){}
    // 4 法人動向
    try{
      const iv=window.__instCur;
      if(iv&&iv.f!=null){
        const tot=iv.f+iv.t+iv.d;
        L.push(['🏦','法人',`外資${iv.f>0?'買超':'賣超'} <b class="${iv.f>0?'pos':'neg'}">${Math.abs(iv.f)}億</b>、投信${iv.t>0?'買超':'賣超'} ${Math.abs(iv.t)}億——`
          +(tot>200?'法人整體站在買方,盤面有支撐。':tot<-200?'法人整體站在賣方,反彈易被壓回。':'法人買賣接近平衡,盤面缺乏主力方向。')]);
      }
    }catch(e){}
    // 5 情緒溫度
    try{
      const h=JSON.parse(localStorage.getItem('twfng_h')||'[]');
      if(h.length){const v=h[h.length-1].s;
        L.push(['🌡','市場情緒',`台股恐懼貪婪指數 <b>${v}</b>(${v<25?'極度恐懼':v<45?'恐懼':v<=55?'中性':v<=75?'貪婪':'極度貪婪'})——`
          +(v<25?'人人恐慌時通常是長線買點,但別一次全押。':v<45?'氣氛偏冷,分批布局的時機。':v<=55?'情緒中性,順著趨勢操作即可。':v<=75?'市場偏樂觀,追高要小心。':'過熱區,別在這時候重倉進場。')]);}
    }catch(e){}
    // 6 亞股/夜盤(明日線索)
    try{
      const nf=window.__nightFut;
      if(nf&&nf.sprd!=null)L.push(['🌙','明日線索',`台指夜盤 ${(+nf.px).toLocaleString()},與現貨價差 <b class="${nf.sprd>0?'pos':'neg'}">${nf.sprd>0?'+':''}${nf.sprd}%</b>——`
        +(nf.sprd>0.3?'夜盤偏強,明天開盤有機會開高。':nf.sprd<-0.3?'夜盤偏弱,明天開盤要提防開低。':'夜盤持平,明天大致延續今天氣氛。')]);
    }catch(e){}
    // 7 今日焦點族群
    try{
      const g={};
      (DATA.stocks||[]).forEach(x=>{if(x.market!=='TW'||x.etf||!x.sector||x.chg==null)return;(g[x.sector]=g[x.sector]||[]).push(+x.chg);});
      const rows=Object.entries(g).filter(([k,v])=>v.length>=5)
        .map(([k,v])=>({k,avg:v.reduce((a,b)=>a+b,0)/v.length})).sort((a,b)=>b.avg-a.avg);
      if(rows.length>=3)L.push(['🔥','資金往哪去',`今天最強是 <b>${rows[0].k}</b>(${rows[0].avg>0?'+':''}${rows[0].avg.toFixed(2)}%),最弱是 <b>${rows[rows.length-1].k}</b>(${rows[rows.length-1].avg.toFixed(2)}%)——資金流向強勢族群時,弱勢股常繼續弱,別急著抄底。`]);
    }catch(e){}
    if(L.length<2){box.style.display='none';return;}
    box.style.display='';
    box.innerHTML=`<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px">
        <b style="font-size:17px">🧭 今日市場懶人包</b>
        <span style="font-size:12px;color:var(--dim)">白話翻譯・${new Date().toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'})} 自動更新</span></div>
      ${L.map(([ic,t,d])=>`<div style="display:flex;gap:10px;padding:7px 0;border-bottom:1px dashed var(--line);line-height:1.6">
        <span style="font-size:17px;flex-shrink:0">${ic}</span>
        <div style="font-size:14.5px"><b style="color:var(--txt2)">${t}</b>:${d}</div></div>`).join('')}
      <div class="dim-note" style="margin-top:8px">以上由站內各引擎自動翻成白話,方便快速掌握全局;每個結論在下方都有對應的圖表與數據可以深入查看。非投資建議。</div>`;
  }catch(e){box.style.display='none';}
}
setTimeout(tldrCard,7200);
setInterval(tldrCard,120000);

async function twFngCard(){
  const box=document.getElementById('twFng');
  if(!box)return;
  try{
    const comp=[];
    let liveN=0;
    try{                                                  // 🔴 即時因子:當下全市場上漲家數比(隨報價輪詢跳動)
      const tw=(DATA.stocks||[]).filter(x=>x.market==='TW'&&!x.etf&&typeof x.chg==='number');
      if(tw.length>500){
        const upR=tw.filter(x=>x.chg>0).length/tw.length*100;
        comp.push(['即時漲跌家數',Math.round(upR)]);liveN++;
      }
    }catch(e){}
    const bd=(DATA.macro||{}).breadth;
    if(bd&&bd.a60&&bd.a60.length)comp.push(['市場廣度',Math.round(Math.max(0,Math.min(100,bd.a60[bd.a60.length-1])))]);
    const pc=(DATA.macro||{}).pcr;
    if(pc&&pc.oi&&pc.oi.length>=20){const cur=pc.oi[pc.oi.length-1];
      const rank=pc.oi.filter(v=>v<=cur).length/pc.oi.length*100;
      comp.push(['選擇權情緒',Math.round(100-rank)]);}
    const cr=(DATA.macro||{}).credit;
    if(cr&&cr.h&&cr.h.fin&&cr.h.fin.filter(x=>x!=null).length>=6){
      const f=cr.h.fin.filter(x=>x!=null);
      const chg5=(f[f.length-1]/f[f.length-6]-1)*100;
      comp.push(['融資動能',Math.round(Math.max(0,Math.min(100,50+chg5*25)))]);}
    const fp=((DATA.macro||{}).fut||{}).fxPct;
    if(fp&&fp.pct!=null)comp.push(['外資期貨',fp.pct]);
    try{const y=await yextData();const vx=y&&y.series&&y.series['^VIX'];const src=vx&&(vx.m||vx.d);
      if(src&&src.c&&src.c.length){const v=[...src.c].reverse().find(x=>x>0);
        if(v)comp.push(['VIX外溢',Math.round(Math.max(0,Math.min(100,100-(v-10)*5)))]);}}catch(e){}
    if(comp.length<3){box.style.display='none';return;}
    const sc=Math.round(comp.reduce((a,x)=>a+x[1],0)/comp.length);
    let histTxt='';
    try{                                                  // 每日快照 → 昨/週對照
      const today=tpDay(Date.now()/1000);
      let h=JSON.parse(localStorage.getItem('twfng_h')||'[]');
      if(!h.length||h[h.length-1].d!==today)h.push({d:today,s:sc});
      else h[h.length-1].s=sc;
      h=h.slice(-15);
      localStorage.setItem('twfng_h',JSON.stringify(h));
      const yv=h.length>=2?h[h.length-2].s:null;
      const wv=h.length>=6?h[h.length-6].s:null;
      const dlt=yv!=null?sc-yv:null;
      histTxt=`${yv!=null?`昨 ${yv}`:''}${wv!=null?` · 週 ${wv}`:''}${dlt!=null?` · ${dlt>0?'升溫 +'+dlt:dlt<0?'降溫 '+dlt:'持平'}`:''}`;
    }catch(e){}
    const lab=sc<25?'極度恐懼':sc<45?'恐懼':sc<=55?'中性':sc<=75?'貪婪':'極度貪婪';
    const col=sc<25?TONE.green:sc<45?'#2E8B57':sc<=55?TONE.gold:sc<=75?TONE.orange:TONE.red;
    box.style.display='';
    box.innerHTML=`<div class="nm">台股恐懼貪婪(站內合成)${frBadge(liveN?'mix':'day')}</div>
      <div style="display:flex;align-items:baseline;gap:9px;flex-wrap:wrap"><b style="font-size:30px;font-family:var(--mono);color:${col}">${sc}</b><b style="color:${col};font-size:15px">${lab}</b><span style="font-size:12px;color:var(--dim)">${histTxt}</span></div>
      <div style="height:7px;background:linear-gradient(90deg,var(--t-green),var(--t-gold),var(--t-red));border-radius:4px;position:relative;margin:6px 2px 8px">
        <div style="position:absolute;left:calc(${sc}% - 2px);top:-3px;width:4px;height:13px;background:var(--txt);border-radius:2px;box-shadow:0 0 0 1.5px var(--panel)"></div></div>
      <div style="font-size:11px;color:var(--dim);line-height:1.55">${comp.map(x=>`${x[0]} ${x[1]}`).join(' · ')}(0=極恐,100=極貪)${liveN?' · 含即時因子,盤中跟著報價變動':' · 收盤後日更因子'}</div>
      <div style="font-size:11px;color:var(--dim);margin-top:3px">情緒是溫度計不是進出訊號;極端值請配合頭部七腳印與防守線使用。</div>`;
  }catch(e){box.style.display='none';}
}
