async function volTempCard(){
  const box=document.getElementById('volTemp');
  if(!box)return;
  try{
    const y=await yextData();
    const tv=y&&y.series&&y.series.TWVOL;
    if(!tv||!tv.amt||tv.amt.length<10){box.style.display='none';return;}
    const hist=tv.amt;
    const avg20=hist.slice(-20).reduce((a,b)=>a+b,0)/Math.min(20,hist.length);
    let cur=hist[hist.length-1],tag='最新交易日',accV=null,accT='';
    const now=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Taipei'}));
    const mins=now.getHours()*60+now.getMinutes()-540;
    if(typeof RT!=='undefined'&&RT.t00v>0&&now.getDay()>=1&&now.getDay()<=5&&mins>0&&mins<270){
      const pct=cumPct(mins);
      accV=RT.t00v;
      accT=now.toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'});
      cur=RT.t00v/(pct/100);
      tag=`盤中預估(時間進度 ${pct.toFixed(0)}%)`;
    }
    const r=cur/avg20*100;
    const st=r>=130?['爆量',TONE.red,'資金洶湧——漲=攻擊有燃料;跌=出貨疑慮,盯緊防線']:
             r>=105?['量增',TONE.orange,'人氣回溫,方向表態日']:
             r>=80?['正常','var(--txt2)','量能中性,順著趨勢看']:
             ['量縮',TONE.green,'觀望氣氛——跌時=殺盤力道漸竭;漲時=續航力存疑'];
    box.style.display='';
    box.innerHTML=`<div class="nm">大盤量能溫度計${frBadge(tag.indexOf('盤中')>=0?'mix':'day')}</div>
      ${(()=>{const ydv=(tag.indexOf('盤中')>=0)?hist[hist.length-1]:(hist.length>=2?hist[hist.length-2]:null);
        const yd=ydv?((cur/ydv-1)*100):null;window.__twVolYd=yd;
        return `<div style="display:flex;align-items:baseline;gap:9px;flex-wrap:wrap"><b style="font-size:27px;font-family:var(--mono);color:${st[1]}">${r.toFixed(0)}%</b><b style="color:${st[1]};font-size:15px">${st[0]}</b>
        ${yd!=null?`<span style="font-family:var(--mono);font-size:13px;color:${yd>=0?'var(--down)':'var(--up)'}">(較昨日 ${yd>0?'+':''}${yd.toFixed(0)}%)</span>`:''}</div>
      <div style="font-size:12px;color:var(--mut);margin-top:3px">上市:${accV!=null
        ?`今累計 <b style="color:var(--txt)">${accV.toFixed(0)} 億</b>(${accT}) → 預估全日 <b>${cur.toFixed(0)} 億</b>`
        :`${tag} <b>${cur.toFixed(0)} 億</b>`} · 昨日 ${ydv?ydv.toFixed(0):'—'} 億 · 20日均 ${avg20.toFixed(0)} 億</div>`;})()}
      ${(()=>{try{
        const tp=y.series&&y.series.TPEXVOL;
        if(!tp||!tp.amt||tp.amt.length<10)return '';
        const oa=tp.amt, oavg=oa.slice(-20).reduce((a,b)=>a+b,0)/Math.min(20,oa.length);
        const ocur=oa[oa.length-1], oyd=oa.length>=2?oa[oa.length-2]:null;
        const od=oyd?((ocur/oyd-1)*100):null;
        return `<div style="font-size:12px;color:var(--mut);margin-top:2px">櫃買:最新交易日 <b>${ocur.toFixed(0)} 億</b> · 昨日 ${oyd?oyd.toFixed(0):'—'} 億 ${od!=null?`<span style="font-family:var(--mono);color:${od>=0?'var(--down)':'var(--up)'}">(較昨日 ${od>0?'+':''}${od.toFixed(0)}%)</span>`:''} · 20日均 ${oavg.toFixed(0)} 億</div>`;
      }catch(e2){return '';}})()}
      <div style="font-size:11.5px;color:var(--dim);margin-top:4px;line-height:1.5">${st[2]}</div>`;
  }catch(e){box.style.display='none';}
}
setTimeout(volTempCard,6000);setInterval(volTempCard,60000);
async function rsCard(){
  const box=document.getElementById('rsCard');
  if(!box)return;
  try{
    const y=await yextData();
    const dd=y&&y.series&&y.series['^TWII']&&y.series['^TWII'].d;
    if(!dd||!dd.c||dd.c.length<40){box.style.display='none';return;}
    const sh='k/tw23.json';
    await loadShard(KCACHE,sh);
    const e=(KCACHE[sh]||{})['2330'];
    if(!e||!e.o||e.o.length<40){box.style.display='none';return;}
    const n=Math.min(60,e.o.length,dd.c.length);
    const tsm=e.o.slice(-n).map(b=>b[3]),idx=dd.c.slice(-n);
    let liveRS=false;
    try{                                                  // 盤中:用即時台積電價與即時指數補上今日點
      const st=(DATA.stocks||[]).find(x=>x.id==='2330');
      const ixNow=(window.IDX&&IDX.misD&&IDX.misD.tw&&IDX.misD.tw.c&&IDX.misD.tw.c.length)
        ?IDX.misD.tw.c[IDX.misD.tw.c.length-1]:null;
      if(typeof marketOpen==='function'&&marketOpen()&&st&&st.price&&ixNow){
        tsm.push(+st.price);idx.push(+ixNow);liveRS=true;
      }
    }catch(e){}
    const norm=tsm.map((v,i)=>v/idx[i]/(tsm[0]/idx[0])*100);
    const nn=norm.length;
    const mn=Math.min(...norm),mx=Math.max(...norm),rg=(mx-mn)||1;
    const W=210,H=38;
    const pts=norm.map((v,i)=>`${(i/(nn-1)*W).toFixed(1)},${(H-3-(v-mn)/rg*(H-6)).toFixed(1)}`).join(' ');
    const sl=norm[nn-1]-norm[Math.max(0,nn-11)];
    const up=sl>0.8,dn=sl<-0.8,col=up?CT.up2:dn?CT.dn2:'#97938A';
    box.style.display='';box.style.cursor='pointer';
    box.title='點我看台積電個股頁';
    box.innerHTML=`<div class="nm">台積電 vs 大盤(相對強弱 RS) ›${frBadge(liveRS?'live':'day')}</div>
      <svg viewBox="0 0 ${W} ${H}" style="width:100%;height:${H}px;display:block;margin:5px 0 3px" preserveAspectRatio="none"><polyline points="${pts}" fill="none" stroke="${col}" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>
      <div style="font-size:12.5px;line-height:1.55"><b style="color:${col}">${up?'龍頭走強於大盤':dn?'龍頭弱於大盤':'與大盤同步'}</b><span style="color:var(--dim)"> — ${dn?'權值龍頭轉弱常領先大盤做頭1~2週,提高警戒':up?'龍頭領軍,指數結構相對安全':'近10日無明顯偏離'}</span></div>`;
    box.onclick=()=>{location.hash='#stock/2330';};
  }catch(e){box.style.display='none';}
}
