let OTC_CH='otc_o00.tw';           // 櫃買指數 MIS 頻道(開站自動探測)
let OTC_OK=false;                   // MIS 是否成功回過櫃買報價
async function otcBase(){           // 櫃買官方基準值(TPEX OpenAPI 直連)
  if(window.__otcBase)return window.__otcBase;
  try{
    const r=await fT('https://www.tpex.org.tw/openapi/v1/tpex_mainboard_highlight',10000);
    if(r.ok){
      const j=await r.json();
      const row=Array.isArray(j)?j[0]:j;
      if(row){
        const kIdx=Object.keys(row).find(k=>k.includes('指數'));
        const v=parseFloat(String(row[kIdx]||'').replace(/,/g,''));
        if(v>0)return window.__otcBase={close:v};
      }
    }
  }catch(e){}
  return null;
}
async function otcApproxTick(){     // MIS 不通時:006201 ETF 即時 × 官方基準換算
  if(OTC_OK||!marketOpen())return;
  const base=await otcBase();
  if(!base)return;
  for(const sym of ['006201.TWO','006201.TW']){
    const d=await yChart(sym,'1d','1m')||await yChart(sym,'1d','5m');
    if(d&&d.prev&&d.c){
      const lastE=[...d.c].reverse().find(x=>x!=null);
      if(!lastE)continue;
      const val=+(base.close*lastE/d.prev).toFixed(2);
      const chg=+(((lastE-d.prev)/d.prev)*100).toFixed(2);
      IDX.last.otc=val;
      ensureOtcCard();
      const v=document.getElementById('otcVal'),c2=document.getElementById('otcChg');
      if(v)v.textContent='≈'+Number(val).toLocaleString();
      if(c2)c2.innerHTML=chgHtml(chg);
      if(IDX.sel==='otc')paintDefense();
      return;
    }
  }
}
