async function refreshIdxMis(){
  window.__idxDiag=window.__idxDiag||{};
  window.__idxDiag.run=new Date().toLocaleTimeString('zh-TW',{hour12:false});   // r486:執行證據——有跑必留時間戳
  try{await Promise.race([idxBoot(),new Promise(r=>setTimeout(r,4000))]);}catch(e){}   // r486:探測上限4秒,夜間休眠不陪葬
  IDX.misD=IDX.misD||{};
  for(const key of ['tw','otc']){
    try{
      window.__idxDiag[key]='執行中…';                  // r486:先寫再做——之後任何一步炸掉都看得到卡在哪
      const ch=key==='tw'?'tse_t00.tw':(typeof OTC_CH!=='undefined'&&OTC_CH?OTC_CH:null);
      const acc=accOf(key);
      // 昨收基準:MIS 累積的 y → idxBoot 存的 → 即時報價現問 → yext 備援
      let prev=acc.prev||(key==='otc'&&IDX.mis&&IDX.mis.prev)||null;
      if(!prev){
        try{const arr=await fetchMIS([ch]);const m=(arr||[])[0],y=m&&parseFloat(m.y);
            if(y>0){prev=y;if(!acc.prev)acc.prev=y;}}catch(e){}
      }
      if(!prev&&IDX.d[key]&&IDX.d[key].prev)prev=IDX.d[key].prev;
      window.__idxDiag=window.__idxDiag||{};
      if(!prev){window.__idxDiag[key]='無昨收基準';continue;}
      let d=ch?await misOhlcCore(ch,prev):null;
      if(!ch)window.__idxDiag[key]='頻道未探測(夜間MIS休眠)→改走備援';
      let via='MIS全日';
      if((!d||d.c.length<5)&&key==='tw'){d=await twse5sIdx(prev);via='官方5秒';}   // 加權第二備援:證交所官方端點
      if((!d||d.c.length<5)&&key==='otc'){
        // 櫃買第三備援:MIS 個股端點對 ETF 是通的 → 006201 富櫃50 全日分線 × 指數比例換算
        try{
          let ey=null;
          try{const ea=await fetchMIS(['otc_006201.tw']);const em=(ea||[])[0],y2=em&&parseFloat(em.y);
              if(y2>0)ey=y2;}catch(e){}
          if(ey){
            const ed=await misOhlcCore('otc_006201.tw',ey);
            if(ed&&ed.c&&ed.c.length>=5){
              const rr=prev/ey;
              d={t:ed.t,c:ed.c.map(x=>x==null?null:+(x*rr).toFixed(2)),v:ed.v,
                 prev:+(+prev).toFixed(2),approx:true};
              via='ETF換算';
            }
          }
        }catch(e){}
      }
      if(d&&d.c&&d.c.length>=5){
        // 🛡️ 驗證這份全日分線最後一點真的是今天(交易日初期官方端點常回「最近交易日=上週五」的完整檔)
        const lastTs=Array.isArray(d.t)&&d.t.length?d.t[d.t.length-1]:0;
        const isToday=lastTs&&tpDay(lastTs)===sessDay();
        if(!isToday&&marketOpen()){
          // 盤中卻拿到非今日分線 → 不採用(交給 idxPick 走即時累積),避免昨日線覆蓋今日
          window.__idxDiag[key]=via+'(非今日·略過 '+(lastTs?tpDay(lastTs):'?')+')';
          if(IDX.sel===key)drawIdxSel();               // 觸發改用即時累積重畫
        }else{
          window.__idxDiag[key]=via+' '+d.c.length+'點';
          const old=IDX.misD[key];
          IDX.misD[key]=Object.assign(d,{day:isToday?sessDay():tpDay(lastTs),via});
          if(!old||old.c.length!==d.c.length){         // 有新點才重畫,避免無謂閃動
            if(IDX.sel===key)drawIdxSel();
            if(window.__mkMis===key&&location.hash.startsWith('#macro/'))drawMkLive(key);
          }
        }
      }else{
        let fixed=false;
        try{                                              // 🐦 富果指數頻道救援:加權 IX0001 / 櫃買 IX0043
          const sym=key==='tw'?'IX0001':key==='otc'?'IX0043':null;
          if(sym){
            const fd=await fglCandles(sym,true);
            if(fd&&fd.c.length>=2&&tpDay(fd.t[fd.t.length-1])===sessDay()){
              window.__idxDiag[key]='富果 '+fd.c.length+'點';
              IDX.misD[key]=Object.assign({t:fd.t.map(_nrmT),c:fd.c,v:Array.isArray(fd.v)?fd.v:fd.c.map(()=>0),   // r480/r514:漏v防彈+時間域正規化(富果+8h域與spark/MIS真實域混排=左側8小時空白的真因)
                prev:(IDX.misD[key]||{}).prev||null},{day:sessDay(),via:'富果'});
              if(IDX.sel===key)drawIdxSel();
              if(window.__mkMis===key&&location.hash.startsWith('#macro/'))drawMkLive(key);
              fixed=true;
            }
          }
        }catch(e2){}
        if(!fixed){                                    // r515:全滅前先掏 localStorage 快取(最近一次成功回補的完整一日)
          try{
            const sv=JSON.parse(localStorage.getItem('idxmis_'+key)||'null');
            if(sv&&Array.isArray(sv.t)&&sv.t.length>5&&!marketOpen()){
              IDX.misD[key]=sv;fixed=true;
              window.__idxDiag[key]='快取 '+String(sv.day||'').slice(5)+' '+sv.t.length+'點';
            }
          }catch(e){}
        }
        if(!fixed)window.__idxDiag[key]=(window.__idxDiag[key]&&window.__idxDiag[key].includes('點'))?window.__idxDiag[key]:'回補失敗(端點/代理均不通)';
        try{const m9=IDX.misD[key];                      // r515:任何來源成功都持久化,供盤外快取還原
          if(m9&&Array.isArray(m9.c)&&m9.c.length>5&&m9.day)
            localStorage.setItem('idxmis_'+key,JSON.stringify({t:m9.t,c:m9.c,v:m9.v||[],prev:m9.prev||null,day:m9.day,via:(m9.via||'')+'・快取'}));
        }catch(e){}
      }
    }catch(e){try{window.__idxDiag[key]='例外:'+String(e).slice(0,70);}catch(_){}}   // r486:例外浮上檯面
  }
  try{updIdxDiagBar();}catch(e){}
  try{if(IDX.sel==='tw'||IDX.sel==='otc')drawIdxSel();}catch(e){}   // r486:回補完成即重畫當前分頁
}
