/* 櫃買分線第三備援:上櫃 ETF(006201)分線 × 指數比例換算(ETF 追蹤指數,形狀一致) */
async function otcFromETF(){
  await idxBoot();
  if(!IDX.mis||!IDX.mis.prev)return null;
  for(const sym of ['006201.TWO','006201.TW']){
    const etf=await yChart(sym,'1d','1m')||await yChart(sym,'1d','5m');
    if(etf&&etf.prev&&etf.c&&etf.c.some(x=>x!=null)){
      const r=IDX.mis.prev/etf.prev;
      return {t:etf.t,c:etf.c.map(x=>x==null?null:+(x*r).toFixed(2)),
              v:etf.v||[],prev:IDX.mis.prev,approx:true};
    }
  }
  return null;
}
/* ══ 風險示警系統:總經 + 個股,紅=危險、琥珀=注意 ══ */
function renderMacroAlerts(){
  const el=document.getElementById('macroAlerts');
  if(!el)return;
  const A=[];
  const __twMode=(window.GMKT||'TW')==='TW';
  const add=(lv,ico,txt)=>{   // r546:美股分頁過濾台股專屬警示(加權/櫃買/台指/融資/夜盤/小台/選擇權/外資現貨)
    if(!__twMode&&/加權|櫃買|台指|台股|小台|融資維持率|夜盤|外資期貨|外資現貨|P\/C|PCR/.test(String(txt)))return;
    A.push({lv,ico,txt});
  };
  try{const pc=((DATA.macro||{}).pcr||{});                   // ⚖️ 台指選擇權 P/C(未平倉)極端時提示
    if(pc.oi&&pc.oi.length>=20){
      const cur=pc.oi[pc.oi.length-1];
      const rank=pc.oi.filter(v=>v<=cur).length/pc.oi.length*100;
      if(rank<=10)add('amb','⚖️',atag('選擇權')+`台指選擇權 P/C 未平倉比 ${cur}%(近60日低檔)——市場樂觀偏頭,反向警訊`);
      else if(rank>=90)add('amb','⚖️',atag('選擇權')+`台指選擇權 P/C 未平倉比 ${cur}%(近60日高檔)——避險情緒濃,恐慌溫度升高`);
    }}catch(e){}
  try{const mt=window.__mtRate;                              // 🧮 融資維持率警戒
    if(mt!=null&&mt<140)add(mt<130?'red':'amb','🧮',atag('融資')+`大盤融資維持率估算 ${mt}%${mt<130?'——跌破追繳線,斷頭多殺多風險高':'——逼近追繳線,大跌日慎防斷頭賣壓'}`);
  }catch(e){}
  try{const nf=window.__nightFut;                            // 🌙 台指夜盤價差(隔日開盤領先參考)
    if(nf&&Date.now()/1000-nf.t<16*3600&&Math.abs(nf.sprd)>=0.15){
      add(Math.abs(nf.sprd)>=0.8?'amb':'ok','🌙',atag('夜盤')+`台指夜盤 ${(+nf.px).toLocaleString()}(${nf.sprd>0?'+':''}${nf.sprd}% vs 加權收盤)——隔日開盤${nf.sprd>0.15?'偏多':'偏空'}參考`);
    }}catch(e){}
  Object.values(window.__headIdx||{}).forEach(x=>{           // 🔺 大盤/櫃買趨勢與頭部機率(常駐;≥50%升級為警告)
    const lv=x.prob>=70?'red':x.prob>=50?'amb':'ok';
    const ico=x.prob>=50?'🔺':'📈';
    add(lv,ico,atag('頭部')+`${x.nm}趨勢:${x.trend} · 頭部機率 ${x.prob}%${x.prob>=70?'——證據齊備,紀律減碼':x.prob>=50?'——頭部風險偏高,反彈保守以對':''}`);
  });
  try{if(window.__turnIdx)turnPills(window.__turnIdx,add,'加權');}catch(e){}
  const rv=window.__riskVals||{};
  if(rv.vix!=null){
    if(rv.vix>=28)add('red','🚨',`VIX ${rv.vix.toFixed(1)} 恐慌區——市場劇烈避險,倉位與槓桿務必控管`);
    else if(rv.vix>=20)add('amb','⚠️',`VIX ${rv.vix.toFixed(1)} 警戒區——波動升溫,操作放謹慎`);
  }
  if(rv.y10!=null){
    if(rv.y10>=5)add('red','🚨',`美債10年 ${rv.y10.toFixed(2)}% 破 5%——高估值成長股評價重壓`);
    else if(rv.y10>=4.5)add('amb','⚠️',`美債10年 ${rv.y10.toFixed(2)}% 偏高水位——成長股評價承壓`);
    if(rv.bp10!=null&&Math.abs(rv.bp10)>=5)add('amb','⚡',`殖利率單日${rv.bp10>0?'急升':'急落'} ${Math.abs(rv.bp10).toFixed(1)}bp——評價波動放大`);
  }
  if(rv.y5!=null&&rv.y10!=null&&rv.y5>rv.y10)add('amb','↩️','殖利率曲線倒掛(5年>10年)——債市對景氣示警');
  try{
    const ft=((DATA.macro||{}).futtab)||[];
    if(ft.length){
      const L=ft[ft.length-1];
      if(L.txf!=null&&L.txf<=-60000){
        const fp=((DATA.macro||{}).fut||{}).fxPct;
        const px=fp&&fp.pct!=null?`(近一年第 ${fp.pct} 百分位${fp.pct<=5?',歷史極端':''})`:'';
        add(fp&&fp.pct<=5?'red':'amb',fp&&fp.pct<=5?'🚨':'⚠️',`外資期貨淨空單 ${Math.abs(L.txf).toLocaleString()} 口${px}——期貨籌碼明顯偏空`);
      }
      if(L.leek!=null&&L.leek>=25)add('amb','🌱',`散戶小台多單比 ${L.leek.toFixed(1)}%——散戶過度樂觀,反向警訊`);
      if(L.pcr!=null&&L.pcr>=130)add('amb','🌡️',`選擇權 PCR ${L.pcr.toFixed(0)}——樂觀情緒過熱`);
      else if(L.pcr!=null&&L.pcr<=80)add('amb','🌡️',`選擇權 PCR ${L.pcr.toFixed(0)}——避險情緒濃厚`);
      const f5=ft.slice(-5).reduce((a,r)=>a+(r.f||0),0);
      if(f5<=-1500)add('amb','📉',`外資現貨 5 日累計賣超 ${Math.abs(f5).toFixed(0)} 億——資金持續流出台股`);
    }
  }catch(e){}
  const news=(window.__glbAlerts||[]).map(x=>
    `<a class="alert-pill alert-${x.lv}" href="${x.l}" target="_blank" rel="noopener"><span class="ico">${x.lv==='red'?'🚨':'📰'}</span><span>${x.lv==='red'?'重大外電:':'外電訊號:'}${x.t}${x.tags.length?` <b>→ ${x.tags.join('/')}</b>`:''}<span style="color:var(--dim);font-weight:600"> · ${x.ago} ↗</span></span></a>`).join('');
  el.style.display='';
  el.innerHTML=(A.length||news)
    ?A.map(a=>`<span class="alert-pill alert-${a.lv}"><span class="ico">${a.ico}</span><span>${a.txt}</span></span>`).join('')+news
    :'<span class="alert-pill alert-ok"><span class="ico">✅</span><span>風險溫度計與外電目前無特別警示</span></span>';
}
