async function grpSummarize(s){                            // r701:章節摘要——每章開頭直接給結論,不展開也能一目瞭然
  const put=(i,html)=>{const el=document.getElementById('gsum-'+i);if(el)el.innerHTML=html;};
  const F1=x=>(x>=0?'+':'')+(+x).toFixed(1);
  const up=t=>`<b style="color:var(--up)">${t}</b>`,dn=t=>`<b style="color:var(--down)">${t}</b>`,nm2=t=>`<b>${t}</b>`;
  let e=null;try{e=await loadChips(s);}catch(x){}
  // 第一章 技術
  try{
    const bits=[];
    try{
      const sh=shardOf(s);const ke=withLiveBar((KCACHE[sh]||{})[s.id],s);   // r701:摘要以盤中價計算
      if(ke&&ke.o&&ke.o.length>=60){
        const c=ke.o.map(x=>x[3]),n=c.length,last=c[n-1];
        const ma=k=>{let x=0;for(let i=n-k;i<n;i++)x+=c[i];return x/k;};
        const m20=ma(20),m60=ma(60);
        bits.push(last>=m20?up('站上月線'):dn('月線之下'));
        bits.push(last>=m60?up('季線之上'):dn('季線之下'));
        if(n>=120){
          const bs=[];for(let i=19;i<n;i++){let m2=0;for(let j=i-19;j<=i;j++)m2+=c[j];bs.push((c[i]/(m2/20)-1)*100);}
          const cur=bs[bs.length-1],pct=Math.round(bs.filter(x=>x<=cur).length/bs.length*100);
          bits.push(`乖離 ${F1(cur)}%(第${pct}百分位${pct>=95?'・過熱':pct<=5?'・超跌':''})`);
        }
      }
    }catch(x){}
    let lts=null;
    try{lts=liveTechScore((KCACHE[shardOf(s)]||{})[s.id],+s.price);}catch(x9){}
    if(lts&&s.t&&Math.abs(lts.score-s.t.score)>=3)bits.push(`技術分 ${nm2(lts.score)}<span style="font-size:11px;color:var(--dim)">(盤中,盤後基準 ${s.t.score})</span>`);
    else if(s.t&&s.t.score!=null)bits.push(`技術分 ${nm2(s.t.score)}`);
    if(bits.length)put(0,'📌 '+bits.join('・'));
  }catch(x){}
  // 第二章 籌碼
  try{
    const bits=[];
    if(e&&Array.isArray(e.f)&&e.f.length>=5){
      const sum5=arr=>{let x=0;for(let i=arr.length-5;i<arr.length;i++)x+=(+arr[i]||0);return Math.round(x);};
      const f5=sum5(e.f);
      bits.push('外資5日 '+(f5>=0?up(F1(f5).replace('.0','')+' 張'):dn(f5.toLocaleString()+' 張')));
      if(Array.isArray(e.t)&&e.t.length>=5){const t5=sum5(e.t);
        bits.push('投信5日 '+(t5>=0?up('+'+t5.toLocaleString()+' 張'):dn(t5.toLocaleString()+' 張')));}
    }
    if(e&&Array.isArray(e.bp)&&e.bp.length>=2){
      const bL=+e.bp[e.bp.length-1],d2=bL-+e.bp[0];
      bits.push(`千張大戶 ${nm2(bL.toFixed(1)+'%')}(${d2>=0?'+':''}${d2.toFixed(1)}pp)`);
    }
    if(s.mg&&s.mg.f>0&&s.mg.s!=null)bits.push(`券資比 ${(s.mg.s/s.mg.f*100).toFixed(1)}%`);
    if(s.c&&s.c.score!=null)bits.push(`籌碼分 ${nm2(s.c.score)}`);
    if(bits.length)put(1,'📌 '+bits.join('・'));
  }catch(x){}
  // 第三章 基本面
  try{
    const bits=[];
    if(e&&Array.isArray(e.ry)&&e.ry.length)bits.push('營收YoY '+((+e.ry[e.ry.length-1]>=0?up:dn)(F1(e.ry[e.ry.length-1])+'%')));
    if(e&&Array.isArray(e.om)&&e.om.length)bits.push(`營益率 ${nm2((+e.om[e.om.length-1]).toFixed(1)+'%')}`);
    if(+s.pe>0)bits.push(`PE ${nm2((+s.pe).toFixed(1))} 倍`);
    if(s.dv&&s.dv.y!=null)bits.push(`殖利率 ${s.dv.y}%`);
    if(s.f&&s.f.score!=null)bits.push(`基本分 ${nm2(s.f.score)}`);
    if(bits.length)put(2,'📌 '+bits.join('・'));
  }catch(x){}
  // 三力技術卡重繪(r701):分片此時已載入——修正進頁首繪拿不到分片、盤後價不動不觸發的兩個死角
  try{
    const tc=document.getElementById('t3TechCard');
    if(tc&&typeof dimBlock==='function')tc.innerHTML=dimBlock('技術線型(權重25%)',t3Live(s));
  }catch(xT){}
  // 第四章 綜合
  try{
    const g=k=>(s[k]&&+s[k].score)||50;
    let tLive=g('t');
    try{const l2=liveTechScore((KCACHE[shardOf(s)]||{})[s.id],+s.price);if(l2)tLive=l2.score;}catch(x8){}
    const comp=Math.round(g('f')*0.4+g('c')*0.35+tLive*0.25);
    put(3,`📌 綜合分 <b style="font-size:15px;color:var(--gold,var(--amber))">${comp}</b>/100(基本 ${g('f')}・籌碼 ${g('c')}・技術 ${tLive},權重 40/35/25)——細節見本章 AI 總結與市場觀點`);
  }catch(x){}
}
function stkReorderSections(s){                            // r501:個股頁資訊架構重排——「四層決策流」
  try{
    if(s&&s.etf)return;                                     // ETF 頁維持原專屬排版
    const first=document.querySelector('[data-sec="stk_k"]');
    if(!first)return;
    const root=first.parentNode;
    const GROUPS=[
      ['📈','技術與價格','現在怎麼走・在哪進出',['stk_k','stk_dna','stk_3','stk_s']],
      ['⚖️','籌碼動向','誰在買、誰在賣',['stk_f','stk_ae','stk_h','stk_bs','stk_c']],
      ['💰','基本面與價值','值不值得・前景如何',['stk_r','stk_v','stk_peer','stk_conf']],
      ['🧭','綜合研判與背景','AI 總結・市場觀點・公司背景',['stk_ai','stk_m','stk_p','stk_e']],
    ];
    const pair=k=>{
      const t=root.querySelector(`[data-sec="${k}"]`);
      if(!t)return null;
      const b=document.getElementById('sb-'+k);
      return b?{t,b}:null;
    };
    const used=new Set();
    GROUPS.forEach(([ico,nm,sub,keys])=>{
      const got=keys.map(pair).filter(Boolean);
      if(!got.length)return;
      const gi=GROUPS.findIndex(g=>g[1]===nm);
      const band=document.createElement('div');
      band.className='grp-band';
      band.dataset.jlabel=`第${['一','二','三','四'][gi]||''}章・${nm}`;
      band.style.cssText='margin:34px 0 4px;padding:12px 16px 11px;border-radius:0 12px 12px 0;background:var(--panel);border:1px solid var(--line);border-left:6px solid var(--gold,var(--amber));box-shadow:var(--sh1,0 1px 3px rgba(0,0,0,.05));position:relative';
      band.innerHTML=`<div style="font-family:var(--serif,inherit);font-weight:900;font-size:17.5px;letter-spacing:.08em"><span style="color:var(--gold,var(--amber));font-size:13px;letter-spacing:.14em;margin-right:8px">第${['一','二','三','四'][gi]||''}章</span>${ico} ${nm} <span style="font-family:var(--sans,inherit);font-weight:400;font-size:12.5px;color:var(--dim);letter-spacing:.02em">${sub}</span></div>
        <div class="grp-sum" id="gsum-${gi}" style="font-size:13px;color:var(--txt2);margin-top:6px;line-height:1.75"><span style="color:var(--dim)">整理本章重點中…</span></div>`;
      root.appendChild(band);
      got.forEach(p=>{root.appendChild(p.t);root.appendChild(p.b);});
      keys.forEach(k=>used.add(k));
    });
    setTimeout(()=>{try{grpSummarize(s);}catch(e){}},1400);  // 待 K 分片/籌碼快取暖機後填結論
    setTimeout(()=>{try{grpSummarize(s);}catch(e){}},4200);  // 第二次補齊慢到的資料
    try{                                                     // r701:手機章節分頁——內容分五個面板,像 app 一樣「切」不是「滑」
      const anchor=document.getElementById('stkAlerts');
      if(anchor&&anchor.parentElement===root){
        let mode='top',ci=-1;
        [...root.children].forEach(el=>{
          if(el===anchor||el.id==='dnaTop'||el.id==='chapTabs'){mode='ov';return;}
          if(mode==='top')return;                            // 返回鈕/價格頭/警示帶:永遠顯示
          if(el.classList.contains('grp-band')){ci++;mode=String(ci);}
          el.dataset.chap=(mode==='ov')?'ov':String(ci);
        });
        let bar=document.getElementById('chapTabs');
        if(bar)bar.remove();
        bar=document.createElement('div');
        bar.id='chapTabs';
        const tabs=[['ov','🏠 總覽'],['0','📈 技術'],['1','⚖️ 籌碼'],['2','💰 基本'],['3','🧭 研判']];
        bar.innerHTML=tabs.map(([k,lb])=>`<button data-ch="${k}">${lb}</button>`).join('');
        anchor.after(bar);
        const setChap=k=>{
          document.documentElement.dataset.chap=k;
          bar.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b.dataset.ch===k));
          setTimeout(()=>{                                   // 隱藏面板裡的 ECharts 寬度為 0,顯示後必須 resize
            try{window.dispatchEvent(new Event('resize'));}catch(x){}
            try{if(typeof chartInst!=='undefined'&&chartInst)chartInst.resize();}catch(x){}
            try{
              if(window.echarts)document.querySelectorAll('[_echarts_instance_]').forEach(el=>{
                const inst=echarts.getInstanceByDom(el);
                if(inst)try{inst.resize();}catch(x2){}
              });
            }catch(x){}
          },230);
        };
        bar.querySelectorAll('button').forEach(b=>b.onclick=()=>{
          setChap(b.dataset.ch);
          try{bar.scrollIntoView({behavior:'smooth',block:'start'});}catch(x){}
        });
        const keep=(window.__chapStk===s.id&&document.documentElement.dataset.chap)||'ov';   // r701:刷新不踢回總覽
        setChap(keep);
        window.__chapStk=s.id;
        try{                                                 // r701:財報狗式桌機左側導航——章節+各節兩層選單,固定左欄
          const old2=document.getElementById('stkSide');
          if(old2)old2.remove();
          const side=document.createElement('nav');
          side.id='stkSide';
          let html='<div class="ss-in">';
          html+=`<button class="ss-ov on" data-sch="ov">🏠 總覽</button>`;
          let ci2=-1;
          [...root.children].forEach(el=>{
            if(el.classList.contains('grp-band')){
              ci2++;
              html+=`<div class="ss-grp" data-sch="${ci2}">${(el.dataset.jlabel||'').replace(/^第.章・/,'')}</div>`;
            }else if(el.classList.contains('sec-title')&&el.dataset.sec&&el.dataset.chap===String(ci2)&&ci2>=0){
              const nm2=(el.childNodes[0]?.textContent||'').trim();
              html+=`<button class="ss-it" data-sch="${ci2}" data-ssec="${el.dataset.sec}">${nm2}</button>`;
            }
          });
          html+='</div>';
          side.innerHTML=html;
          root.prepend(side);
          const go=(ch,sec)=>{
            const tb=bar.querySelector(`[data-ch="${ch}"]`);
            if(tb&&!tb.classList.contains('on'))tb.click();
            side.querySelectorAll('.ss-it,.ss-ov').forEach(x=>x.classList.toggle('on',
              sec?x.dataset.ssec===sec:x.dataset.sch===ch&&!x.dataset.ssec));
            if(sec)setTimeout(()=>{try{document.querySelector(`.sec-title[data-sec="${sec}"]`).scrollIntoView({behavior:'smooth',block:'start'});}catch(x2){}},80);
            else window.scrollTo({top:0,behavior:'smooth'});
          };
          try{                                               // r701:重建後左欄高亮跟著當前章節
            const cc=document.documentElement.dataset.chap||'ov';
            side.querySelectorAll('.ss-ov').forEach(x=>x.classList.toggle('on',cc==='ov'));
          }catch(x6){}
          side.querySelectorAll('.ss-ov').forEach(b2=>b2.onclick=()=>go('ov',null));
          side.querySelectorAll('.ss-grp').forEach(b2=>b2.onclick=()=>go(b2.dataset.sch,null));
          side.querySelectorAll('.ss-it').forEach(b2=>b2.onclick=()=>go(b2.dataset.sch,b2.dataset.ssec));
        }catch(e10){}
      }
    }catch(e9){}
    root.querySelectorAll('.sec-title[data-sec]').forEach(t=>{   // 未列入者維持相對順序附於最後
      const k=t.dataset.sec;
      if(used.has(k)||!k.startsWith('stk_'))return;
      const b=document.getElementById('sb-'+k);
      root.appendChild(t);if(b)root.appendChild(b);
    });
  }catch(e){}
}
function kpiStrip(s){                                     // r701:財報狗式大數字 KPI 卡——股價/EPS/本益比/股價淨值比/月營收YoY 一排大字報
  try{
    if(s.etf)return '';
    const up=+s.chg>0,dn=+s.chg<0,cc=up?'var(--up)':dn?'var(--down)':'var(--mut)';
    const cell=(lb,big,sub,col)=>`<div class="kpi-c"><div class="kpi-lb">${lb}</div><div class="kpi-big"${col?` style="color:${col}"`:''}>${big}</div><div class="kpi-sub">${sub||''}</div></div>`;
    const cards=[];
    const pct=(+s.chg||0), pctS=(pct>=0?'+':'')+pct.toFixed(2)+'%';
    cards.push(cell('股價',`<span id="kpiPx">${s.price??'—'}</span>`,`<span id="kpiChg" style="color:${cc}">${pctS}</span>`));
    cards.push(cell('每股盈餘 EPS',(s.eps!=null?(+s.eps).toFixed(2):'—'),s.eps!=null?'近四季':'待更新',(s.eps!=null&&+s.eps<0)?'var(--down)':''));
    const ind=(DATA.indpe||{})[s.sector];
    const peSub=(s.pe&&ind)?((s.pe>=ind?'高於':'低於')+'同業 '+ind):(s.pe?'倍':'虧損不適用');
    cards.push(cell('本益比 PE',(s.pe?s.pe:'—'),peSub,(s.pe&&ind&&s.pe<ind)?'var(--up)':''));
    cards.push(cell('股價淨值比 PB',(s.pb?s.pb:'—'),s.pb?'倍':'—'));
    const ry=(s.t3&&s.t3.ry!=null)?s.t3.ry:null;
    cards.push(cell('月營收年增',(ry!=null?((ry>=0?'+':'')+(+ry).toFixed(1)+'%'):'—'),ry!=null?'YoY':'待更新',ry!=null?(ry>=0?'var(--up)':'var(--down)'):''));
    return `<div class="kpi-strip">${cards.join('')}</div>`;
  }catch(e){return '';}
}
function renderStkAlerts(s,k,tt){
  const el=document.getElementById('stkAlerts');
  if(!el||location.hash!=='#stock/'+s.id)return;
  const A=[];const add=(lv,ico,txt)=>A.push({lv,ico,txt});
  try{window.__lastStkAlertArgs=[...arguments];}catch(e){}
  try{const hc=window.__headStkC;                            // 🔺 七腳印趨勢/機率:重繪也常駐
    if(hc&&hc.id===s.id){
      const lv=hc.prob>=70?'red':hc.prob>=50?'amb':'ok';
      add(lv,hc.prob>=50?'🔺':'📈',atag('頭部')+`趨勢:${hc.trend} · 頭部機率 ${hc.prob}%${hc.prob>=70?'——證據齊備,紀律減碼/停損':hc.prob>=50?'——做頭風險偏高,反彈視為減碼機會':''}`);
    }}catch(e){}
  try{const tc=window.__turnStkC;                            // 🔔 轉折提醒(波段高低點/時間窗/價位觸碰)
    if(tc&&tc.id===s.id)turnPills(tc.r,add,'');}catch(e){}
  if(s.disp)add('red','🚨','處置股——交易管制中,流動性差、波動放大,短線進出風險高');
  if(s.dtp!=null&&s.dtp>=40)add(s.dtp>=60?'red':'amb','🎰',atag('當沖')+`當沖佔比 ${s.dtp}%——投機盤主導,波動劇烈${s.dtp>=60?',留意處置風險與尾盤變臉':',隔日沖出貨常在尾盤'}`);
  try{
    if(!k&&s.market==='US'){                                  // 美股:警示條也吃日K(與台股同規格)
      try{const sh=shardOf(s);
        const e2=(KCACHE[sh]||{})[s.id];
        if(e2&&e2.o&&e2.o.length>=60)k={ohlc:e2.o};
      }catch(e){}
    }
    if(k&&!k.demo&&Array.isArray(k.ohlc)&&k.ohlc.length>=60&&s.price){
      const cl=k.ohlc.map(x=>x[3]);
      const ma=p=>cl.slice(-p).reduce((x,y)=>x+y,0)/p;
      const m20=ma(20),m60=ma(60),px=s.price;
      if(px<m60)add('red','🔻',`跌破季線 ${m60.toFixed(1)}——中期趨勢轉弱`);
      else if(px<m20)add('amb','🔻',`跌破月線 ${m20.toFixed(1)}——短線轉弱,下一道防線季線 ${m60.toFixed(1)}`);
      const bias=(px/m20-1)*100;
      if(bias>=15)add('amb','🔥',atag('乖離')+`股價高於月線 ${bias.toFixed(0)}%——短線乖離過大,慎防急回檔`);
      else if(bias<=-12)add('ok','🧊',atag('乖離')+`股價低於月線 ${Math.abs(bias).toFixed(0)}%——負乖離深,技術性反彈機率升高;左側接刀請分批`);
    }
  }catch(e){}
  if(tt&&s.price&&tt.l10&&s.price<tt.l10)add('red','🐢',`跌破 10 日低點 ${tt.l10}——海龜法則出場訊號`);
  try{
    const r=chipRaw(s);
    if(r&&r.f5<0&&r.t5<0)add('amb','📉','外資+投信 5 日同步賣超——法人籌碼轉弱');
    if(r&&r.bigw!=null&&r.bigw<=-0.5)add('amb','👑',`千張大戶週減 ${Math.abs(r.bigw).toFixed(1)}pp——大戶調節持股`);
  }catch(e){}
  el.style.display='';
  const HINTS=[                                            // r499:膠囊白話提示字典(這代表什麼/該怎麼做/詳解在哪)
    [/頭部機率/,'頭部機率=「打頭七腳印」證據數換算:≥50% 反彈視為減碼機會、≥70% 證據齊備紀律出場。完整證據清單在下方「⚖️ 三力檢視」。'],
    [/已達平均週期|轉折窗|留意反轉/,'轉折節奏是時間統計:時間到了不代表一定轉,要等價格真的跌破/突破關鍵價才算數。價位與情境詳解在「🔄 轉折點分析」。'],
    [/跌破季線/,'季線(60日均線)=中期多空分界:站不回去之前中期趨勢視為轉弱,反彈到季線附近常遇解套賣壓——搶反彈以季線為壓力參考。'],
    [/跌破月線/,'月線(20日均線)=短線多空分界:下一道防線看季線;若 1~2 天內快速站回,視為假跌破。'],
    [/乖離過大|高於月線/,'股價離月線太遠時均值回歸的力量增強——不追高,等回測月線不破再評估,或等乖離收斂。'],
    [/低於月線.*%|負乖離/,'跌深後技術性反彈機率升高——但這是左側訊號:分批、小量、先設好停損再進場。'],
    [/海龜/,'海龜法則:跌破 10 日低點=趨勢單出場訊號——重紀律不重預測,出場後突破新高可再進。'],
    [/法人籌碼轉弱|同步賣超/,'外資+投信 5 日同賣是籌碼轉空的前兆——搭配量價確認:帶量下跌可信度高,無量緩跌可能只是調節。'],
    [/大戶調節|千張大戶週減/,'籌碼從大戶流向散戶=中期偏空訊號。完整分級趨勢在「👑 大戶持股趨勢」。'],
    [/處置股/,'處置=分盤交易/預收款券:流動性差、進出成本高、波動放大——短線族建議避開,持有者降槓桿。'],
    [/觸及本波段高點/,'價格進入轉折敏感區,又與時間週期共振——不是叫你賣,是叫你把防守價設好。'],
    [/趨勢:頭部確認中|已破末升低/,'「末升低點」跌破=頭部型態的確認要件之一——反彈不過前波高,以頭部劇本操作(反彈減碼優先於攤平)。'],
  ];
  const hintOf=t=>{const x=String(t).replace(/<[^>]+>/g,'');for(const [re,h] of HINTS)if(re.test(x))return h;return '';};
  el.innerHTML=(A.length
    ?A.map((a,i)=>{const h=hintOf(a.txt);
      return `<span class="alert-pill alert-${a.lv}" ${h?`data-hint="${i}" style="cursor:pointer" title="點我看白話解讀"`:''}><span class="ico">${a.ico}</span><span>${a.txt}${h?' <span style="opacity:.55;font-size:11px">ⓘ</span>':''}</span></span>`
        +(h?`<div id="pillHint_${i}" style="display:none;font-size:12.5px;color:var(--txt2);background:var(--panel2);border-radius:8px;padding:7px 11px;margin:3px 0 5px;line-height:1.65">💡 ${h}</div>`:'');}).join('')
    :'<span class="alert-pill alert-ok"><span class="ico">✅</span><span>目前無特別風險警示</span></span>');
  el.querySelectorAll('[data-hint]').forEach(p=>{p.onclick=()=>{
    const d=document.getElementById('pillHint_'+p.dataset.hint);
    if(d)d.style.display=d.style.display==='none'?'':'none';};});
}
/* ── 恐懼貪婪指數(CNN 同款半圓儀表;資料:後端 yext.json ← CNN 公開端點)── */
function fngZh(s){return s<25?'極度恐懼':s<45?'恐懼':s<=55?'中性':s<=75?'貪婪':'極度貪婪';}
function fngAnalysisHTML(f){   // 站內判讀:分級解讀+動向+極端訊號(取代外連 CNN)
  const s=f.s;
  const seg=s<25?'市場處於「極度恐懼」:恐慌性賣壓主導。歷史統計上此區間往往離階段性低點不遠——是反向思考的價值區,但接刀務必分批、嚴設停損。'
    :s<45?'市場處於「恐懼」:避險情緒偏重、資金縮手。此區間常見超跌反彈,但趨勢未明前以防守與分批佈局為主。'
    :s<=55?'市場情緒「中性」:多空力道均衡,方向交由基本面與資金面決定,順勢操作即可。'
    :s<=75?'市場處於「貪婪」:風險偏好升溫、資金積極。趨勢行情可續抱,但追價要節制、逢高分批調節。'
    :'市場處於「極度貪婪」:情緒亢奮到極端。歷史統計上高檔震盪與回檔風險明顯升高——不是不能做多,而是該開始想退場計畫。';
  const dirTxt=(a,b,lab)=>{const d=Math.round(a-b);return d>1?`較${lab}升溫 +${d}`:d<-1?`較${lab}降溫 ${d}`:`與${lab}持平`;};
  const mv=[dirTxt(s,f.p,'昨日'),dirTxt(s,f.w,'上週'),dirTxt(s,f.m,'上月')].join('、');
  const cross=(f.w-s>15)?'一週內情緒急凍(降幅逾 15)——通常對應急跌段,波動仍大,留意流動性與槓桿。'
             :(s-f.w>15)?'一週內情緒急升(升幅逾 15)——短線漲多,提防樂觀過頭後的回檔。':'';
  return `<div class="dim-note" style="margin-top:8px;line-height:1.75"><b>站內判讀:</b>${seg}<br><b>動向:</b>${mv}。${cross?`<br><b>訊號:</b>${cross}`:''}<br><span style="color:var(--dim)">指數綜合七項美股指標(動能/強弱/選擇權/垃圾債等,0=極恐、100=極貪);對台股主要經由美股連動與外資風險偏好傳導。情緒是「溫度計」不是進出訊號,請搭配防守線與籌碼判讀使用。</span></div>`;
}
function fngToggle(){
  const dd=document.getElementById('fngDetail');
  if(dd)dd.style.display=dd.style.display==='none'?'':'none';
}
function fngGauge(s){
  const zones=[[0,25,'#d64545'],[25,45,'#e8944a'],[45,55,'#b9b3a8'],[55,75,'#8fbf6f'],[75,100,'#3d9c5f']];
  const R=34,CX=45,CY=42,W=9;
  const arc=(a0,a1,color)=>{
    const r0=Math.PI*(1-a0/100),r1=Math.PI*(1-a1/100);
    const x0=CX+R*Math.cos(r0),y0=CY-R*Math.sin(r0);
    const x1=CX+R*Math.cos(r1),y1=CY-R*Math.sin(r1);
    return `<path d="M${x0.toFixed(1)} ${y0.toFixed(1)} A${R} ${R} 0 0 1 ${x1.toFixed(1)} ${y1.toFixed(1)}" stroke="${color}" stroke-width="${W}" fill="none" stroke-linecap="butt"/>`;
  };
  const na=Math.PI*(1-s/100);
  const nx=CX+(R-13)*Math.cos(na),ny=CY-(R-13)*Math.sin(na);
  return `<svg viewBox="0 0 90 48" style="width:86px;height:46px;display:block">
    ${zones.map(z=>arc(z[0]+0.6,z[1]-0.6,z[2])).join('')}
    <line x1="${CX}" y1="${CY}" x2="${nx.toFixed(1)}" y2="${ny.toFixed(1)}" stroke="var(--tx,#333)" stroke-width="2.2" stroke-linecap="round"/>
    <circle cx="${CX}" cy="${CY}" r="3" fill="var(--tx,#333)"/>
  </svg>`;
}
