/* ── 風險指標:VIX 恐慌指數 + 美債殖利率(每60秒即時更新)── */
async function refreshRisk(){
  const box=document.getElementById('riskRow');
  // 大盤融資餘額卡(FinMind,每日更新)
  window.__creditCard=()=>{
    const c=(DATA.macro||{}).credit;
    if(!box||!c||!c.fin||document.getElementById('creditCard'))return;
    const d=document.createElement('div');
    d.className='idx-card';d.id='creditCard';
    d.style.cursor='pointer';
    d.onclick=()=>{location.hash='#macro/credit';};
    d.innerHTML=`<div class="nm">信用交易(上市+櫃買) ›</div>
      <div class="vl">${c.fin.toLocaleString()} 億</div>
      <div class="ch ${(c.finD||0)>=0?'pos':'neg'}">${c.finD!=null?((c.finD>=0?'▲ +':'▼ ')+c.finD+' 億'):'—'}${c.otcF!=null?` · 櫃買 ${(c.otcF/1e4).toFixed(1)} 萬張`:''}</div>`;
    box.appendChild(d);
  };
  setTimeout(()=>{try{window.__creditCard();}catch(e){}},400);
  if(!box)return;
  const defs=[
    ['VIX 恐慌指數','^VIX','vix'],
    ['美債10年殖利率','^TNX','y10'],
    ['美債30年殖利率','^TYX','y30'],
    ['美債5年殖利率','^FVX','y5']];
  const out={};
  for(const [name,sym,key] of defs){
    try{
      const d=await yChart(sym);
      if(!d)continue;
      const last=[...d.c].reverse().find(x=>x!=null);
      if(last!=null)out[key]={name,last,prev:d.prev};
    }catch(e){}
  }
  if(!Object.keys(out).length){
    box.innerHTML='<div class="idx-card"><div class="nm">風險指標暫時載入不到,稍後自動重試</div></div>';
    return;
  }
  const cards=[];
  if(out.vix){
    const v=out.vix, chg=(v.last-v.prev)/v.prev*100;
    cards.push(`<div class="idx-card" data-mk="vix"><div class="nm">${v.name}</div>
      <div class="vl">${v.last.toFixed(2)}</div>
      <div class="ch">${chgHtml(+chg.toFixed(2))}</div></div>`);
  }
  // 🔧 殖利率格式自動偵測:Yahoo ^TNX 系列有時回「殖利率×10」(如 45.7)、有時回原值(如 4.57)
  //    以 >20 判定為 ×10 格式需除10,否則為原值——兩種來源都正確顯示(修正先前一律÷10 導致顯示 0.46% 的錯誤)
  const yld=x=>x==null?null:(x>20?x/10:x);
  for(const key of ['y10','y30','y5']){
    const v=out[key]; if(!v)continue;
    const yLast=yld(v.last), yPrev=yld(v.prev);
    const bp=(yLast!=null&&yPrev!=null)?(yLast-yPrev)*100:null;   // 殖利率差 ×100 = 基點(bp)
    cards.push(`<div class="idx-card" data-mk="${key}"><div class="nm">${v.name} <span class="c-code" title="小卡為日收盤;點卡看 TradingView 即時走勢">›</span></div>
      <div class="vl">${yLast!=null?yLast.toFixed(2):'—'}%</div>
      <div class="ch">${bp!=null?`<span class="${bp>0?'pos':bp<0?'neg':'flat'}">${bp>0?'▲':bp<0?'▼':'–'} ${Math.abs(bp).toFixed(1)} bp</span>`:''}</div></div>`);
  }
  box.innerHTML=cards.join('');
  // 依當下數值自動判讀(精簡版,併入總經判讀)
  let txt='';
  if(out.vix){
    const v=out.vix.last;
    const mood=v<15?'偏樂觀(留意自滿)':v<20?'正常區':v<28?'<b>警戒區</b>(倉位宜降)':'<b>恐慌區</b>(急殺與長線買點並存)';
    txt+=`VIX ${v.toFixed(1)} 屬${mood}。`;
  }
  if(out.y10){
    const y=out.y10.last/10, bp=(out.y10.last-out.y10.prev)*10;
    txt+=`美債10年 ${y.toFixed(2)}%`;
    if(Math.abs(bp)>=3)txt+=bp>0?`(+${bp.toFixed(1)}bp 急升,高估值 AI 股評價承壓)`:`(${bp.toFixed(1)}bp 回落,資金面轉鬆利成長股)`;
    if(out.y5)txt+=out.y5.last>out.y10.last?',曲線倒掛、債市示警景氣':'';
    txt+='。';
  }
  window.__noteRisk=txt;
  composeMacroNote();
  window.__riskVals={
    vix:out.vix?out.vix.last:null,
    y10:out.y10?yld(out.y10.last):null,
    bp10:(out.y10&&yld(out.y10.last)!=null&&yld(out.y10.prev)!=null)?(yld(out.y10.last)-yld(out.y10.prev))*100:null,
    y5:out.y5?yld(out.y5.last):null};
  try{renderMacroAlerts();}catch(e){}
}
setTimeout(refreshRisk,5000);
setInterval(refreshRisk,60000);

