/* ══════════ 🐦 富果 Fugle 即時行情層(WebSocket 逐筆;Key 僅存本機瀏覽器,絕不進 repo) ══════════ */
const FGL={ws:null,sym:null,ok:false,retry:0,bars:null};
function fglKey(){try{return localStorage.getItem('fugleKey')||'';}catch(e){return '';}}
function fglPanel(){                          // ⚙️ 設定面板:貼 Key/清除/狀態
  let m=document.getElementById('fglMask');
  if(m){m.remove();return;}
  m=document.createElement('div');m.id='fglMask';
  m.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:2100;display:flex;align-items:center;justify-content:center;padding:16px';
  const has=!!fglKey();
  m.innerHTML=`<div style="background:var(--panel);border:1px solid var(--line);border-radius:16px;max-width:560px;width:100%;padding:18px 20px">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px"><b style="font-size:17px">🐦 富果即時行情(券商級)</b>
      <a href="javascript:void 0" onclick="document.getElementById('fglMask').remove()" style="margin-left:auto;color:var(--dim);font-size:20px;font-weight:800">×</a></div>
    <div style="font-size:13.5px;line-height:1.7;color:var(--mut);margin-bottom:10px">
      貼上你在 developer.fugle.tw 申請的行情 API Key。<b>Key 只儲存在這台裝置的瀏覽器</b>(localStorage),不會上傳、不會進入網站原始碼;啟用後「正在觀看的個股」改用富果 WebSocket 逐筆行情(真即時價/量/力道),其餘功能維持原樣;無 Key 或斷線時自動退回現行模式。</div>
    <input id="fglKeyIn" type="password" placeholder="${has?'已設定(輸入新值可覆蓋)':'貼上 API Key'}"
      style="width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:9px;background:var(--panel2);color:var(--txt);font-family:var(--mono);font-size:13px">
    <div style="display:flex;gap:10px;margin-top:12px;align-items:center">
      <button id="fglSave" style="background:var(--amber);color:#fff;border:none;border-radius:9px;padding:9px 18px;font-weight:900;cursor:pointer">儲存並啟用</button>
      <button id="fglTest" style="background:transparent;border:1px solid var(--amber);border-radius:9px;padding:9px 14px;color:var(--amber);font-weight:800;cursor:pointer">測試自動領取</button>
      <button id="fglDiag" style="background:transparent;border:1px solid var(--line);border-radius:9px;padding:9px 14px;color:var(--mut);font-weight:800;cursor:pointer">連線診斷</button>
      ${has?'<button id="fglClr" style="background:transparent;border:1px solid var(--line);border-radius:9px;padding:9px 14px;color:var(--mut);cursor:pointer">清除 Key</button>':''}
      <span id="fglSt" style="font-size:12.5px;color:${FGL.ok?'var(--up)':'var(--dim)'}">${FGL.ok?'● 已連線':has?'○ 已設定,待連線':'○ 未設定'}</span></div></div>`;
  m.onclick=e=>{if(e.target===m)m.remove();};
  document.body.appendChild(m);
  const sv=m.querySelector('#fglSave');
  if(sv)sv.onclick=()=>{
    const v=(m.querySelector('#fglKeyIn').value||'').trim();
    if(v){try{localStorage.setItem('fugleKey',v);}catch(e){}}
    m.remove();
    try{toastLite('富果 Key 已儲存——進入任一個股即啟用逐筆行情');}catch(e){}
    try{fglEnsure(true);}catch(e){}
  };
  const ts=m.querySelector('#fglTest');
  if(ts)ts.onclick=async()=>{
    const st9=m.querySelector('#fglSt');
    st9.textContent='… 測試中';
    try{
      const MAIN='https://muddy-cake-cb69.frankccc199.workers.dev';
      let hosts=[MAIN];
      try{const p=(typeof myProxy==='function'?myProxy():'');
        const o=p?new URL(p).origin:'';
        if(o&&o!==MAIN)hosts=[o,MAIN];}catch(e){}
      let done=false,logs=[];
      for(const h of hosts){
        try{
          const r=await fglRawGet(h+'/fk',8000);
          const tag=h.includes('muddy-cake')?'muddy-cake(主力)':h.replace('https://','').split('.')[0];
          if(r.status===200){const j=await r.json();
            if(j&&j.k){localStorage.setItem('fugleKey',j.k);
              st9.style.color='var(--up)';
              st9.textContent=`✅ 成功!經由 ${tag} 取得 Key(${j.k.length} 字元)——盤中進個股即啟用逐筆`;done=true;break;}
            logs.push(tag+':200無內容');}
          else logs.push(tag+':HTTP '+r.status);
        }catch(e){logs.push('連線失敗');}
      }
      if(!done)st9.textContent='❌ '+logs.join(' → ')+'(全部截圖給我)';
    }catch(e){st9.textContent='❌ 連不上 Worker:'+String(e).slice(0,60);}
  };
  const dg=m.querySelector('#fglDiag');
  if(dg)dg.onclick=async()=>{
    const st9=m.querySelector('#fglSt');
    st9.style.color='var(--mut)';st9.textContent='… 三路實測中(約8秒)';
    const out=[];
    const key=fglKey();
    const api='https://api.fugle.tw/marketdata/v1.0/stock/intraday/candles/2330?timeframe=1';
    try{const r1=await fglRawGet2(api,key,6000);
      out.push('REST直連:'+(r1&&r1.ok?'✅ '+((await r1.json()).data||[]).length+'根':'HTTP '+(r1?r1.status:'CORS/連線失敗')));
    }catch(e){out.push('REST直連:❌'+String(e).slice(0,40));}
    try{let host='https://muddy-cake-cb69.frankccc199.workers.dev';
      try{const p=(typeof myProxy==='function'?myProxy():'');if(p)host=new URL(p).origin;}catch(e){}
      const r2=await fglRawGet(host+'/?url='+encodeURIComponent(api),8000);
      out.push('REST經Worker:'+(r2&&r2.ok?'✅ '+((await r2.json()).data||[]).length+'根':'HTTP '+(r2?r2.status:'失敗')));
    }catch(e){out.push('REST經Worker:❌'+String(e).slice(0,40));}
    await new Promise(res=>{
      try{
        const ws=new WebSocket('wss://api.fugle.tw/marketdata/v1.0/stock/streaming');
        const done=v=>{out.push('WS:'+v);try{ws.close();}catch(e){}res();};
        const to=setTimeout(()=>done('⏱ 5秒無回應'),5000);
        ws.onopen=()=>{try{ws.send(JSON.stringify({event:'auth',data:{apikey:key}}));}catch(e){}};
        ws.onmessage=ev=>{try{const raw=String(ev.data).slice(0,110);const j=JSON.parse(ev.data);
          if(j.event==='authenticated'||/authenticated/i.test(raw)){clearTimeout(to);done('✅ 認證成功');}
          else if(j.event==='error'){clearTimeout(to);done('❌ '+((j.data&&j.data.message)||'error'));}
          else {clearTimeout(to);done('❓收到:'+raw);}         // 未知回覆:原文攤開,一眼定案
        }catch(e){}};
        ws.onerror=()=>{clearTimeout(to);done('❌ 連線錯誤');};
      }catch(e){out.push('WS:❌'+String(e).slice(0,30));res();}
    });
    st9.style.color='var(--txt)';
    st9.innerHTML=out.join('　|　')+(window.__fglLastErr?('　|　最近錯誤:'+window.__fglLastErr):'');
  };
  const cl=m.querySelector('#fglClr');
  if(cl)cl.onclick=()=>{try{localStorage.removeItem('fugleKey');}catch(e){}
    try{if(FGL.ws)FGL.ws.close();}catch(e){}
    FGL.ok=false;m.remove();try{toastLite('已清除,退回一般模式');}catch(e){}};
}
function fglBarsPush(px,vol,tsec){            // 逐筆 → 1分K累積(供分時圖/力道/總量)
  const B=FGL.bars;if(!B)return;
  const mkey=Math.floor(tsec/60)*60;
  const L=B.t.length;
  if(L&&B.t[L-1]===mkey){
    B.c[L-1]=px;
    if(vol>0)B.v[L-1]+=vol;
  }else{
    B.t.push(mkey);B.c.push(px);B.v.push(vol>0?vol:0);
    if(B.t.length>400){B.t.shift();B.c.shift();B.v.shift();}
  }
}
function fglEnsure(force){                    // 連線管理:個股頁+盤中+有Key 才開;離開自動關
  try{
    const key=fglKey();
    const onStk=/^#stock\//.test(location.hash);
    const st=onStk?(DATA.stocks||[]).find(x=>x.id===decodeURIComponent(location.hash.split('/')[1]||'')):null;
    const want=key&&onStk&&st&&st.market==='TW'&&typeof marketOpen==='function'&&marketOpen();
    if(!want){
      if(FGL.ws){try{FGL.ws.close();}catch(e){}FGL.ws=null;FGL.ok=false;}
      return;
    }
    if(FGL.ws&&FGL.sym===st.id&&FGL.ws.readyState<=1&&!force)return;
    if(FGL.ws){try{FGL.ws.close();}catch(e){}}
    FGL.sym=st.id;
    FGL.bars={id:st.id,t:[],c:[],v:[],prev:null};
    const ws=new WebSocket('wss://api.fugle.tw/marketdata/v1.0/stock/streaming');
    FGL.ws=ws;
    ws.onopen=()=>{try{ws.send(JSON.stringify({event:'auth',data:{apikey:key}}));}catch(e){}};
    let authT=setTimeout(()=>{try{ws.send(JSON.stringify({event:'auth',data:{apikey:key}}));}catch(e){}},2000);
    const authOK=()=>{clearTimeout(authT);
      if(FGL.ok)return;
      FGL.ok=true;FGL.retry=0;
      try{ws.send(JSON.stringify({event:'subscribe',data:{channel:'aggregates',symbol:FGL.sym}}));}catch(e){}
      try{ws.send(JSON.stringify({event:'subscribe',data:{channel:'trades',symbol:FGL.sym}}));}catch(e){}
    };
    ws.onmessage=ev=>{
      try{
        const j=JSON.parse(ev.data);
        const msg=JSON.stringify(j).slice(0,120);
        if(j.event==='authenticated'||/authenticated/i.test(msg)||(j.event==='auth'&&!/error|invalid/i.test(msg))){authOK();return;}
        if(j.event==='data'&&!FGL.ok)authOK();               // 有資料=已通(容錯:成功事件名不明時)
        if(j.event==='error'){FGL.ok=false;window.__fglLastErr='WS '+((j.data&&j.data.message)||'error');return;}
        if(j.event!=='data'||!j.data)return;
        const d=j.data;
        const lt=d.lastTrade||d.lastPrice!=null&&{price:d.lastPrice}||null;
        const px=lt&&+lt.price;
        if(!(px>0))return;
        const tot=d.total||{};
        const vTot=+tot.tradeVolume>0?+tot.tradeVolume:null;      // 張(富果整股 tradeVolume 單位=張)
        const prev=+d.previousClose>0?+d.previousClose:null;
        const o9=+d.openPrice>0?+d.openPrice:null;
        const hi=+d.highPrice>0?+d.highPrice:null;
        const lo=+d.lowPrice>0?+d.lowPrice:null;
        const tsec=lt&&lt.time?Math.floor(+lt.time/1e6):Math.floor(Date.now()/1e3);   // 富果 time=微秒
        const id=FGL.sym;
        const st2=(DATA.stocks||[]).find(x=>x.id===id);
        if(st2){st2.price=px;if(prev)st2.chg=+(((px/prev)-1)*100).toFixed(2);}
        RTC[id]=Object.assign(RTC[id]||{},{c:px,o:o9||((RTC[id]||{}).o),h:hi||((RTC[id]||{}).h),
          l:lo||((RTC[id]||{}).l),y:prev||((RTC[id]||{}).y)});
        if(vTot!=null){
          const pv=window.__fglVTot||0;
          const dv=vTot-pv;
          window.__fglVTot=vTot;
          window.__intraVSum=vTot;                                 // 券商級累計量,直接覆蓋
          fglBarsPush(px,dv>0&&dv<1e6?dv:0,tsec);
        }else fglBarsPush(px,0,tsec);
        FGL.bars.prev=prev||FGL.bars.prev;
        try{if((d.bids||d.asks)&&(!window.__l5T||Date.now()-window.__l5T>1000)){   // r528:WS 帶委託簿→秒級五檔
          window.__l5T=Date.now();l5FromFugle(id,d);}}catch(e5){}
        window.__fglT=Date.now();
        try{stkAccPush(id,px,prev||null);}catch(e8){}       // r470:斷線備援——逐筆同步進本機累積(自帶節流)
        try{                                                // r470:逐筆秒級戳圖——線尾跟著每一筆成交跳
          if(location.hash==='#stock/'+id){
            if(RT.intra&&RT.intra.id===id&&window.__stkToday)pokeChart(RT.intra,px);
            try{liveKBar(id);}catch(eK){}                        // r508:富果逐筆同步驅動日K今日棒(內建8秒重繪節流)
            const nowMs=Date.now();
            if(!window.__fglUiT||nowMs-window.__fglUiT>150){   // r512:150ms——逐筆幾乎筆筆上畫面(仍防極端連發轟DOM)
              window.__fglUiT=nowMs;
              if(st2){
                const st3=document.getElementById('intraStat');
                if(st3){
                  if(st3.dataset.keep==null)st3.dataset.keep=(st3.innerHTML.split(' · ').slice(1)||[]).join(' · ');   // r513:徽章尾巴只讀一次
                  let h9=intraStatTxt(st2,st3.dataset.keep||null);
                  if(!/富果/.test(h9))h9+=' · <span style="color:var(--up)">🐦 富果逐筆</span>';
                  if(window.__isHtml!==h9){window.__isHtml=h9;st3.innerHTML=h9;}   // r513:內容沒變不寫DOM
                }
                const lp2=document.getElementById('dPx'),ch2=document.getElementById('dChg');
                const pt2=String(st2.price);
                if(lp2&&lp2.textContent!==pt2)lp2.textContent=pt2;
                if(ch2){const ch9=chgHtml(st2.chg);if(window.__dchH!==ch9){window.__dchH=ch9;ch2.innerHTML=ch9;}}
                const lv2=document.getElementById('lvPx');
                if(lv2&&lv2.textContent!==pt2)lv2.textContent=pt2;
              }
            }
          }
        }catch(e9){}
      }catch(e){}
    };
    ws.onclose=()=>{FGL.ok=false;
      if(fglKey()&&FGL.retry<6){FGL.retry++;setTimeout(()=>fglEnsure(true),Math.min(30000,3000*FGL.retry));}};
    ws.onerror=()=>{};
  }catch(e){}
}


const __fglCd={};                             // 60秒快取:symbol → {at,d}
async function fglSnapshot(){                              // r509→r522:已退役(健檢實測 snapshot 端點 HTTP 403,免費方案不含);保留僅供查考
  return;
  try{
    if(document.hidden)return;                             // r513:分頁隱藏休眠
    const key=fglKey();
    if(!key||!DATA||!Array.isArray(DATA.stocks))return;
    const open9=(typeof marketOpen==='function'&&marketOpen());
    if(open9){if(Date.now()-(window.__fglSnapT||0)<17000)return;}
    else{if(Date.now()-(window.__fglSnapOff||0)<10*60e3)return;window.__fglSnapOff=Date.now();}   // r516:盤外=開機對帳+每10分鐘(修「盤後檔過期/污染→全站錯價」)
    window.__fglSnapT=Date.now();
    const map=new Map();DATA.stocks.forEach(x=>{if(x.market==='TW')map.set(x.id,x);});
    let n=0;
    const errs=[];
    for(const mkt of ['TSE','OTC']){
      const api='https://api.fugle.tw/marketdata/v1.0/stock/snapshot/quotes/'+mkt;
      let r=null,e1='';
      try{r=await fglRawGet2(api,key,9000);}catch(e){r=null;e1=String(e&&e.name||e).slice(0,16);}
      if(r&&!r.ok)e1='HTTP'+r.status;
      if(!r||!r.ok){
        let host='https://muddy-cake-cb69.frankccc199.workers.dev';
        try{const p=(typeof myProxy==='function'?myProxy():'');if(p)host=new URL(p).origin;}catch(e){}
        try{r=await fT(host+'/fgl?u='+encodeURIComponent(api),9000);
          if(r&&!r.ok)e1+='/代發HTTP'+r.status;}catch(e){e1+='/代發失敗';r=null;}
      }
      if(!r||!r.ok){errs.push(mkt+':'+(e1||'?'));continue;}   // r519:每市場精確錯因
      const j=await r.json();
      (j&&j.data||[]).forEach(q=>{
        const st=map.get(String(q.symbol));
        if(!st)return;
        const px=+q.closePrice||+q.lastPrice||0;
        if(!(px>0))return;
        try{if(st.price>0&&Math.abs(px/st.price-1)>0.03)window.__snapDiffN=(window.__snapDiffN||0)+1;}catch(e){}   // r516:對帳差異統計
        st.price=px;
        if(q.changePercent!=null)st.chg=+(+q.changePercent).toFixed(2);
        const r0=RTC[st.id]||(RTC[st.id]={});
        if(+q.openPrice>0)r0.o=+q.openPrice;
        if(+q.highPrice>0)r0.h=+q.highPrice;
        if(+q.lowPrice>0)r0.l=+q.lowPrice;
        r0.c=px;
        if(q.change!=null&&px-(+q.change)>0)r0.y=+(px-(+q.change)).toFixed(2);
        snapPut(st.id,px,st.chg);
        n++;
      });
    }
    if(!n){window.__fglSnapErr=errs.length?errs.join(' '):'快照0檔';}   // r517/r519:精確錯因(403=方案不含/TypeError=CORS需代發/代發HTTP404=Worker缺/fgl路由)
    if(n){
      window.__fglSnapErr=null;
      window.__rtOkN=n;window.__rtOkT=Date.now();window.__fglSnapOk=Date.now();
      try{const mm2=location.hash.match(/^#stock\/(.+)$/);
        if(mm2){const s2=DATA.stocks.find(x=>x.id===decodeURIComponent(mm2[1]));
          if(s2){
            const px8=document.getElementById('dPx'),ch8=document.getElementById('dChg');   // r516:盤外對帳也更新標頭大字
            if(px8)px8.textContent=s2.price;
            if(ch8)ch8.innerHTML=chgHtml(s2.chg);
            if(open9){stitchStk(s2);try{liveKBar(s2.id);}catch(e){}}
          }}}catch(e){}
      try{if(window.__snapDirty&&typeof snapFlush==='function')snapFlush();}catch(e){}
    }
  }catch(e){}
}
