async function fglCandles(symbol,isIndex){    // 🐦 富果 REST:當日開盤至今的完整 1 分 K(全網站台股即時的底圖)
  try{
    const key=fglKey();
    if(!key)return null;
    const c0=__fglCd[symbol];
    if(c0&&Date.now()-c0.at<25000)return c0.d;   // r511:快取25秒
    const api='https://api.fugle.tw/marketdata/v1.0/stock/intraday/candles/'
      +encodeURIComponent(symbol)+'?timeframe=1';
    let r=null;
    try{r=await fglRawGet2(api,key,7000);}catch(e){r=null;}  // 直連(部分環境 CORS 擋)
    if(!r||!r.ok){                                            // 退自家 Worker 代發(Key 由 Worker 注入)
      let host='https://muddy-cake-cb69.frankccc199.workers.dev';
      try{const p=(typeof myProxy==='function'?myProxy():'');if(p)host=new URL(p).origin;}catch(e){}
      try{r=await fglRawGet(host+'/?url='+encodeURIComponent(api),9000);}catch(e){r=null;}
    }
    if(!r||!r.ok){window.__fglLastErr='REST '+(r?('HTTP '+r.status):'連線失敗');
      if(c0&&Date.now()-c0.at<600000)return c0.d;           // 沿用10分鐘內的最後成功快取,圖不倒退
      return null;}
    const j=await r.json();
    const rows=(j&&j.data)||[];
    if(!rows.length)return null;
    const t=[],c=[],v=[];
    rows.forEach(b=>{
      const ts=Math.floor(Date.parse(b.date)/1000);
      if(!(ts>0)||!(b.close>0))return;
      t.push(ts);c.push(+b.close);
      v.push(isIndex?0:Math.round((+b.volume||0)*1000));   // 個股:張→股;指數不用量
    });
    if(c.length<2)return null;
    const d={t,c,v};
    __fglCd[symbol]={at:Date.now(),d};
    return d;
  }catch(e){return null;}
}
async function fglRawGet2(url,key,ms){
  const ac=new AbortController();
  const t=setTimeout(()=>ac.abort(),ms||9000);
  try{return await fetch(url,{signal:ac.signal,cache:'no-store',headers:{'X-API-KEY':key}});}
  finally{clearTimeout(t);}
}

async function fglRawGet(url,ms){             // /fk 專用:原生 fetch,不經站內代理包裝(fT 會重包網址導致 400)
  const ac=new AbortController();
  const t=setTimeout(()=>ac.abort(),ms||8000);
  try{return await fetch(url,{signal:ac.signal,cache:'no-store'});}
  finally{clearTimeout(t);}
}

