function intraStatTxt(s,extra){
  const px=s.price!=null?s.price:'—';
  const cg=s.chg!=null?` <span class="${s.chg>=0?'pos':'neg'}">${s.chg>=0?'▲':'▼'} ${Math.abs(s.chg).toFixed(2)}%</span>`:'';
  const mt=(window.__mkT||{})[s.id];
  let tt='';
  if(mt){                                                  // r422:成交時刻新鮮度檢查——過期就標「延遲/前一場」,不再假裝即時
    let stale=false,mins=null;
    try{
      const now=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Taipei'}));
      const hm=String(mt).slice(0,5).split(':');
      if(hm.length===2){
        const qm=+hm[0]*60+ +hm[1], nm=now.getHours()*60+now.getMinutes();
        mins=nm-qm;
        stale=(typeof marketOpen==='function'&&marketOpen())&&(mins>15||mins<-3);
      }
    }catch(e){}
    tt=` <span style="font-size:11px;color:${stale?'var(--amber)':'var(--dim)'}" title="交易所成交時刻">成交 ${String(mt).slice(0,8)}${stale?`(${mins>0?'延遲約'+mins+'分':'非本場'},非最新)`:''}</span>`;
  }
  const vv=(window.__intraVSum||0);                        // 唯一來源:分時量加總(RTC.v 實測為單筆量,棄用)
  let vt='';
  try{
    const now=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Taipei'}));
    const mins=now.getHours()*60+now.getMinutes()-540;
    const open2=typeof marketOpen==='function'&&marketOpen();
    const expct=(window.__v1&&open2&&mins>0)?window.__v1*cumPct(Math.min(mins,270))/100:null;
    if(vv>0){
      const cut=(!open2&&window.__stkToday&&window.__intraLastM!=null&&window.__intraLastM<795);   // 收盤後但只擷半場
      const sparse=(expct!=null&&vv<expct*0.2)||cut||vv<50
        ||(window.__v1&&vv<window.__v1*0.02);               // 偏低/中斷/絕對過少 → 誠實標示,不給誤導%
      vt=` <span style="font-size:11px;color:var(--dim)">${cut?'已收錄':'總量'} ${sparse?'≥':''}${Math.round(vv).toLocaleString()} 張${cut?'(不完整)':sparse?'(來源回補中)':''}</span>`;
      if(!sparse&&(window.__v1||window.__v20)&&open2&&mins>=20&&mins<270){
        const est=vv/(cumPct(mins)/100);
        const base=window.__v1||window.__v20;
        const df=(est/base-1)*100;
        vt+=` <span style="font-size:11px;color:${df>=30?'var(--down)':df<=-30?'var(--up)':'var(--dim)'}" title="以量能時間曲線推估的全日成交量,與昨日比較">預估 ${Math.round(est).toLocaleString()} 張(較昨日 ${df>0?'+':''}${df.toFixed(0)}%)</span>`;
      }
    }
  }catch(e){}
  return `<b style="font-family:var(--mono)">${px}</b>${cg}${tt}${vt}${extra?' · '+extra:''}`;
}
/* 個股即時解讀:開盤型態/日內位置/均價關係/短線動能/量能/關卡距離 */
function stkRead(s){
  const r=RTC[s.id];
  if(!r||!(r.o>0)||!(r.y>0))return null;
  const c=r.c,o=r.o,h=r.h,l=r.l,y=r.y;
  const gap=(o-y)/y*100, chg=(c-y)/y*100;
  const pat=gap>=1.5?`跳空開高(+${gap.toFixed(1)}%)`:gap<=-1.5?`跳空開低(${gap.toFixed(1)}%)`:'平盤附近開出';
  const rng=h-l;
  const pos=rng>0?(c-l)/rng:0.5;
  const posTxt=pos>=0.75?'收斂在日內高檔區':pos<=0.25?'壓在日內低檔區':'於日內中間帶震盪';
  // 均價關係(累積線平均)
  const acc=stkAcc(s.id);
  let vw='';
  if(acc.c.length>=5){
    const avg=acc.c.reduce((a,b)=>a+b,0)/acc.c.length;
    vw=c>=avg*1.002?'站穩均價線之上(多方控盤)':c<=avg*0.998?'跌落均價線之下(賣壓浮現)':'貼著均價線拉鋸';
  }
  // 短線動能:最近~10點斜率
  let mom='';
  if(acc.c.length>=10){
    const seg=acc.c.slice(-10);
    const d0=(seg[seg.length-1]-seg[0])/seg[0]*100;
    mom=d0>0.35?'短線正在拉升':d0<-0.35?'短線正在回落':'短線橫盤整理';
  }
  // 關卡距離(20日高/箱頂/停損)
  const notes=[];
  const a=s.al||{};
  if(a.h20&&c<a.h20&&c>=a.h20*0.985)notes.push(`逼近 20 日高 ${a.h20}(差 ${(((a.h20-c)/c)*100).toFixed(1)}%),突破帶量可視為右側訊號`);
  else if(a.h20&&c>=a.h20)notes.push(`已站上 20 日高 ${a.h20},右側動能確認`);
  if(window.__kBox&&KHASH==='#stock/'+s.id){
    const b=window.__kBox;
    if(c>=b.top*0.99&&c<b.top*1.005)notes.push(`正在測試箱頂 ${b.top}`);
    else if(c>=b.top*1.005)notes.push(`突破箱頂 ${b.top},整理結束向上表態`);
    else if(c<=b.bot*1.01)notes.push(`貼近箱底 ${b.bot},守不守得住是關鍵`);
  }
  if(a.stop&&c<=a.stop*1.02&&c>a.stop)notes.push(`接近停損參考價 ${a.stop},紀律優先`);
  const strength=chg>=5?'今日強攻':chg>=2?'今日走強':chg<=-5?'今日重挫':chg<=-2?'今日走弱':'今日波動溫和';
  return `${strength}——${pat},現於 ${c}(${chg>=0?'+':''}${chg.toFixed(2)}%),日內 ${l}~${h},${posTxt}${vw?'、'+vw:''}${mom?'、'+mom:''}。${notes.length?notes.join(';')+'。':''}<span class="dim-note">規則化描述,非投資建議。</span>`;
}
