async function misOhlcCore(ch,prev){
  // 證交所 MIS 站內分線端點(非正式):成功=瞬間補全 09:00 起走勢;失敗=無感回退
  // ch:MIS 頻道(tse_2330.tw / tse_t00.tw / otc_o00.tw)、prev:昨收(彈性掃描值域基準)
  try{
    if(!(prev>0))return null;
    const u=`https://mis.twse.com.tw/stock/api/getChartOhlcStatis.jsp?ex_ch=${ch}&_=${Date.now()}`;
    const routes=[
      ...(myWrap(u)?[[myWrap(u),0]]:[]),
      [u,0],
      ['https://corsproxy.io/?url='+encodeURIComponent(u),0],
      ['https://api.allorigins.win/raw?url='+encodeURIComponent(u),0],
      ['https://api.allorigins.win/get?url='+encodeURIComponent(u),1]];
    const one=async([url,wrap])=>{
      const r0=await fT(url,6000);
      if(!r0.ok)throw 0;
      let j0=await r0.json();
      if(wrap&&j0&&j0.contents){j0=JSON.parse(j0.contents);}
      if(!j0)throw 0;
      return j0;
    };
    let j;
    try{j=await routeRace('misohlc',routes,one);}catch(e){return null;}
    // 彈性掃描:在回應樹中找「長度>=5 的數字陣列,值域貼近昨收±15%」= 分線收盤序列
    let best=null;
    const arrs=[];
    const scan=(o,depth)=>{
      if(depth>4||!o)return;
      if(Array.isArray(o)){
        const nums=o.map(x=>parseFloat(Array.isArray(x)?x[1]??x[0]:x)).filter(v=>isFinite(v));
        if(nums.length>=5){
          arrs.push(nums);
          if(prev>0){
            const inBand=nums.filter(v=>v>prev*0.8&&v<prev*1.2).length;
            if(inBand>=nums.length*0.8&&(!best||nums.length>best.length))best=nums;
          }
        }
        o.forEach(x=>scan(x,depth+1));
      }else if(typeof o==='object'){Object.values(o).forEach(x=>scan(x,depth+1));}
    };
    scan(j,0);
    if(!best||best.length<5)return null;
    // 📊 量序列判別(行為特徵):與價等長(±3)、非負、不在價格帶、非等差(時間軸);
    //    近乎單調遞增且有成長=累計量→差分;其餘=分時量直接用
    let volA=null,volMode='';
    arrs.forEach(a=>{
      if(a===best||Math.abs(a.length-best.length)>3)return;
      if(a.some(v=>v<0))return;
      const inBand=a.filter(v=>v>prev*0.8&&v<prev*1.2).length;
      if(inBand>=a.length*0.5)return;
      const diffs=[];
      for(let i=1;i<a.length;i++)diffs.push(+(a[i]-a[i-1]).toFixed(6));
      const cnt={};let topN=0;
      diffs.forEach(x=>{cnt[x]=(cnt[x]||0)+1;if(cnt[x]>topN)topN=cnt[x];});
      if(diffs.length&&topN/diffs.length>=0.85)return;
      const mono=diffs.filter(x=>x>=-1e-6).length;
      const mode=(diffs.length&&mono/diffs.length>=0.9&&a[a.length-1]>a[0]*1.2)?'cum':'per';
      if(!volA||a.length>volA.length){volA=a;volMode=mode;}
    });
    let vArr=best.map(()=>0);
    if(volA){
      const per=volMode==='cum'?volA.map((v,i)=>i?Math.max(0,v-volA[i-1]):v):volA.slice();
      for(let i=0;i<best.length;i++)vArr[i]=Math.max(0,Math.round(per[i]||0));
    }
    // 以「最近交易時段日」09:00 起、每點一分鐘組時間軸(凌晨/週末開頁不會標成未來時間)
    const base=sessDate();
    base.setHours(9,0,0,0);
    const t0=Math.floor(base.getTime()/1000);
    return {t:best.map((_,i)=>t0+i*60),c:best.map(v=>+v.toFixed(2)),
            v:vArr,prev:+(+prev).toFixed(2)};
  }catch(e){return null;}
}
function clipSession(d){                                   // r506:序列夾取——只留最後一個交易日(跨日殘留=左側大空白的元兇)
  try{
    if(!d||!d.t||d.t.length<2)return d;
    const lastDay=tpDay(d.t[d.t.length-1]);
    let i0=0;
    for(let i=d.t.length-1;i>=0;i--){if(tpDay(d.t[i])!==lastDay){i0=i+1;break;}}
    if(i0<=0)return d;
    return Object.assign({},d,{t:d.t.slice(i0),c:d.c.slice(i0),v:Array.isArray(d.v)?d.v.slice(i0):d.v});
  }catch(e){return d;}
}
function gridIntra(d){                                     // r469:重採樣為每分鐘等距網格——稀疏來源(5分掃描/快照)不再扭曲時間軸
  try{
    if(!d||!d.t||d.t.length<2)return d;
    if((d.t[d.t.length-1]-d.t[0])>6.5*3600)return d;       // 跨度超過一個交易日 → 非日內,不動
    const t0=Math.floor(d.t[0]/60)*60,t1=Math.floor(d.t[d.t.length-1]/60)*60;
    if(t1<=t0)return d;
    const n=Math.round((t1-t0)/60)+1;
    if(n>1200)return d;
    const c=new Array(n).fill(null),v=new Array(n).fill(0);
    for(let i=0;i<d.t.length;i++){
      const k=Math.round((Math.floor(d.t[i]/60)*60-t0)/60);
      if(k<0||k>=n)continue;
      if(d.c[i]!=null&&isFinite(+d.c[i]))c[k]=+d.c[i];      // 同分鐘取最後一筆=分收
      v[k]+=(d.v&&+d.v[i]>0)?+d.v[i]:0;
    }
    for(let k=1;k<n;k++)if(c[k]==null&&c[k-1]!=null){       // ≤3分鐘缺口前向填補;更長缺口誠實留白
      let g=1;while(k+g<n&&c[k+g]==null)g++;
      if(g<=3)c[k]=c[k-1];
    }
    const t=[];for(let k=0;k<n;k++)t.push(t0+k*60);
    return Object.assign({},d,{t,c,v});
  }catch(e){return d;}
}
function capLast(d,s){                                     // r469:線尾封頂=最新成交價(盤中=現在;收盤後同日=13:30),補齊中段等距留白
  try{
    if(!d||!d.t||!d.t.length||!s||!(+s.price>0))return d;
    const px=+(+s.price).toFixed(2);
    let li=d.c.length-1;while(li>=0&&d.c[li]==null)li--;
    if(li<0)return d;
    const lastC=+d.c[li];
    if(Math.abs(px/lastC-1)>0.5)return d;                  // 量級防護:源不匹配不硬縫
    const base=sessDate();base.setHours(13,30,0,0);
    const closeT=Math.floor(base.getTime()/1000);
    const open2=typeof marketOpen==='function'&&marketOpen();
    const tEnd=Math.floor((open2?Math.min(Date.now()/1000,closeT):closeT)/60)*60;
    const lastT=d.t[d.t.length-1];
    if(!Array.isArray(d.v)||d.v.length!==d.t.length)d.v=d.t.map(()=>0);
    if(tEnd<=lastT){d.c[li]=px;return d;}                  // 資料已到線尾時間 → 直接修補最後實點
    if(Math.abs(lastC-px)<1e-9)return d;
    for(let t2=lastT+60;t2<tEnd;t2+=60){d.t.push(t2);d.c.push(null);d.v.push(0);}   // 缺口留白,時間軸維持等距
    d.t.push(tEnd);d.c.push(px);d.v.push(0);
    return d;
  }catch(e){return d;}
}
function sanitizeIntra(d,truthPx){                         // r479:分線消毒——孤立長針剔除+時段長度封頂+時間嚴格遞增(時間域無關)
  try{
    if(!d||!d.t||d.t.length<3)return d;
    const t=[],c=[],v=[];
    const t0=d.t[0];
    const cap=t0+4.7*3600+900;                             // 09:00→13:42 再加緩衝;超出=跑錯時間域的野點
    let lastT=-Infinity;
    for(let i=0;i<d.t.length;i++){
      if(d.t[i]<=lastT)continue;                           // 時間必須嚴格遞增
      if((d.t[d.t.length-1]-t0)<=8*3600&&d.t[i]>cap)continue;   // 日內資料才封頂
      t.push(d.t[i]);c.push(d.c[i]==null?null:+d.c[i]);v.push((d.v&&+d.v[i])||0);
      lastT=d.t[i];
    }
    for(let i=1;i<c.length-1;i++){                          // 孤立長針:與前後都偏離>6%,且與最新真價矛盾 → 剔除
      if(c[i]==null||c[i-1]==null||c[i+1]==null)continue;
      const d1=Math.abs(c[i]/c[i-1]-1),d2=Math.abs(c[i]/c[i+1]-1);
      if(d1>0.06&&d2>0.06){
        if(!(truthPx>0)||Math.abs(c[i]/truthPx-1)>0.06)c[i]=null;
      }
    }
    const li=c.length-1;                                    // 線尾野點:與前點偏離>6% 且與最新真價矛盾 → 剔除
    if(li>=1&&c[li]!=null&&c[li-1]!=null){
      const dv=Math.abs(c[li]/c[li-1]-1);
      if(dv>0.06&&truthPx>0&&Math.abs(c[li]/truthPx-1)>0.06){t.pop();c.pop();v.pop();}
    }
    return Object.assign({},d,{t,c,v});
  }catch(e){return d;}
}
function padTail1330(d){                                   // r474:ECharts 備援引擎固定框架——補 null 空槽到 13:30(LWC 走 setVisibleRange,不吃這個)
  try{
    if(!d||!d.t||!d.t.length)return d;
    const dd0=new Date(d.t[0]*1000);
    if(!(dd0.getHours()>=8&&dd0.getHours()<=14))return d;
    const e2=new Date(dd0);e2.setHours(13,30,0,0);
    const tEnd=Math.floor(e2.getTime()/1000/60)*60;
    const lastT=d.t[d.t.length-1];
    if(lastT>=tEnd)return d;
    if(!Array.isArray(d.v)||d.v.length!==d.t.length)d.v=d.t.map(()=>0);
    for(let t2=lastT+60;t2<=tEnd;t2+=60){d.t.push(t2);d.c.push(null);d.v.push(0);}
    return d;
  }catch(e){return d;}
}
function prevCloseOf(s){                                   // r468:個股昨收單一事實來源(MIS y → 日K分片精確昨收 → 累積 → 推導)
  try{
    if(!s)return null;
    try{const y=(typeof RTC!=='undefined'&&RTC[s.id]&&+RTC[s.id].y>0)?+RTC[s.id].y:null;if(y)return y;}catch(e0){}
    try{                                                   // 日K分片:不受四捨五入漲跌幅污染的精確昨收
      const sh=shardOf(s),e=(KCACHE[sh]||{})[s.id];
      if(e&&e.o&&e.o.length>=2){
        const today=tpDay(Date.now()/1000);
        const lastD=e.d&&e.d.length?String(e.d[e.d.length-1]).slice(0,10):null;
        const c1=+e.o[e.o.length-1][3],c2=+e.o[e.o.length-2][3];
        const v=lastD===today?c2:c1;
        if(v>0)return v;
      }
    }catch(e2){}
    try{const a=(typeof STK_ACC!=='undefined')&&STK_ACC[s.id];if(a&&+a.prev>0)return +a.prev;}catch(e3){}
    if(s.chg!=null&&+s.price>0)return +(+s.price/(1+s.chg/100)).toFixed(2);
    return null;
  }catch(e){return null;}
}
function stitchStk(s){                                     // r468:任何來源更新現價後,把分線線尾縫到最新價(冷門股 MIS 不回也不再脫節)
  try{
    if(!s||!(+s.price>0)||s.market!=='TW')return;
    if(location.hash!=='#stock/'+s.id)return;
    if(typeof marketOpen==='function'&&!marketOpen())return;
    try{stkAccPush(s.id,+s.price,prevCloseOf(s)||null);}catch(e1){}   // 收進當日累積線(後端5分掃價同為真實成交價)
    try{                                                    // r508:合成/累積今日OHLC——MIS/富果都沒有的冷門股,日K今日棒也要活
      const r0=(typeof RTC!=='undefined')?(RTC[s.id]||(RTC[s.id]={})):null;
      if(r0){const px9=+s.price;
        if(!(r0.o>0))r0.o=px9;                              // 首見掃價當開盤近似(富果/MIS 到位會覆蓋為真值)
        r0.h=Math.max(+r0.h>0?+r0.h:px9,px9);
        r0.l=Math.min(+r0.l>0?+r0.l:px9,px9);
        r0.c=px9;
        if(!(r0.y>0)){const y0=prevCloseOf(s);if(y0>0)r0.y=y0;}
        liveKBar(s.id);
      }
    }catch(eK){}
    if(RT.intra&&RT.intra.id===s.id&&window.__stkToday)pokeChart(RT.intra,+s.price);
    const st=document.getElementById('intraStat');
    if(st){const keep=(st.innerHTML.split(' · ').slice(1)||[]).join(' · ');st.innerHTML=intraStatTxt(s,keep||null);}
    const lv9=document.getElementById('lvPx');if(lv9)lv9.textContent=s.price;     // r472:關鍵價位現價同步
    const px9=document.getElementById('dPx'),ch9=document.getElementById('dChg');
    if(px9)px9.textContent=s.price;
    if(ch9)ch9.innerHTML=chgHtml(s.chg);
  }catch(e){}
}
async function misIntraday(s){
  // 個股版:算出頻道與昨收後交給共用核心
  try{
    const ch=`${s.ex==='otc'?'otc':'tse'}_${s.id}.tw`;
    const prev=prevCloseOf(s)||s.price/(1+(s.chg||0)/100);
    return await misOhlcCore(ch,prev);
  }catch(e){return null;}
}
/* 加權第二備援:證交所官方「每5秒指數統計」(MI_5MINS_INDEX)→ 降採樣為1分全日走勢 */
async function twse5sIdx(prev){
  try{
    prev=+prev;
    if(!(prev>0))return null;
    const u='https://www.twse.com.tw/rwd/zh/TAIEX/MI_5MINS_INDEX?response=json&_='+Date.now();
    const routes=[
      ...(myWrap(u)?[[myWrap(u),0]]:[]),
      [u,0],
      ['https://corsproxy.io/?url='+encodeURIComponent(u),0],
      ['https://api.allorigins.win/raw?url='+encodeURIComponent(u),0],
      ['https://api.allorigins.win/get?url='+encodeURIComponent(u),1]];
    const one=async([url,wrap])=>{
      const r0=await fT(url,8000);
      if(!r0.ok)throw 0;
      let j0=await r0.json();
      if(wrap&&j0&&j0.contents){j0=JSON.parse(j0.contents);}
      if(!j0||!Array.isArray(j0.data)||!j0.data.length)throw 0;
      return j0;
    };
    let j;
    try{j=await routeRace('twse5s',routes,one);}catch(e){return null;}
    const rows=j.data;
    // 彈性找欄:時間欄=HH:MM:SS;指數欄=值域貼近昨收±15%(欄序改版也不怕)
    let tCol=-1,vCol=-1;
    const cols=(rows[0]||[]).length;
    for(let ci=0;ci<cols;ci++){
      if(/^\d{1,2}:\d{2}:\d{2}$/.test(String(rows[0][ci]||'').trim())){tCol=ci;break;}
    }
    for(let ci=0;ci<cols;ci++){
      if(ci===tCol)continue;
      const vals=rows.slice(0,60).map(r=>parseFloat(String(r[ci]||'').replace(/,/g,''))).filter(v=>isFinite(v));
      if(vals.length>=5&&vals.filter(v=>v>prev*0.85&&v<prev*1.15).length>=vals.length*0.9){vCol=ci;break;}
    }
    if(tCol<0||vCol<0)return null;
    const base=sessDate();                               // 錨定最近交易時段日(凌晨拿到的是前一日盤)
    const t=[],c=[];let lastMin=null;
    rows.forEach(r=>{
      const tm=String(r[tCol]||'').trim(),v=parseFloat(String(r[vCol]||'').replace(/,/g,''));
      if(!isFinite(v))return;
      const mch=tm.match(/^(\d{1,2}):(\d{2}):(\d{2})$/);
      if(!mch)return;
      const mk=mch[1]+':'+mch[2];
      if(mk===lastMin){c[c.length-1]=v;return;}     // 同一分鐘:留最後一筆=分收
      const d2=new Date(base);d2.setHours(+mch[1],+mch[2],0,0);
      lastMin=mk;t.push(Math.floor(d2.getTime()/1000));c.push(v);
    });
    if(c.length<5)return null;
    return {t,c:c.map(v=>+v.toFixed(2)),v:c.map(()=>0),prev:+prev.toFixed(2)};
  }catch(e){return null;}
}
async function seedStk(s){
  // 開頁即刻抓一筆即時報價當種子(不等 10 秒輪),圖更快出現
  try{
    const arr=await fetchMIS([`${s.ex==='otc'?'otc':'tse'}_${s.id}.tw`]);
    const m=(arr||[])[0];
    if(!m)return;
    const last=rtPx(m),y=parseFloat(m.y);
    if(!last)return;
    s.price=+last.toFixed(2);
    if(y>0)s.chg=+(((last-y)/y)*100).toFixed(2);
    try{snapPut(s.id,s.price,s.chg);}catch(e){}
    stkAccPush(s.id,last,y);
    try{candleFromMIS(s.id,m,last);}catch(e){}
    try{l5FromMIS(s.id,m);}catch(e){}                      // r528:開頁即出五檔,不等輪詢
    const st=document.getElementById('intraStat');
    if(st&&location.hash===KHASH)st.innerHTML=intraStatTxt(s);
    const px0=document.getElementById('dPx'),ch0=document.getElementById('dChg');
    if(px0)px0.textContent=s.price;
    if(ch0)ch0.innerHTML=chgHtml(s.chg);
  }catch(e){}
}
