/* ── 秒級即時報價:瀏覽器直連證交所 MIS 快照(每10秒,僅更新畫面上的個股)── */
const RT={lastOk:0};
/* 指數當日 OHLC(供日K長出今日這根) */
const IDXRTC={};
/* 個股當日走勢即時累積(看哪檔就累積哪檔;換日自動重置) */
const STK_ACC={};
function stkAcc(id){
  const today=tpDay(Date.now()/1000);
  let a=STK_ACC[id];
  if(!a||a.day!==today){
    a=STK_ACC[id]={day:today,t:[],c:[],v:[],prev:null};
    try{const sv=JSON.parse(localStorage.getItem('sacc_'+id)||'null');   // 還原今日已累積的走勢+大戶/散戶力道
      if(sv&&sv.day===today&&Array.isArray(sv.t)&&sv.t.length){
        a.t=sv.t;a.c=sv.c;
        a.v=(Array.isArray(sv.v)&&sv.v.length===sv.t.length)?sv.v:sv.t.map(()=>0);
        a.prev=sv.prev||null;
        if(Array.isArray(sv.bs))a.bs=sv.bs;
        if(Array.isArray(sv.bb))a.bb=sv.bb;
        if(Array.isArray(sv.sb))a.sb=sv.sb;}}catch(e){}
  }
  return a;
}
function stkAccSave(id){
  const now=Date.now();
  const a0=STK_ACC[id];
  if(!a0)return;
  if(a0.__sv&&now-a0.__sv<30000)return;                    // 每檔獨立30秒節流(原全域節流會讓多數股票存不到)
  a0.__sv=now;
  try{const a=STK_ACC[id];
    if(a&&a.t.length){
      const K=Math.max(0,a.t.length-320),cut=x=>Array.isArray(x)?x.slice(K):undefined;
      localStorage.setItem('sacc_'+id,JSON.stringify({day:a.day,t:a.t.slice(K),c:a.c.slice(K),
        v:cut(a.v),bs:cut(a.bs),bb:cut(a.bb),sb:cut(a.sb),prev:a.prev}));}}catch(e){}
}
function stkAccPush(id,last,y){
  if(!marketOpen())return;
  const a=stkAcc(id);
  if(a.t.length&&tpDay(a.t[a.t.length-1])!==tpDay(Date.now()/1000)){   // r518:換日防護——掛過夜的昨日殘留(走勢+力道)全清
    a.t=[];a.c=[];a.v=[];a.prev=null;
    if(Array.isArray(a.bs))a.bs=[];if(Array.isArray(a.bb))a.bb=[];if(Array.isArray(a.sb))a.sb=[];
    try{localStorage.removeItem('sacc_'+id);}catch(e){}
  }
  if(y>0&&!a.prev)a.prev=y;
  const now=Math.floor(Date.now()/1000);
  const i=a.t.length-1;
  if(i<0||now-a.t[i]>=(a.t.length<3?8:25)){
    a.t.push(now);a.c.push(+(+last).toFixed(2));a.v.push(0);
    stkAccSave(id);
    if(location.hash==='#stock/'+id){const s2=DATA.stocks.find(x=>x.id===id);if(s2)try{refreshIntraLight(s2);}catch(e){}}
  }else a.c[a.c.length-1]=+(+last).toFixed(2);
}
/* ══ 盤中即時警示:好股下殺至買進區 / 帶量突破整理區 ══ */
/* 盤中警訊:預設「關閉」(使用者主動開啟才通知);dip/brk 為兩種策略的個別開關 */
const AL={on:localStorage.getItem('alert_on')==='1',
          dip:localStorage.getItem('alert_dip')!=='0',
          brk:localStorage.getItem('alert_brk')!=='0',seen:null};
function alSeen(){
  const d=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Taipei'})).toISOString().slice(0,10);
  if(!AL.seen||AL.seen.d!==d){
    try{const s=JSON.parse(localStorage.getItem('al_seen')||'null');
        AL.seen=(s&&s.d===d)?s:{d,k:{}};}catch(e){AL.seen={d,k:{}};}
  }
  return AL.seen;
}
function alMark(key){const s=alSeen();s.k[key]=1;try{localStorage.setItem('al_seen',JSON.stringify(s));}catch(e){}}
function alGood(s){return s.market==='TW'&&s.al&&(total(s)>=66||s.thesis);}
function tpMins(){const d=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Taipei'}));return (d.getHours()-9)*60+d.getMinutes();}
function alToast(type,s,title,text){
  const box=document.getElementById('toasts');
  if(!box)return;
  while(box.children.length>=4)box.removeChild(box.firstChild);
  const el=document.createElement('div');
  el.className='toast '+(type==='dip'?'dip':'');
  el.innerHTML=`<div class="tt">${type==='dip'?'🎯 下殺至買進區':'🚀 帶量突破'} <span class="cls">✕</span></div>
    <div class="tx"><b>${s.name}(${s.id})</b> ${text}</div>`;
  el.onclick=e=>{
    if(e.target.classList.contains('cls')||!s.id||s.id==='系統'){el.remove();return;}
    location.hash='#stock/'+s.id;el.remove();
  };
  box.appendChild(el);
  setTimeout(()=>{try{el.remove();}catch(e){}},20000);
  if('Notification' in window&&Notification.permission==='granted'){
    try{const n=new Notification(title,{body:`${s.name}(${s.id})`+text.replace(/<[^>]+>/g,''),icon:'icon.png',tag:s.id+type});
        n.onclick=()=>{window.focus();location.hash='#stock/'+s.id;};}catch(e){}
  }
}
function alertCheck(s,m,last){
  if(!AL.on||!alGood(s))return;
  const a=s.al, seen=alSeen().k;
  // 條件一:多頭好股回檔進「左側買進區」(均線帶),且未破停損
  if(AL.dip&&a.bull&&last<=a.z1*1.005&&last>=a.stop){
    const key=s.id+'|dip';
    if(!seen[key]){
      alMark(key);
      alToast('dip',s,'🎯 好股下殺至買進區',
        `現價 ${last},回到均線帶 ${a.z0}~${a.z1}(綜合 ${total(s)} 分);左側分批參考區,停損 ${a.stop}`);
    }
  }
  // 條件二:帶量突破近月高(整理區上緣)
  const vol=parseFloat(String(m.v||'').replace(/,/g,''));
  if(AL.brk&&last>=a.h20*1.005&&vol>0&&a.v20>0){
    const prog=Math.max(cumPct(tpMins()),8)/100;   // 依盤中時間估的量能進度
    if(vol>=a.v20*prog*1.15){
      const key=s.id+'|brk';
      if(!seen[key]){
        alMark(key);
        alToast('brk',s,'🚀 帶量突破整理區',
          `現價 ${last} 站上近月高 ${a.h20},量能已達同時段均量 ${Math.round(vol/(a.v20*prog)*100)}%(綜合 ${total(s)} 分)`);
      }
    }
  }
}
/* 後端尚未提供 al 時,背景載入 K 線分片自行計算(僅盤中執行一次) */
let AL_SEEDED=false;
/* ══ 🌊 r579 戰法:外資連買 + 財報持續成長 + 有未來性 ══
   三道關卡缺一不可:
     ① 籌碼:外資連續買超 ≥3 日(且近5日累積為正,排除「買1張也算」的假連買)
     ② 財報:月營收 YoY 連 3 個月為正 或 三率三升;且最新月 YoY > 0
     ③ 未來性:futureOK(基本面 75+ / 成長產業 60+ / 有投資論述)
   掃 c/tw*.json 籌碼分片,結果進 window.__FGO 供雷達顯示。*/
let FGO_SEEDED=false, FGO_TS=0;
async function fgoSeed(force){
  try{
    if(!DATA||DATA.source!=='live')return;
    if(!force&&FGO_SEEDED&&Date.now()-FGO_TS<15*60*1000)return;
    FGO_SEEDED=true;FGO_TS=Date.now();
    const cand=(DATA.stocks||[]).filter(s=>s.market==='TW'&&!s.etf&&s.price>0&&futureOK(s));
    if(!cand.length){window.__FGO=[];return;}
    const out=[];
    for(const sh of await shardList('c')){
      const __k=sh.replace(/^c\/tw|\.json$/g,'');
      const grp=cand.filter(s=>twShardKey(s.id)===__k);
      if(!grp.length)continue;
      await loadShard(CCACHE,sh);
      grp.forEach(s=>{
        const e=(CCACHE[sh]||{})[s.id];
        if(!e||!Array.isArray(e.f)||e.f.length<5)return;
        // ① 外資連買
        let run=0;
        for(let i=e.f.length-1;i>=0;i--){if((e.f[i]||0)>0)run++;else break;}
        if(run<3)return;
        const sum5=e.f.slice(-5).reduce((a,b)=>a+(b||0),0);
        const sumRun=e.f.slice(-run).reduce((a,b)=>a+(b||0),0);
        if(sum5<=0||sumRun<100)return;                       // 連買量太小(<100張)不算
        // ② 財報持續成長
        const ry=Array.isArray(e.ry)?e.ry:[];
        let posM=0;
        for(let i=ry.length-1;i>=0;i--){if(ry[i]>0)posM++;else break;}
        const latestY=ry.length?ry[ry.length-1]:null;
        const n=(e.fq||[]).length-1;
        const rise=a=>Array.isArray(a)&&n>=1&&a[n]!=null&&a[n-1]!=null&&a[n]>a[n-1];
        const t3=rise(e.gm)&&rise(e.om)&&rise(e.nm);
        const revOK=(posM>=3)||(t3&&latestY!=null&&latestY>0);
        if(!revOK)return;
        if(latestY!=null&&latestY<=0)return;                 // 最新月轉負一律排除
        // ③ 投信同買加分
        let trun=0;
        if(Array.isArray(e.t)){for(let i=e.t.length-1;i>=0;i--){if((e.t[i]||0)>0)trun++;else break;}}
        const tSum5=Array.isArray(e.t)?e.t.slice(-5).reduce((a,b)=>a+(b||0),0):0;
        const bp=Array.isArray(e.bp)?e.bp:[];
        const bw4=bp.length>4?+(bp[bp.length-1]-bp[bp.length-5]).toFixed(2):null;
        const tags=[];
        if(trun>=2||tSum5>0)tags.push('投信同買');
        if(t3)tags.push('三率三升');
        if(bw4!=null&&bw4>=0.3)tags.push(`大戶四週 +${bw4}pp`);
        if(s.thesis)tags.push('有投資論述');
        out.push({id:s.id,run,sumRun:Math.round(sumRun),sum5:Math.round(sum5),
          posM,latestY:latestY!=null?+(+latestY).toFixed(1):null,t3,tags,
          score:run*10+(t3?25:0)+(posM>=3?posM*4:0)+(tags.includes('投信同買')?15:0)+(total(s)||0)*0.4});
      });
      await new Promise(r=>setTimeout(r,400));
    }
    out.sort((a,b)=>b.score-a.score);
    window.__FGO=out;
    try{if(typeof renderRadar==='function')renderRadar();}catch(e2){}
  }catch(err){window.__FGO=window.__FGO||[];}
}
lazyRun('#radar,#pickBox',()=>fgoSeed(),15*60*1000);     // r701
async function alSeed(){
  if(AL_SEEDED||!DATA||DATA.source!=='live')return;
  const need=(DATA.stocks||[]).filter(s=>s.market==='TW'&&!s.al&&(total(s)>=66||s.thesis));
  if(!need.length){AL_SEEDED=true;return;}
  if(!marketOpen())return;   // 收盤不浪費流量,明天開盤再補
  AL_SEEDED=true;
  for(const sh of await shardList('k')){
    const __k=sh.replace(/^k\/tw|\.json$/g,'');
    await loadShard(KCACHE,sh);
    need.filter(s=>twShardKey(s.id)===__k).forEach(s=>{
      const e=(KCACHE[sh]||{})[s.id];
      if(!e||!e.o||e.o.length<60)return;
      const o=e.o,closes=o.map(x=>x[3]),vols=o.map(x=>x[4]);
      const ma20=avg(closes.slice(-20)),ma60=avg(closes.slice(-60));
      const h20=Math.max(...o.slice(-20).map(x=>x[1]));
      const z1=Math.max(ma20,ma60),z0=Math.min(ma20,ma60);
      s.al={z1:+z1.toFixed(2),z0:+z0.toFixed(2),stop:+(z0*0.97).toFixed(2),
            h20:+h20.toFixed(2),v20:Math.round(avg(vols.slice(-20))),bull:ma20>ma60?1:0};
    });
    await new Promise(r=>setTimeout(r,600));
  }
}
lazyRun('#alBox,#radar,#pickBox',alSeed,10*60*1000);     // r701
/* ══ 戰法模組 #1:🐢 海龜交易法則(EP.334)══
   規則:①突破20日新高進場(上次20日突破若獲利→本次跳過,改看55日突破)
        ②初始停損 = 進場價 − 2N(N = ATR20)
        ③金字塔加碼:每上漲 0.5N 加一單,最多加 3 次(共 4 Units)
        ④出場:跌破 10 日低點
   架構:之後的戰法(螺旋起漲區…)照同樣模式擴充 → xxxCalc(單檔計算) + xxxSeed(分片掃描) + STRATS 註冊 + 個股詳情區塊。*/
function calcATR(o,endEx,p){ // o=[[開,高,低,收,量]...];取 endEx(不含)往前 p 期 TR 簡單平均
  p=p||20;const e=endEx==null?o.length:endEx;
  if(e<p+1)return null;
  let sum=0;
  for(let i=e-p;i<e;i++){
    const h=o[i][1],l=o[i][2],pc=o[i-1][3];
    sum+=Math.max(h-l,Math.abs(h-pc),Math.abs(l-pc));
  }
  return sum/p;
}
function turtleCalc(o,livePx){
  if(!Array.isArray(o)||o.length<40)return null;
  const n=o.length;
  const hiOf=(a,b)=>{let m=-Infinity;for(let i=Math.max(0,a);i<b;i++)m=Math.max(m,o[i][1]);return m;};
  const loOf=(a,b)=>{let m=Infinity;for(let i=Math.max(0,a);i<b;i++)m=Math.min(m,o[i][2]);return m;};
  const last=(livePx&&livePx>0)?livePx:o[n-1][3];
  const h20=hiOf(n-21,n-1);                       // 不含今日的前 20 日最高
  const h55=n>=57?hiOf(n-56,n-1):null;            // 不含今日的前 55 日最高
  const l10=loOf(n-11,n-1);                       // 不含今日的前 10 日最低(出場線)
  const N=calcATR(o,null,20);
  if(!N||!(last>0)||!(h20>0))return null;
  const brk20=last>h20, brk55=h55!=null&&last>h55;
  // 濾網:回測「最近一次已完成的 20 日突破」;獲利 → 依法則跳過本次 20 日訊號
  let lastRes=null;
  for(let i=n-2;i>=22;i--){
    const hh=hiOf(i-20,i);
    if(o[i][3]>hh && o[i-1][3]<=hiOf(i-21,i-1)){  // i = 收盤首次突破日
      const entry=o[i][3], Ni=calcATR(o,i+1,20)||N, stop=entry-2*Ni;
      for(let j=i+1;j<n;j++){
        if(o[j][2]<=stop){lastRes='loss';break;}
        if(o[j][3]<loOf(j-10,j)){lastRes=(o[j][3]>entry)?'win':'loss';break;}
      }
      break;                                       // 只評估最近一次
    }
  }
  const skip20=lastRes==='win';
  const sigType=(brk20&&!skip20)?'20':(brk55?'55':null);
  return {N:+N.toFixed(2),h20:+h20.toFixed(2),h55:h55!=null?+h55.toFixed(2):null,
    l10:+l10.toFixed(2),last:+(+last).toFixed(2),brk20,brk55,skip20,lastRes,sigType,
    stop:+(last-2*N).toFixed(2),
    adds:[1,2,3].map(k=>+(last+0.5*N*k).toFixed(2)),
    riskPct:+(2*N/last*100).toFixed(1),
    gap20:+((h20-last)/last*100).toFixed(1)};
}
/* 個股詳情:🐢 海龜法則檢視區塊 */
function turtleBlock(s,t){
  if(!t)return '';
  const fmt=v=>(+v).toLocaleString();
  const st=t.sigType==='20'
      ?'<b style="color:var(--down)">✅ 今日觸發 20 日突破</b>'
    :t.sigType==='55'
      ?'<b style="color:var(--down)">✅ 今日觸發 55 日突破</b>'+(t.skip20?'(上次 20 日突破獲利 → 依法則跳過 20 日訊號,改採 55 日)':'')
    :(t.brk20&&t.skip20)
      ?`<b style="color:var(--amber)">⏸ 已過 20 日高,但依法則跳過</b>(上次 20 日突破獲利 → 本次 20 日訊號不進場;等 55 日突破 ${t.h55!=null?fmt(t.h55):'—'})`
      :`⏳ 尚未突破 —— 距 20 日高 ${fmt(t.h20)} 還差 <b>${t.gap20}%</b>`;
  const resTxt=t.lastRes==='win'?'上次 20 日突破:<b style="color:var(--down)">獲利出場</b> → 本次 20 日訊號跳過'
             :t.lastRes==='loss'?'上次 20 日突破:<b style="color:var(--up)">虧損出場</b> → 本次 20 日訊號有效'
             :'近期資料內找不到已完成的 20 日突破紀錄 → 20 日訊號視為有效';
  const cell=(g,k,v,d)=>`<div style="background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:10px 12px">
    <div data-g="${g}" style="font-size:12px;color:var(--mut);font-weight:800;letter-spacing:.05em;cursor:help;border-bottom:1px dotted var(--dim);display:inline-block">${k}</div>
    <div style="font-family:var(--mono);font-size:17px;font-weight:600;margin-top:4px">${v}</div>
    <div style="font-size:12px;color:var(--dim);margin-top:3px;line-height:1.6">${d}</div></div>`;
  return `<div class="dim-block" style="border-left:4px solid #5BD9C0">
    <h3>🐢 海龜法則檢視 <span class="ds">20/55日突破 · ATR · 加碼 · 出場(規則化)</span></h3>
    <div class="dim-note" style="margin:2px 0 8px">${st}</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px">
      ${cell('ATR','N(ATR20)',fmt(t.N),'20 日平均真實波幅,海龜所有距離都用 N 度量')}
      ${cell('停損','停損 −2N',fmt(t.stop),`以現價 ${fmt(t.last)} 進場試算,單筆風險約 ${t.riskPct}%`)}
      ${cell('金字塔加碼','加碼三段 +0.5N',t.adds.map(fmt).join(' / '),'每上漲 0.5N 加一單,最多加 3 次(共 4 Units)')}
      ${cell('出場','出場線·10日低',fmt(t.l10),'收盤跌破 10 日低點 → 短線趨勢轉弱,出場離場')}
    </div>
    <div class="dim-note" style="margin-top:8px">${resTxt}${t.h55!=null?` · 55 日高 ${fmt(t.h55)}`:''}。K 線圖上的 <b style="color:var(--down)">🐢 出場·10日低</b> 虛線每日隨資料更新。</div>
    <div class="dim-note" style="color:var(--dim)">法則精神:趨勢是你的朋友、嚴格紀律執行、控制風險、讓利潤奔跑。此為以現價套入海龜參數的<b>規則化試算,不是投資建議</b>——它不知道你的實際成本與部位;到價要不要執行,由你自己決定。</div>
  </div>`;
}
/* 背景掃描:載入台股 K 線分片,找出今日觸發海龜突破的個股(結果陸續補進雷達) */
let TURTLE_SEEDED=false;
async function turtleSeed(){
  if(TURTLE_SEEDED||!DATA||DATA.source!=='live')return;
  TURTLE_SEEDED=true;
  const byId={};(DATA.stocks||[]).forEach(s=>{if(s.market==='TW'&&!s.etf&&s.price!=null)byId[s.id]=s;});
  const out=[];
  const gems=[];
  const hot=(()=>{try{return zt8Hot();}catch(e){return new Set();}})();
  for(const sh of await shardList('k')){
    const __k=sh.replace(/^k\/tw|\.json$/g,'');
    await loadShard(KCACHE,sh);
    Object.keys(KCACHE[sh]||{}).forEach(id=>{
      const s=byId[id];if(!s)return;
      const e=KCACHE[sh][id];
      if(!e||!Array.isArray(e.o)||e.o.length<40)return;
      const vols=e.o.slice(-20).map(x=>x[4]||0);
      if(avg(vols)<500)return;                    // 流動性濾網:20日均量 ≥ 500 張
      const t=turtleCalc(e.o,s.price);
      // 💎 蓄勢好股:基本面 ≥78 分、未突破、距 20 日高 3~20%
      try{
        if(t&&s.f&&s.f.score>=78&&!t.sigType&&!t.brk20&&t.gap20>=3&&t.gap20<=20){
          const g=gemDiag(s,e.o,t,hot);
          if(g)gems.push({id,g:{type:'gem',label:`💎 蓄勢好股 ${g.lit}/8`,
            desc:`基本面 ${g.f} 分未發動 · 發動訊號已亮 ${g.lit}/8 · 主因:${g.reasons[0].t.split('——')[0].split(':')[0]} · 確認點:帶量過 ${g.h20}(+${g.gap}%)`}});
        }
      }catch(e2){}
      if(!t||!t.sigType)return;
      out.push({id,g:{type:'turtle',
        label:t.sigType==='55'?'🐢 55日突破':'🐢 20日突破',
        desc:`突破${t.sigType}日高 ${t.sigType==='55'?t.h55:t.h20} · N=${t.N} · 現價進場停損 ${t.stop}(−2N) · 加碼 ${t.adds.join('/')} · 跌破10日低 ${t.l10} 出場`
          +(t.sigType==='55'&&t.skip20?' · 上次20日突破獲利→依法則改採55日':'')}});
    });
    window.__TURTLE=out.slice();
    window.__GEM=gems.slice();
    if(document.getElementById('radar')){try{renderRadar();}catch(e){}}
    await new Promise(r=>setTimeout(r,500));
  }
}
