/* ══ 戰法模組 #2:⚡ 漲停8招(股·價·大·漲·發·財·成·群)══
   股:股本 < 50 億(籌碼集中拉升容易)  價:< 200 元(想像空間大)
   大:大資金買超(大戶/法人持續買超)  漲:一波上漲中出現 ≥3 根漲停(漲基因)
   發:剛站上月線或季線(趨勢剛轉強)  財:近期本益比 < 20 倍(安全邊際)
   成:今日量 ≥ 昨日 2 倍(資金進場)  群:族群熱(當日強勢族群)*/
function zt8Hot(){ // 當日強勢族群:平均漲幅前 5 且為正(至少 4 檔有報價)
  const g={};
  (DATA.stocks||[]).filter(s=>s.market==='TW'&&!s.etf&&typeof s.chg==='number')
    .forEach(s=>{(g[s.sector]=g[s.sector]||[]).push(s.chg);});
  return new Set(Object.entries(g).filter(([_,a])=>a.length>=4)
    .map(([k,a])=>[k,a.reduce((x,y)=>x+y,0)/a.length])
    .filter(([_,v])=>v>0).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([k])=>k));
}
function zt8Calc(s,o,ctx){
  const items=[];
  const add=(k,ok,txt)=>items.push({k,ok:!!ok,txt});
  // 股:股本 < 50 億(證交所/櫃買公司基本資料,實收資本額)
  const capRaw=ctx&&ctx.cap&&ctx.cap[s.id];
  const cz=capSize(capRaw);
  add('股',cz!=null&&cz.e<50,cz?`股本 ${cz.e>=100?cz.e.toFixed(0):cz.e.toFixed(1)} 億·${cz.t}${cz.e<50?'':'(≥50億)'}`
    :(ctx&&ctx.loading?'股本載入中…(證交所資料抓取中)':'股本資料缺(稍後重整再看)'));
  // 價:< 200 元
  const px=s.price;
  add('價',px!=null&&px<200,px!=null?`價格 ${px} 元${px<200?'':'(≥200)'}`:'無報價');
  // 大:大資金買超(外資/投信 5 日買超 或 400張大戶週增)
  const r=chipRaw(s);
  const hits=[r.f5>0?'外資買超':null,r.t5>0?'投信買超':null,r.bigw>0?'大戶週增':null].filter(Boolean);
  add('大',hits.length>0,hits.length?hits.join('+'):'外資/投信/大戶未見買超');
  // K 線三條件:漲基因、剛發動、量增倍
  let zt=0,launch=false,vol2=false,ztTxt='K線資料缺',lTxt='K線資料缺',vTxt='K線資料缺';
  if(Array.isArray(o)&&o.length>=25){
    const n=o.length,closes=o.map(x=>x[3]);
    // 漲:自近 60 日最低點起的這一波,漲停(日漲 ≥9.5%)根數
    const w=Math.min(60,n);let li=n-w;
    for(let i=n-w;i<n;i++)if(o[i][2]<o[li][2])li=i;
    for(let i=Math.max(li,1);i<n;i++)if(closes[i]>=closes[i-1]*1.095)zt++;
    ztTxt=`波段內漲停 ${zt} 根${zt>=3?'':'(<3)'}`;
    // 發:今日在月線/季線之上,且近 8 日內曾在該線之下(剛站上,不是早就在上面)
    const ma=(p,i)=>{if(i<p-1)return null;let s2=0;for(let j=i-p+1;j<=i;j++)s2+=closes[j];return s2/p;};
    const lastC=(px!=null&&px>0)?px:closes[n-1];
    const chk=p=>{
      const m=ma(p,n-1);if(m==null||lastC<=m)return false;
      for(let i=Math.max(p-1,n-9);i<n-1;i++){const mi=ma(p,i);if(mi!=null&&closes[i]<mi)return true;}
      return false;};
    const on20=chk(20),on60=chk(60);
    launch=on20||on60;
    lTxt=launch?`剛站上${on20?'月線':''}${on20&&on60?'+':''}${on60?'季線':''}`:'未剛站上月/季線';
    // 成:最新一根日K的量 ≥ 前一根 2 倍
    const v1=o[n-1][4]||0,v0=o[n-2][4]||0;
    vol2=v0>0&&v1>=v0*2;
    vTxt=v0>0?`量 ${(v1/v0).toFixed(1)} 倍(${Math.round(v1).toLocaleString()} vs ${Math.round(v0).toLocaleString()} 張)`:'量能資料缺';
  }
  add('漲',zt>=3,ztTxt);
  add('發',launch,lTxt);
  // 財:近期本益比 < 20 倍
  const pe=(s.pe&&s.pe>0)?s.pe:((s.fpe&&s.fpe>0)?s.fpe:null);
  add('財',pe!=null&&pe<20,pe!=null?`本益比 ${pe} 倍${pe<20?'':'(≥20)'}`:'無本益比(近四季虧損或資料缺)');
  add('成',vol2,vTxt);
  // 群:族群熱
  const hot=ctx&&ctx.hot?ctx.hot.has(s.sector):false;
  add('群',hot,hot?`${s.sector} 為今日強勢族群`:`${s.sector||'族群'} 今日非熱門`);
  return {items,score:items.filter(x=>x.ok).length};
}
