const MY_PROXY_DEFAULT='https://muddy-cake-cb69.frankccc199.workers.dev';   // 站方自家 Worker:全站自動套用,免設定
function myProxy(){try{const v=(localStorage.getItem('my_proxy')||'').trim();return v||MY_PROXY_DEFAULT;}catch(e){return MY_PROXY_DEFAULT;}}   /* 設定欄位仍可覆蓋(填入其他網址時優先) */
const ROUTE_MEM={};
function routeMemGet(k){if(ROUTE_MEM[k]!=null)return ROUTE_MEM[k];try{return ROUTE_MEM[k]=+(localStorage.getItem('rt_route_'+k)||0);}catch(e){return 0;}}
function routeMemSet(k,i){ROUTE_MEM[k]=i;try{localStorage.setItem('rt_route_'+k,String(i));}catch(e){}}
async function routeRace(kind,routes,runner){
  // 平常只打「上次成功那條」(省流量防 429);失敗才並行剩餘路線並記住新贏家。
  // 🏁 升級:贏家不是路0(自家Worker)時,每次都讓路0一起參賽先到先贏——
  //    自家代理只要恢復就自動奪回王座,杜絕「偶發失敗後長期卡在慢速公共代理」的慢性不即時。
  const fav=Math.min(routeMemGet(kind),routes.length-1);
  if(fav===0){
    try{return await runner(routes[0]);}catch(e){}
  }else{
    try{
      const w=await Promise.any([
        runner(routes[fav]).then(v=>[v,fav]),
        runner(routes[0]).then(v=>[v,0])]);
      if(w[1]!==fav)routeMemSet(kind,w[1]);
      return w[0];
    }catch(e){}
  }
  const rest=routes.map((r,i)=>[r,i]).filter(([,i])=>i!==fav);
  const winner=await Promise.any(rest.map(async([r,i])=>{const v=await runner(r);return [v,i];}));
  routeMemSet(kind,winner[1]);
  return winner[0];
}
function myWrap(u){const p=myProxy();return p?p.replace(/\/+$/,'')+'/?url='+encodeURIComponent(u):null;}
async function fetchMISOne(chans){
  const mis='https://mis.twse.com.tw/stock/api/getStockInfo.jsp?ex_ch='
    +chans.join('|')+'&json=1&delay=0&_='+Date.now();
  const routes=[                                            // 並行先到先贏;自家代理(若有設)永遠第一路
    ...(myWrap(mis)?[[myWrap(mis),0]]:[]),
    [mis,0],
    ['https://corsproxy.io/?url='+encodeURIComponent(mis),0],
    ['https://api.allorigins.win/raw?url='+encodeURIComponent(mis),0],
    ['https://api.codetabs.com/v1/proxy?quest='+encodeURIComponent(mis),0],
    ['https://api.allorigins.win/get?url='+encodeURIComponent(mis),1]];
  const one=async ([url,wrap])=>{
    const res=await fT(url,6000);
    if(!res.ok)throw 0;
    let j=await res.json();
    if(wrap&&j&&j.contents){try{j=JSON.parse(j.contents);}catch(e){throw 0;}}
    if(j&&j.msgArray)return j.msgArray;
    throw 0;
  };
  try{return await routeRace('mis',routes,one);}catch(e){return null;}
}
async function fetchMIS(chans){
  if(!chans||!chans.length)return null;
  const CH=90;                                              // MIS 批次上限保險:切 ≤90 檔多包並行
  const parts=[];
  for(let i=0;i<chans.length;i+=CH)parts.push(chans.slice(i,i+CH));
  const res=await Promise.all(parts.map(fetchMISOne));
  let out=null;
  res.forEach(r=>{if(r){out=(out||[]).concat(r);}});
  return out;
}
function rtPx(m){
  /* 取價鐵律:只信真實成交價;無成交(試撮/處置分盤間隔)寧可不更新,
     絕不退回昨收——退昨收會製造「假 0.00%+分時圖懸崖」的錯誤畫面 */
  const P=k=>{const v=String(m[k]||'-').split('_')[0],f=parseFloat(v);return f>0?f:null;};
  const z=P('z');
  if(z)return z;                       // 有成交:用成交價
  const b=P('b'),a=P('a');
  if(b&&!a)return b;                   // 漲停鎖死(只剩買單掛漲停):用買價
  if(a&&!b)return a;                   // 跌停鎖死(只剩賣單掛跌停):用賣價
  return null;                         // 無成交:保留上一筆真實價,等下一次撮合
}
/* 捲動位置保持:資料重繪不打斷閱讀 */
function uiBusy(){return Date.now()-(window.__lastAct||0)<3500;}   // r719:使用者互動中(滾動/觸控/按鍵 3.5 秒內)
['scroll','wheel','touchstart','pointerdown','keydown'].forEach(ev=>addEventListener(ev,()=>{window.__lastAct=Date.now();},{passive:true,capture:true}));
function keepScroll(fn){
  if(uiBusy()){clearTimeout(window.__ksT);window.__ksT=setTimeout(()=>keepScroll(fn),3600);return;}   // r719:互動中排隊延後,不在你眼前重繪
  if(window.__navScrollTs&&Date.now()-window.__navScrollTs<8000){try{fn();}catch(e){}return;}
  const y=window.scrollY,x=window.scrollX;
  try{fn();}finally{
    requestAnimationFrame(()=>{
      if(window.__navScrollTs&&Date.now()-window.__navScrollTs<8000)return;
      if(Math.abs(window.scrollY-y)>2||Math.abs(window.scrollX-x)>2)
        window.scrollTo({top:y,left:x,behavior:'instant'});
      requestAnimationFrame(()=>{
        if(Math.abs(window.scrollY-y)>2)window.scrollTo({top:y,left:x,behavior:'instant'});
      });
    });
  }
}
