function openish(){
  // 收盤後~19:30 仍持續同步「今日」資料(MIS 收盤快照+Yahoo 回補),不再下午就凍結
  const t=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Taipei'}));
  const d=t.getDay(),m=t.getHours()*60+t.getMinutes();
  return d>=1&&d<=5&&m>=535&&m<=1170;
}
