/* ── 機會雷達:規則化訊號(非投資建議)── */
const avg=a=>a.reduce((x,y)=>x+y,0)/a.length;
function chipRaw(s){ // 取籌碼原始數值:優先用 raw(真實資料),否則解析文字(範例)
  if(s.c&&s.c.raw) return s.c.raw;
  const kv=(s.c&&s.c.kv)||{}, r={};
  const big=kv['400張大戶']||kv['400張大戶持股']||'';
  let m=/週([+-][\d.]+)/.exec(big); if(m) r.bigw=parseFloat(m[1]);
  m=/([\d.]+)%/.exec(big); if(m) r.big=parseFloat(m[1]);
  const t=String(kv['投信5日']||kv['投信5日買賣超']||'');
  m=/([+-][\d,]+)/.exec(t); if(m) r.t5=parseFloat(m[1].replace(/,/g,''));
  const f=String(kv['外資5日']||kv['外資5日買賣超']||'');
  m=/([+-][\d,]+)/.exec(f); if(m) r.f5=parseFloat(m[1].replace(/,/g,''));
  return r;
}
function signals(s){
  const hasReal=Array.isArray(s.ohlc)&&s.ohlc.length>25;
  const out=[];
  // ⓪ 大戶進場(只靠籌碼,不需要K線)
  const r0=chipRaw(s);
  if(r0.bigw!==undefined && r0.bigw>=0.7)
    out.push({type:'whale',label:'大戶進場',
      desc:`400張大戶持股週增 +${r0.bigw.toFixed(2)} 個百分點`+
        (r0.big?`,目前 ${r0.big}%`:'')+((r0.t5>0&&r0.f5>0)?',外資投信同步買超':r0.t5>0?',投信同步買超':'')});
  if(!hasReal && DATA.source==='live') return out; // 真實模式缺K線 → 不做型態訊號
  const ohlc=hasReal?s.ohlc:demoOHLC(s);
  const closes=ohlc.map(x=>x[3]).slice(-60);
  const last=s.price||closes[closes.length-1];
  const ma20=avg(closes.slice(-20)), ma60=avg(closes);
  const T=total(s);
  // ① 突破整理區:突破近 40 日整理平台(排除最近 5 日),平台高低差 <15%
  const prior=closes.slice(-45,-5);
  const hi=Math.max(...prior), lo=Math.min(...prior);
  if(last>hi && (hi-lo)/lo<0.15 && T>=65)
    out.push({type:'break',label:'突破整理區',
      desc:`站上平台高點 ${hi.toFixed(1)},整理區間僅 ${((hi-lo)/lo*100).toFixed(0)}%,綜合 ${T} 分`});
  // ② 下殺近關鍵價:好股票自波段高點回檔 ≥7%,現價貼近季線(-2%~+4%)
  const h20=Math.max(...closes.slice(-20));
  const off=(last-h20)/h20*100, d60=(last-ma60)/ma60*100;
  if(T>=64 && off<=-7 && d60>=-4 && d60<=4)
    out.push({type:'dip',label:'下殺近關鍵價',
      desc:`自波段高點回檔 ${Math.abs(off).toFixed(0)}%,回測季線 ${ma60.toFixed(1)} 附近,綜合 ${T} 分`});
  // ③ 三力強勢:綜合 ≥78 且站上 20MA、均線多頭
  if(T>=78 && last>ma20 && ma20>ma60)
    out.push({type:'strong',label:'三力強勢',
      desc:`綜合 ${T} 分,多頭排列沿 20MA 推進,基本/籌碼/技術同向`});
  return out;
}
/* ── 盤面脈動:強勢族群 + 焦點個股(依最新報價即時計算)── */
/* 族群卡點擊:一次性委派,重繪不失效 */
(function(){
  const box=document.getElementById('pulseSec');
  if(!box||box.dataset.b)return;
  box.dataset.b='1';
  box.addEventListener('click',e=>{
    const c=e.target.closest('.ps-card');
    if(!c||!c.dataset.sec)return;
    const sec=c.dataset.sec;
    window.__navScrollTs=Date.now();
    const m2=sec.startsWith('美股')?'US':'TW';
    if(m2!==window.GMKT)setGMKT(m2,true);
    mkt='ALL'; sector=sec; page=1;
    document.querySelectorAll('#mktSeg button').forEach(x=>x.classList.toggle('on',x.dataset.m==='ALL'));
    renderChips(); render();
    const t=document.getElementById('chips'); if(t) t.scrollIntoView({behavior:'smooth'});
  });
})();
function renderPulse(){
  const secBox=document.getElementById('pulseSec');
  const stBox=document.getElementById('pulseStocks');
  const priced=DATA.stocks.filter(s=>!s.etf&&s.price!=null&&typeof s.chg==='number'&&s.market===(window.GMKT||'TW'));
  // 族群強度:平均漲幅排行(至少4檔有報價的族群才列入)
  const g={};
  priced.forEach(s=>{(g[s.sector]=g[s.sector]||[]).push(s);});
  const rows=Object.entries(g).filter(([_,a])=>a.length>=4).map(([sec,a])=>{
    const avg=a.reduce((x,s)=>x+s.chg,0)/a.length;
    const up=a.filter(s=>s.chg>0).length;
    const lead=a.slice().sort((x,y)=>y.chg-x.chg)[0];
    return {sec,avg,up,n:a.length,lead};
  }).sort((a,b)=>b.avg-a.avg);
  secBox.innerHTML=rows.length?rows.slice(0,6).map((r,i)=>
    `<div class="idx-card ps-card" data-sec="${r.sec}" tabindex="0" role="button" aria-label="查看${r.sec}">
      <div class="nm">${i===0?'🔥 ':''}${r.sec}${String(r.sec).startsWith('美股')?' <span class="c-code" title="美股個股為前日收盤資料">盤後</span>':''} <span style="color:var(--dim)">›</span></div>
      <div class="vl">${chgHtml(+r.avg.toFixed(2))}</div>
      <div class="lead">上漲 ${r.up}/${r.n} · 領漲 ${r.lead.name} ${r.lead.chg>0?'+':''}${r.lead.chg}%</div>
    </div>`).join('')
    :'<div class="idx-card"><div class="nm">尚無報價資料,等資料更新後顯示</div></div>';
  // 族群卡點擊:事件委派於永久容器(見下方一次性綁定)
  // 焦點個股:強勢上攻(漲幅大且評分佳)、好股重挫(高分股大跌,值得觀察)
  const hot=priced.filter(s=>s.chg>=3.5&&total(s)>=58)
    .sort((a,b)=>b.chg-a.chg).slice(0,6)
    .map(s=>({s,label:'強勢上攻',cls:'tg-hot',
      desc:`今日 +${s.chg}%,綜合 ${total(s)} 分${s.sig&&s.sig.length?' · 觸發「'+s.sig[0].label+'」':''} · ${s.sector}`}));
  const drop=priced.filter(s=>s.chg<=-3.5&&total(s)>=68)
    .sort((a,b)=>a.chg-b.chg).slice(0,4)
    .map(s=>({s,label:'好股重挫',cls:'tg-drop',
      desc:`今日 ${s.chg}%,綜合 ${total(s)} 分的體質股大跌,留意是否殺到關鍵價 · ${s.sector}`}));
  const items=[...hot,...drop];
  stBox.innerHTML=items.length?items.map(({s,label,cls,desc})=>
    `<div class="r-card" data-id="${s.id}" tabindex="0" role="button">
      <span class="r-tag ${cls}">${label}</span>
      <span class="r-name">${s.name} <span class="c-code">${s.id}</span> <b class="rpx">${s.price??'—'}</b> <span style="font-family:var(--mono);font-size:13px">${chgHtml(s.chg)}</span><span class="mini-candle" data-candle="${s.id}"></span></span>
      <span class="r-desc">${desc}</span></div>`).join('')
    :'<div class="r-empty">目前沒有明顯異動的焦點個股(休市或盤勢平靜)。</div>';
  stBox.querySelectorAll('.r-card').forEach(c=>{
    c.onclick=()=>{location.hash='#stock/'+c.dataset.id;};
    c.onkeydown=e=>{if(e.key==='Enter'){location.hash='#stock/'+c.dataset.id;}};
  });
}

