/* 未來性濾網:基本面夠強 或 成長型產業+及格基本面 或 精選論點股 */
const GROWTH_SECTORS=new Set(['半導體業','電子零組件業','電腦及週邊設備業','光電業','通信網路業','其他電子業','資訊服務業','電子通路業','數位雲端','綠能環保']);
function futureOK(s){
  const f=s.f&&s.f.score||0;
  if(s.thesis)return true;
  if(f>=75)return true;
  return f>=60&&GROWTH_SECTORS.has(s.sector||'');
}
function sideItems(){
  const out=[];
  (DATA.stocks||[]).forEach(s=>{
    if(s.market!=='TW'||!s.al||s.price==null||!futureOK(s))return;
    const a=s.al,f=s.f?s.f.score:0,c=s.c?s.c.score:0,t=s.t?s.t.score:0;
    // ◀ 左側·價值回檔:多頭架構 + 價格回到均線買進區(未破停損) + 籌碼未潰
    if(a.bull&&a.z1&&a.stop&&s.price<=a.z1*1.02&&s.price>=a.stop&&c>=50){
      out.push({s,g:{type:'left',label:'◀ 左側·價值回檔',
        desc:`多頭架構回檔至均線帶(${a.z0}~${a.z1}),基本面 ${f} 分——左側分批佈局思路;跌破 ${a.stop} 守停損`}});
    }
    // ▶ 右側·動能突破:站上或逼近 20 日高 + 技術面強
    else if(a.h20&&t>=65&&s.price>=a.h20*0.99){
      const over=s.price>=a.h20;
      out.push({s,g:{type:'right',label:'▶ 右側·動能突破',
        desc:`${over?'已站上':'逼近'} 20 日高 ${a.h20},技術 ${t} 分/基本面 ${f} 分——右側動能確認${over?'':'(突破帶量再追)'};失守 ${a.h20} 宜減碼`}});
    }
  });
  return out;
}
function radarItems(){
  const items=[];
  const push=(s,g)=>{if(s&&s.market===(window.GMKT||'TW'))items.push({s,g});};
  const byId={};(DATA.stocks||[]).forEach(s=>byId[s.id]=s);
  if(DATA.source==='live'){
    DATA.stocks.forEach(s=>(s.sig||[]).forEach(g=>push(s,g)));
  }else{
    DATA.stocks.forEach(s=>signals(s).forEach(g=>push(s,g)));
  }
  // 三率三升(後端 s.t3;無則用瀏覽器備援算好的清單)
  const arrow=(a,b)=>`${(+a).toFixed(1)}→${(+b).toFixed(1)}%`;
  const t3src=(DATA.stocks||[]).some(s=>s.t3)
    ?(DATA.stocks||[]).filter(s=>s.t3).map(s=>({id:s.id,t3:s.t3}))
    :(window.__T3||[]);
  t3src.forEach(x=>{
    const s=byId[x.id];const t=x.t3;
    if(!s||!t)return;
    push(s,{type:'t3',label:'三率三升 '+t.q,
      desc:`毛 ${arrow(t.gm[0],t.gm[1])} · 營益 ${arrow(t.om[0],t.om[1])} · 淨利 ${arrow(t.nm[0],t.nm[1])}${t.ry!=null?` · 月營收 ${t.ry>0?'+':''}${t.ry}%`:''}`});
  });
  // 🌊 外資連買·成長股(三關:外資連買 + 財報成長 + 未來性)
  (window.__FGO||[]).forEach(x=>{
    const s=byId[x.id];
    if(!s)return;
    push(s,{type:'fgo',label:`🌊 外資連買 ${x.run} 日`,
      desc:`外資連 ${x.run} 日買超(累計 ${x.sumRun.toLocaleString()} 張、近5日 ${x.sum5>0?'+':''}${x.sum5.toLocaleString()} 張)`
        +`${x.posM>=3?` · 月營收 YoY 連 ${x.posM} 月正成長`:''}${x.latestY!=null?`(最新 ${x.latestY>0?'+':''}${x.latestY}%)`:''}`
        +`${x.tags.length?` · ${x.tags.join('/')}`:''}——籌碼+成長+未來性三關通過`});
  });
  // 🐢 海龜突破(瀏覽器背景掃描 K 線分片計算,結果陸續進場)
  (window.__TURTLE||[]).forEach(x=>{
    const s=byId[x.id];
    if(s)push(s,x.g);
  });
  // ⚡ 漲停8招(股·價·大·漲·發·財·成·群 檢核 ≥6 項)
  (window.__ZT8||[]).forEach(x=>{
    const s=byId[x.id];
    if(s)push(s,x.g);
  });
  // 💎 蓄勢好股(基本面強但價格未發動)
  (window.__GEM||[]).forEach(x=>{
    const s=byId[x.id];
    if(s)push(s,x.g);
  });
  // 左側/右側交易分類(未來性濾網把關)
  sideItems().forEach(x=>{if(x&&x.s&&x.s.market===(window.GMKT||'TW'))items.push(x);});   // r543:左右側清單同樣鎖定當前市場分頁
  // 研究觀點:潛在漲價/缺料
  PRICE_WATCH.forEach(([id,why])=>{
    const s=byId[id];
    if(s)push(s,{type:'theme',label:'潛在漲價',desc:why});
  });
  return items;
}
function renderRadar(){
  const box=document.getElementById('radar');
  if(!box)return;
  const items=radarItems();
  const cnt={};items.forEach(({g})=>cnt[g.type]=(cnt[g.type]||0)+1);
  // 策略選單
  const seg=document.getElementById('stratSeg');
  const __gmU=(window.GMKT||'TW')==='US';
  if(__gmU&&curStrat!=='all'&&!(cnt[curStrat]||0))curStrat='all';   // r555:美股模式下當前策略沒有標的→退回全部
  if(seg)seg.innerHTML=STRATS.map(([k,n])=>{
    const c=k==='all'?items.length:(cnt[k]||0);
    if(__gmU&&!c&&k!=='all')return '';                              // r555:美股不渲染 0 檔策略鈕(多為台股專屬,佔位又誤導)
    return `<button data-st="${k}" class="${k===curStrat?'on':''}" ${!c&&k!=='all'?'style="opacity:.45"':''}>${n}${c?` <span style="font-size:11px;opacity:.75">${c}</span>`:''}</button>`;
  }).join('');
  if(seg&&!seg.dataset.b){seg.dataset.b='1';
    seg.addEventListener('click',e=>{
      const b=e.target.closest('button[data-st]');
      if(!b)return;
      curStrat=b.dataset.st;
      renderRadar();
    });
  }
  const order={whale:0,dip:1,break:2,turtle:2.5,zt8:2.6,gem:2.8,left:3,right:4,t3:5,price:6,strong:7,theme:8};
  let show=items.filter(({g})=>curStrat==='all'||g.type===curStrat);
  show.sort((a,b)=>(order[a.g.type]??9)-(order[b.g.type]??9)||total(b.s)-total(a.s));
  if(curStrat==='all'){
    const c2={};
    show=show.filter(({g})=>{c2[g.type]=(c2[g.type]||0)+1;return c2[g.type]<=6;});
  }else show=show.slice(0,36);
  box.innerHTML=show.length?show.map(({s,g})=>
    `<div class="r-card" data-id="${s.id}" tabindex="0" role="button">
       <span class="r-tag tg-${g.type}">${g.label}</span>
       <span class="r-name">${s.name} <span class="c-code">${s.id}</span> <b class="rpx">${s.price??'—'}</b> <span style="font-family:var(--mono);font-size:13px">${chgHtml(s.chg)}</span><span class="mini-candle" data-candle="${s.id}"></span></span>
       <span class="r-desc">${g.desc}</span></div>`).join('')
    +(curStrat==='all'&&items.length>show.length?`<div class="r-empty">「全部」模式每策略顯示前 6 檔;點上方策略看完整清單(共 ${items.length} 個訊號)。</div>`:'')
    :'<div class="r-empty">此策略今日沒有符合的個股 —— 沒有訊號也是一種訊號。</div>';
  box.querySelectorAll('.r-card').forEach(c=>{
    c.onclick=()=>{location.hash='#stock/'+c.dataset.id;};
    c.onkeydown=e=>{if(e.key==='Enter'){location.hash='#stock/'+c.dataset.id;}};
  });
}

