/* ══ 🌏 r542 市場總分頁:台股/美股 兩大分頁,全站狀態記憶 ══ */
window.GMKT=(function(){try{return localStorage.getItem('gmkt')||'TW';}catch(e){return 'TW';}})();
function setGMKT(m,skipRender){
  window.GMKT=m;try{localStorage.setItem('gmkt',m);}catch(e){}
  document.querySelectorAll('#gmktBar button').forEach(b=>b.classList.toggle('on',b.dataset.gm===m));
  try{
    mkt='ALL';sector='全部';page=1;q='';const qi=document.getElementById('q');if(qi)qi.value='';
    document.querySelectorAll('#mktSeg button').forEach(x=>{
      if(x.dataset.m==='TW'||x.dataset.m==='US')x.classList.add('gm-hide');   // 市場改由總分頁主導,清單內只留「全部/最愛」
      x.classList.toggle('on',x.dataset.m==='ALL');
    });
  }catch(e){}
  const twOnly=['mk_temp','mk_fut','mk_head','mk_conf','mk_pick','glb','aipick'];   // r702:AI Pick 為台股週選   // r557:mk_rot(資金輪動熱力圖)台美通用   // r544:大盤走勢區(mk_idx)不再整區隱藏——美股共用即時走勢引擎,細項分流
  twOnly.forEach(k=>{document.querySelectorAll(`.sec-title[data-sec="${k}"],#sb-${k}`).forEach(el=>el.classList.toggle('gm-hide',m==='US'));});
  document.documentElement.classList.toggle('gm-us',m==='US');            // r544:美股大盤細分流(CSS 隱藏台股卡/台指期/加權櫃買鈕)
  try{   // r547:股癌=台股專屬大分類——美股模式藏分頁鈕;若正停在股癌頁則跳回個股
    const gb=document.querySelector('#homeTabs [data-tab="gooaye"]');
    if(gb)gb.classList.toggle('gm-hide',m==='US');
    if(m==='US'&&gb&&gb.classList.contains('on'))setHomeTab('stocks');
  }catch(e){}
  try{   // r547:ETF 子分頁跟隨市場——美股模式鎖「美股精選」並藏台股子分頁;台股模式反向
    const sub=document.getElementById('etfSub');
    if(sub){
      sub.querySelectorAll('button').forEach(b=>{
        const isUS=b.dataset.s==='us';
        b.classList.toggle('gm-hide',m==='US'?!isUS:isUS);
      });
      const want=m==='US'?'us':(window.__etfSub==='us'?'tw':window.__etfSub);
      if(window.__etfSub!==want){window.__etfSub=want;
        sub.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x.dataset.s===want));
        try{renderEtf();}catch(e2){}}
    }
  }catch(e){}
  try{   // r555:區塊標題/副標依市場換裝(總經、清單、搜尋提示)
    const swap=(sel,usHtml)=>{const el=document.querySelector(sel);if(!el)return;
      if(!el.dataset.twHtml)el.dataset.twHtml=el.innerHTML;
      el.innerHTML=m==='US'?usHtml:el.dataset.twHtml;};
    swap('.sec-title[data-sec="macro"]','美股總經環境 <span style="font-weight:400;font-size:13px;letter-spacing:0">指數走勢・財報雷達・風險指標即時更新</span>');
    swap('.sec-title[data-sec="list"]','美股清單 <span style="font-weight:400;font-size:13px;letter-spacing:0">S&P 500+台積電等 ADR 共 538 檔・SEC 官方基本面,可搜尋/排序/依產業篩選</span>');
    const qi2=document.getElementById('q');
    if(qi2)qi2.placeholder=m==='US'?'搜尋名稱或代號,例如 NVDA、輝達':'搜尋名稱或代號,例如 3665、貿聯';
  }catch(e){}
  try{
    const tt=document.querySelector('.sec-title[data-sec="mk_idx"]');
    if(tt){
      if(!tt.dataset.twHtml)tt.dataset.twHtml=tt.innerHTML;
      tt.innerHTML=m==='US'
        ?'📈 美股大盤走勢與近期大事 <span style="font-weight:400;font-size:13px;letter-spacing:0">標普/那指即時走勢・道瓊費半・行事曆</span>'
        :tt.dataset.twHtml;
    }
    const fr=document.getElementById('futRow');
    if(fr&&fr.previousElementSibling&&fr.previousElementSibling.classList.contains('mini-cap'))
      fr.previousElementSibling.classList.toggle('gm-hide',m==='US');     // 「期貨籌碼(台指)」小標一併收
    const seg=document.getElementById('idxSeg');
    if(seg){
      const cur=seg.querySelector('button.on');
      if(m==='US'&&cur&&(cur.dataset.x==='tw'||cur.dataset.x==='otc')){const b=seg.querySelector('[data-x="sp"]');if(b)b.click();}
      if(m==='TW'&&cur&&(cur.dataset.x==='sp'||cur.dataset.x==='nq')&&!skipRender){const b=seg.querySelector('[data-x="tw"]');if(b)b.click();}
    }
  }catch(e){}
  if(!skipRender){try{renderChips();}catch(e){}try{renderAll();}catch(e){}}
  try{renderMacroAlerts();}catch(e){}                                      // r548:警示條依新市場立即重建(原本只在載入/資料到貨時建,切換後殘留舊市場過濾結果)
  try{applyGmUsFineTune();setTimeout(applyGmUsFineTune,600);}catch(e){}   // r546:切換立即清場+非同步渲染後補刀
}
/* ══ 🗺️ r556 每日資金流向熱力圖:Finviz 式 treemap(產業分群);台股面積=近20日均成交值、美股面積=市值(SEC股數×價);顏色=今日漲跌(紅漲綠跌) ══ */
function heatColor(c){   // -3%~+3% 漸層,台灣慣例紅漲綠跌
  if(c==null||!isFinite(c))return '#4A4A52';
  const t=Math.max(-1,Math.min(1,c/3));
  if(t>=0){const k=t;return `rgb(${Math.round(90+120*k)},${Math.round(62-20*k)},${Math.round(58-18*k)})`;}
  const k=-t;return `rgb(${Math.round(52-14*k)},${Math.round(96+50*k)},${Math.round(70+12*k)})`;
}
async function renderFundMap(){
  try{
    if(!DATA||!DATA.stocks)return;
    const el=document.getElementById('fundMap');                             // r557:畫進「類股資金輪動」區(rotBoard 準備容器)
    if(!el)return;
    const _sb=el.closest('.sec-body');
    if(_sb&&_sb.classList.contains('closed'))return;
    if(!el.clientWidth){window.__fmRetry=(window.__fmRetry||0)+1;            // r561:行動版常見 0 寬初始化——等版面就緒再畫(最多重試 10 次)
      if(window.__fmRetry<=10)setTimeout(renderFundMap,700);return;}
    window.__fmRetry=0;
    const GM=window.GMKT||'TW';
    let shMap={};
    if(GM==='US'){try{const u=await usfData();if(u&&u.s)Object.keys(u.s).forEach(k=>{if(u.s[k].sh)shMap[k]=u.s[k].sh;});}catch(e1){}}
    const rt=id=>{try{const r=RTC[id];return(r&&r.c>0&&r.y>0)?{chg:(r.c/r.y-1)*100,px:r.c}:null;}catch(e){return null;}};   // r559:即時價優先(MIS/富果輪掃快取)
    const pool=DATA.stocks.filter(s=>!s.etf&&s.market===GM&&s.price>0&&typeof s.chg==='number')
      .map(s=>{const q=rt(s.id);return q?Object.assign({},s,{chg:+q.chg.toFixed(2),price:q.px}):s;});
    const wOf=s=>{
      if(GM==='US'){const sh=shMap[String(s.id).toUpperCase()];return sh?sh*s.price:s.price*8;}   // 市值(百萬美元);無股數者給小面積保底
      const v=(s.al&&s.al.v20)||0;return v*s.price/100;                                            // 近20日均成交值(約=張×價,相對面積)
    };
    const bySec={};
    pool.forEach(s=>{const k=(s.sector||'其他').replace(/^美股·/,'');(bySec[k]=bySec[k]||[]).push(s);});
    const __mob=innerWidth<640;
    // r560:總權重與微型產業合併——占全圖 <1.5% 的產業併入「其他產業」,右下角不再是馬賽克
    const secList=Object.entries(bySec).map(([sec,arr])=>({sec,arr,w:arr.reduce((a,s)=>a+wOf(s),0)}));
    const totalW=secList.reduce((a,x)=>a+x.w,0)||1;
    const main=secList.filter(x=>x.w/totalW>=0.015);
    const tail=secList.filter(x=>x.w/totalW<0.015);
    if(tail.length>=2){
      const merged=[].concat(...tail.map(x=>x.arr));
      main.push({sec:'其他產業('+tail.length+'類)',arr:merged,w:tail.reduce((a,x)=>a+x.w,0)});
    }else if(tail.length===1)main.push(tail[0]);
    const children=main.map(({sec,arr})=>{
      arr.sort((a,b)=>wOf(b)-wOf(a));
      const top=arr.slice(0,GM==='US'?28:26);                                   // r559:多收幾檔主角
      const rest=arr.slice(top.length);
      const secW=arr.reduce((a,s)=>a+wOf(s),0)||1;
      const kids=top.map(s=>{
        const w=Math.max(wOf(s),0.01), sh=w/secW, gh=w/totalW;
        const big=gh>=(__mob?0.010:0.0055)||sh>=0.12;                            // r560:門檻改全圖占比——夠大的格子一律有名+%,小產業裡的老大也保底
        const mid=gh>=(__mob?0.0035:0.0016)||sh>=0.045;
        return {name:s.id,value:w,_nm:s.name,_chg:s.chg,_px:s.price,
          label:big?{show:true,fontSize:13,fontWeight:800,lineHeight:16,formatter:()=>`${s.name}\n${s.chg>0?'+':''}${(+s.chg).toFixed(2)}%`}
               :mid?{show:true,fontSize:11,formatter:()=>s.name}
               :{show:false},
          itemStyle:{color:heatColor(s.chg),borderColor:'rgba(0,0,0,.25)',borderWidth:1}};
      });
      if(rest.length){
        const rv=rest.reduce((a,s)=>a+wOf(s),0)*0.3, rc=rest.reduce((a,s)=>a+s.chg,0)/rest.length;   // r559:「其餘」面積壓縮 0.3 倍,不再吃掉主角版面
        kids.push({name:'…',value:Math.max(rv,0.01),_nm:`其餘 ${rest.length} 檔(面積已壓縮)`,_chg:+rc.toFixed(2),
          label:{show:true,fontSize:10.5,color:CT.legend,formatter:()=>`其餘${rest.length}檔`},
          itemStyle:{color:heatColor(rc),borderColor:'rgba(0,0,0,.2)',borderWidth:1,opacity:.85}});
      }
      const secChg=arr.reduce((a,s)=>a+wOf(s)*s.chg,0)/Math.max(1,arr.reduce((a,s)=>a+wOf(s),0));
      return {name:`${sec}  ${secChg>0?'+':''}${secChg.toFixed(2)}%`,children:kids,
        upperLabel:{show:true,height:22,color:'#EFE8DA',fontSize:11.5,fontWeight:800,backgroundColor:'rgba(30,30,36,.92)'}};
    }).sort((a,b)=>b.children.reduce((x,c)=>x+c.value,0)-a.children.reduce((x,c)=>x+c.value,0));
    const nt=document.getElementById('fundMapNote');
    if(nt)nt.innerHTML=(window.__rotJudge||'')+(window.__rotJudge?'<br>':'')
      +(GM==='US'?'面積=市值(SEC 股數×價)':'面積=近20日日均成交值(資金聚集度)')
      +'・顏色=今日漲跌(紅漲綠跌,±3% 飽和)・產業標題列=產業加權漲跌・點格子進個股・<b>盤中每 30 秒隨全市場輪掃報價跳動</b>。'
      +(GM==='US'&&!Object.keys(shMap).length?'<b>美股股數資料尚未到貨(usf 工作流跑過後自動補上),暫以等面積顯示。</b>':'');
    try{await ensureECharts();}catch(e2){}
    if(!window.echarts)return;
    try{echarts.dispose(el);}catch(e3){}
    el.style.height=(innerWidth<640?480:640)+'px';                              // r560:加高
    const ch=echarts.init(el,null,{renderer:'svg'});                            // r560:SVG 渲染——高解析螢幕文字銳利(canvas 縮放是模糊主因)
    setTimeout(()=>{try{ch.resize();}catch(e4){}},350);
    try{if(window.__fmChart&&window.__fmChart!==ch)window.__fmChart.dispose();}catch(e5){}
    window.__fmChart=ch;
    ch.setOption({backgroundColor:'#1E1E24',
      tooltip:{confine:true,formatter:p=>{const d=p.data||{};
        return d._nm?`<b>${d._nm}</b> ${p.name!=='…'?p.name:''}<br>漲跌:${d._chg>0?'+':''}${d._chg}%${d._px?`<br>價:${(+d._px).toLocaleString()}`:''}`:p.name;}},
      series:[{type:'treemap',roam:false,nodeClick:false,breadcrumb:{show:false},
        width:'100%',height:'100%',top:0,left:0,
        label:{show:true,color:'#F3EDE0',fontSize:11,fontWeight:700,overflow:'truncate'},
        levels:[{itemStyle:{gapWidth:3,borderColor:'#1E1E24'}},{itemStyle:{gapWidth:1}}],
        data:children}]});
    ch.off('click');
    ch.on('click',p=>{const d=p.data||{};if(d._nm&&p.name&&p.name!=='…')location.hash='#stock/'+p.name;});
  }catch(err){
    try{   // r561:繪圖失敗→錯誤浮出+簡易產業色條保底,不留白箱
      const el2=document.getElementById('fundMap'),nt2=document.getElementById('fundMapNote');
      if(nt2)nt2.innerHTML='⚠ 熱力圖繪製失敗('+String(err&&err.message||err).slice(0,120)+'),已切換簡易檢視;請把此訊息截圖回報。';
      if(el2&&DATA&&DATA.stocks){
        const GM2=window.GMKT||'TW',g2={};
        DATA.stocks.forEach(x=>{if(x.market!==GM2||x.etf||x.chg==null||!x.sector)return;(g2[x.sector]=g2[x.sector]||[]).push(+x.chg);});
        const rows2=Object.entries(g2).filter(([k,v])=>v.length>=3)
          .map(([k,v])=>({k,avg:v.reduce((a,b)=>a+b,0)/v.length,n:v.length})).sort((a,b)=>b.avg-a.avg);
        el2.style.height='auto';
        el2.innerHTML=rows2.map(r2=>`<div style="display:flex;align-items:center;gap:8px;padding:3px 0;font-size:13px">
          <span style="width:9em">${r2.k.replace(/^美股·/,'')}<span style="color:var(--dim);font-size:11px">(${r2.n})</span></span>
          <span style="flex:1;height:12px;border-radius:6px;background:${heatColor(r2.avg)}"></span>
          <b class="${r2.avg>=0?'pos':'neg'}" style="font-family:var(--mono);width:64px;text-align:right">${r2.avg>0?'+':''}${r2.avg.toFixed(2)}%</b></div>`).join('');
      }
    }catch(e9){}
  }
}
