/* ── 手機版分區摺疊(≤640px):點標題展開/收合 ── */
/* 區塊收合:電腦與手機皆可點標題展開/收合,偏好記在本機 */
function setupSections(){
  const mob=window.matchMedia&&window.matchMedia('(max-width:640px)').matches;
  let saved={};try{saved=JSON.parse(localStorage.getItem('secState')||'{}');}catch(e){}
  document.querySelectorAll('.sec-title[data-sec]').forEach(t=>{
    const key=t.dataset.sec,body=document.getElementById('sb-'+key);
    if(!body)return;
    t.classList.add('tap');
    if(!t.querySelector('.sec-hint')){
      const h=document.createElement('span');h.className='sec-hint';h.textContent='點標題收合';t.appendChild(h);
    }
    // 全站預設收合(2026-07-19 定案):除「總經環境」外一律先收合成乾淨目錄;點開看細項且偏好會記住
    const OPEN0=['macro','mk_idx'];   // r727:桌機預設只展開「總經環境 + 即時走勢」(法說會改預設收合),版面回到乾淨目錄
    const closed=(key in saved)?!!saved[key]:((key==='aipick'||key==='aipstat'||key==='aiptoday')?false:(mob||OPEN0.indexOf(key)<0));   // r744:本週精選/實戰戰績預設展開,歷史紀錄預設收合
    body.classList.toggle('closed',closed);
    t.classList.toggle('closed',closed);
    t.onclick=()=>{
      const c=body.classList.toggle('closed');
      t.classList.toggle('closed',c);
      saved[key]=c;
      try{localStorage.setItem('secState',JSON.stringify(saved));}catch(e){}
      if(!c)setTimeout(()=>{ // 重新展開後圖表重算尺寸
        try{if(RT.idx&&RT.idx.ch&&!RT.idx.lwc)RT.idx.ch.resize();}catch(e){}
        try{if(RT.intra&&RT.intra.ch)RT.intra.ch.resize();}catch(e){}
        try{if(chartInst)chartInst.resize();}catch(e){}
        try{body.querySelectorAll('div').forEach(el=>{      // r502:泛用復活——收合期間 init 的寬0圖展開即重算(修籌碼圖永遠空白;大盤頁同款早已存在)
          const inst=window.echarts&&echarts.getInstanceByDom&&echarts.getInstanceByDom(el);
          if(inst)inst.resize();});}catch(e){}
      },80);
    };
  });
}
function buildJumpBar(root){
  if(!root)return;
  [...root.children].filter(c=>c.classList&&c.classList.contains('mob-jump')).forEach(c=>c.remove());
  const walk=[...root.querySelectorAll('.grp-band,.sec-title[data-sec],[data-jumpname]')];   // r701:依 DOM 順序走訪——章節帶變成分組標籤,分類更細更好找
  const secs=walk.filter(x=>x.classList.contains('sec-title'));
  const named=walk.filter(x=>x.dataset&&x.dataset.jumpname);
  if(secs.length+named.length<2)return;
  const bar=document.createElement('div');
  bar.className='mob-jump';
  bar.innerHTML=walk.map(el=>{
    if(el.classList.contains('grp-band'))
      return `<span class="jm-lab">${el.dataset.jlabel||''}</span>`;
    if(el.dataset&&el.dataset.jumpname)
      return `<button data-jmn="${el.id}">${el.dataset.jumpname}</button>`;
    const nm=(el.childNodes[0]?.textContent||'').trim();
    return `<button data-jm="${el.dataset.sec}">${nm}</button>`;
  }).join('');
  root.prepend(bar);
  bar.querySelectorAll('[data-jm]').forEach(b=>b.onclick=()=>{
    const t=root.querySelector(`.sec-title[data-sec="${b.dataset.jm}"]`);
    if(!t)return;
    if(t.offsetParent===null||getComputedStyle(t).display==='none'){  // 區段隱藏(尚無資料)→ 明確回饋,不靜默捲空
      const nm=(t.childNodes[0]?.textContent||'此區塊').trim();
      toastLite(nm+' 尚無資料,到位後會自動出現');
      return;
    }
    const body=document.getElementById('sb-'+b.dataset.jm);
    if(body&&body.classList.contains('closed'))t.click();     // 收合中→展開(沿用原機制含記憶與圖表重算)
    setTimeout(()=>t.scrollIntoView({behavior:'smooth',block:'start'}),60);
  });
  bar.querySelectorAll('[data-jmn]').forEach(b=>b.onclick=()=>{
    const el=document.getElementById(b.dataset.jmn);
    if(!el)return;
    const sec=el.closest('.sec-body');
    if(sec&&sec.classList.contains('closed')){                 // 目標在收合區內 → 先展開所屬區段
      const t=root.querySelector('.sec-title[data-sec="'+sec.id.replace('sb-','')+'"]');
      if(t)t.click();
    }
    if(el.hidden||(el.offsetParent===null&&!sec)){try{toastLite('這個區塊目前沒有內容,資料到位後會自動出現');}catch(e){}return;}
    el.classList.remove('closed');
    try{const fb=el.querySelector&&el.querySelector('.fold-body');
      if(fb&&fb.style.display==='none'){const h=el.querySelector('h3');if(h)h.click();}}catch(e){}
    setTimeout(()=>el.scrollIntoView({behavior:'smooth',block:'start'}),80);
  });
}
function buildHomeSide(){                                  // r701:首頁左欄(財報狗式)——當前分頁的所有區塊一覽,點了捲過去
  try{
    const old=document.getElementById('homeSide');
    if(old)old.remove();
    if(location.hash)return;                               // 個股/內頁不掛(個股有自己的 stkSide)
    if(window.innerWidth<1024)return;
    const pane=[...document.querySelectorAll('.tabPane')].find(p=>p.style.display!=='none'&&p.offsetParent!==null);
    if(!pane)return;
    const items=[...pane.querySelectorAll('.sec-title[data-sec],[data-jumpname]')];
    if(items.length<3)return;
    const side=document.createElement('nav');
    side.id='homeSide';
    side.innerHTML='<div class="ss-in">'+items.map(el=>{
      if(el.dataset&&el.dataset.jumpname)
        return `<button class="ss-it" data-hsn="${el.id}">${el.dataset.jumpname}</button>`;
      const nm=(el.childNodes[0]?.textContent||'').trim();
      return `<button class="ss-it" data-hs="${el.dataset.sec}">${nm}</button>`;
    }).join('')+'</div>';
    pane.prepend(side);
    side.querySelectorAll('button').forEach(b=>b.onclick=()=>{
      side.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));
      const t=b.dataset.hs?pane.querySelector(`.sec-title[data-sec="${b.dataset.hs}"]`):document.getElementById(b.dataset.hsn);
      if(t){
        try{const fb=t.nextElementSibling;if(fb&&fb.classList.contains('sec-body')&&fb.style.display==='none')t.click();}catch(x){}
        setTimeout(()=>{try{t.scrollIntoView({behavior:'smooth',block:'start'});}catch(x){}},60);
      }
    });
  }catch(e){}
}
function setupMobileNav(){
  document.querySelectorAll('.tabPane').forEach(p=>buildJumpBar(p));
  /* 底部拇指導航 */
  if(!document.getElementById('mobNav')){
    const nav=document.createElement('div');
    nav.id='mobNav';
    const items=[['macro','📊','大盤'],['aipick','🤖','AI'],['stocks','📈','個股'],['etf','🧺','ETF'],['gooaye','🎙','股癌'],['port','💼','持股']];
    nav.innerHTML=items.map(([k,ic,lb])=>`<button data-mn="${k}"><span class="mi">${ic}</span>${lb}</button>`).join('')
      +`<button data-mn="__fav"><span class="mi">⭐</span>最愛</button>`;
    document.body.appendChild(nav);
    const sync=()=>{
      const onFav=location.hash==='#fav';
      const cur=document.querySelector('#homeTabs button.on');
      const k=onFav?'__fav':(cur?cur.dataset.tab:'macro');
      nav.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b.dataset.mn===k));
    };
    nav.querySelectorAll('[data-mn]').forEach(b=>b.onclick=()=>{
      if(b.dataset.mn==='__fav'){
        location.hash='#fav';
        setTimeout(sync,0);
        window.scrollTo({top:0,behavior:'smooth'});
        return;
      }
      if(location.hash)location.hash='';                       // 從個股/小學堂等內頁先回首頁
      const t=document.querySelector(`#homeTabs [data-tab="${b.dataset.mn}"]`);
      if(t)t.click();
      sync();
      window.scrollTo({top:0,behavior:'smooth'});
    });
    window.addEventListener('hashchange',()=>setTimeout(sync,0));
    document.getElementById('homeTabs')?.addEventListener('click',()=>setTimeout(sync,0));
    sync();
    document.getElementById('homeTabs')?.addEventListener('click',()=>setTimeout(buildHomeSide,80));   // r701:切分頁重建首頁左欄
    window.addEventListener('hashchange',()=>setTimeout(buildHomeSide,150));
    setTimeout(buildHomeSide,900);
  }
}
