/* ── 示意圖產生器:主題色自適應的四種版型 ── */
function figFlow(steps,loop){
  const n=steps.length,W=760,H=150,bw=Math.min(150,(W-40-(n-1)*34)/n),y=46,bh=58;
  let x=(W-(bw*n+34*(n-1)))/2,out='';
  const pos=[];
  steps.forEach((st,i)=>{
    const[h,sub]=Array.isArray(st)?st:[st,''];
    pos.push(x);
    out+=`<rect x="${x}" y="${y}" width="${bw}" height="${bh}" rx="10" fill="var(--panel2)" stroke="var(--amber)" stroke-width="1.6"/>
      <text x="${x+bw/2}" y="${y+(sub?24:34)}" text-anchor="middle" fill="var(--txt)" font-size="13" font-weight="800">${h}</text>
      ${sub?`<text x="${x+bw/2}" y="${y+43}" text-anchor="middle" fill="var(--mut)" font-size="10.5">${sub}</text>`:''}`;
    if(i<n-1)out+=`<text x="${x+bw+17}" y="${y+bh/2+5}" text-anchor="middle" fill="var(--amber)" font-size="17" font-weight="900">→</text>`;
    x+=bw+34;
  });
  if(loop){
    const x0=pos[0]+bw/2,x1=pos[n-1]+bw/2;
    out+=`<path d="M ${x1} ${y+bh+8} L ${x1} ${y+bh+26} L ${x0} ${y+bh+26} L ${x0} ${y+bh+8}" fill="none" stroke="var(--amber)" stroke-width="1.6" stroke-dasharray="5 4" marker-end="url(#lfArr)"/>
    <defs><marker id="lfArr" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="var(--amber)"/></marker></defs>
    <text x="${(x0+x1)/2}" y="${y+bh+41}" text-anchor="middle" fill="var(--mut)" font-size="11.5">循環往復</text>`;
  }
  return `<svg viewBox="0 0 ${W} ${loop?H+42:H}" xmlns="http://www.w3.org/2000/svg">${out}</svg>`;
}
function figBars(items,unit){
  const W=760,H=64+items.length*44,mx=Math.max(...items.map(x=>Math.abs(x[1])));
  let out='';
  items.forEach(([lb,v,col],i)=>{
    const y=44+i*44,w=Math.max(8,Math.abs(v)/mx*380);
    out+=`<text x="200" y="${y+18}" text-anchor="end" fill="var(--txt2)" font-size="13" font-weight="700">${lb}</text>
      <rect x="214" y="${y}" width="${w}" height="26" rx="6" fill="${col||'var(--amber)'}" opacity=".82"/>
      <text x="${214+w+10}" y="${y+18}" fill="var(--txt)" font-size="13.5" font-weight="900" font-family="monospace">${v}${unit||''}</text>`;
  });
  return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg">${out}</svg>`;
}
function figSplit(L,R){
  const W=760,H=176,bw=340;
  const panel=(o,x,col)=>`<rect x="${x}" y="34" width="${bw}" height="126" rx="12" fill="var(--panel2)" stroke="${col}" stroke-width="1.8"/>
    <text x="${x+bw/2}" y="60" text-anchor="middle" fill="${col}" font-size="14.5" font-weight="900">${o.h}</text>
    ${o.lines.map((l,i)=>`<text x="${x+18}" y="${86+i*23}" fill="var(--txt2)" font-size="12.5">• ${l}</text>`).join('')}`;
  return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg">${panel(L,26,TONE.red)}${panel(R,W-26-bw,TONE.green)}<text x="${W/2}" y="102" text-anchor="middle" fill="var(--mut)" font-size="15" font-weight="900">vs</text></svg>`;
}
function figTrend(a,b,note){
  const W=760,H=190,x0=60,x1=720,y0=150,y1=40;
  const all=[...a.pts,...b.pts],mn=Math.min(...all),mxv=Math.max(...all);
  const line=(s,col)=>{
    const pts=s.pts.map((v,i)=>`${x0+(x1-x0)*i/(s.pts.length-1)},${y0-(v-mn)/(mxv-mn||1)*(y0-y1)}`).join(' ');
    const lx=x1-4,ly=y0-(s.pts[s.pts.length-1]-mn)/(mxv-mn||1)*(y0-y1);
    return `<polyline points="${pts}" fill="none" stroke="${col}" stroke-width="2.6" stroke-linejoin="round"/>
      <text x="${lx}" y="${ly-8}" text-anchor="end" fill="${col}" font-size="12.5" font-weight="800">${s.label}</text>`;
  };
  return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg">
    <line x1="${x0}" y1="${y0}" x2="${x1}" y2="${y0}" stroke="var(--line)"/>
    ${line(a,'var(--up)')}${line(b,'var(--amber)')}
    ${note?`<text x="${(x0+x1)/2}" y="${H-8}" text-anchor="middle" fill="var(--mut)" font-size="12">${note}</text>`:''}</svg>`;
}
