/* ══════════════ 公司簡介(Yahoo 公司資料 + AI 白話解讀)══════════════ */
let __cdCache=null;
async function coDescData(){                 // r535:站內公司簡介檔(繁中,全數 538 檔美股+可擴充台股)
  if(__cdCache)return __cdCache;
  try{
    const r=await fT('codesc.json?_='+Math.floor(Date.now()/864e5),8000);
    if(r.ok)__cdCache=await r.json();
  }catch(e){}
  return __cdCache;
}
const YSUM={};
function ySym(s){return s.market==='TW'?`${s.id}.${s.ex==='tse'?'TW':'TWO'}`:s.id;}
async function jinaRead(url,ms){
  try{
    const r=await fT('https://r.jina.ai/'+url,ms||16000);
    if(r.ok){const t=await r.text();if(t&&t.length>400&&!/rate ?limit/i.test(t.slice(0,200)))return t;}
  }catch(e){}
  return null;
}
function saNum(t,res){
  for(const re of res){const m=t.match(re);if(m)return parseFloat(m[1].replace(/,/g,''));}
  return null;
}
async function ySummary(s){
  const sym=ySym(s);
  if(YSUM[sym])return YSUM[sym];
  YSUM[sym]=(async()=>{
    const isTW=s.market==='TW';
    const base=isTW?`https://stockanalysis.com/quote/tpe/${s.id}/`:`https://stockanalysis.com/stocks/${s.id}/`;
    let fd=null,ap=null;
    // ── 主力來源:jina 閱讀器讀 stockanalysis(繞過機器人封鎖、支援 CORS 直連) ──
    const ft=await jinaRead(base+'forecast/');
    if(ft){
      const mean=saNum(ft,[/average (?:12-month )?(?:price )?target (?:of |is |at )?(?:NT\$|\$|TWD ?)?([\d,]+\.?\d*)/i,
                           /average target of (?:NT\$|\$)?([\d,]+\.?\d*)/i,
                           /price target[^\d]{0,30}?([\d,]+\.\d+)/i]);
      const hi=saNum(ft,[/high (?:estimate|target|forecast)? ?(?:of|is|at)? ?(?:NT\$|\$|TWD ?)?([\d,]+\.?\d*)/i]);
      const lo=saNum(ft,[/low (?:estimate|target|forecast)? ?(?:of|is|at)? ?(?:NT\$|\$|TWD ?)?([\d,]+\.?\d*)/i]);
      const n=saNum(ft,[/(\d+)\s+(?:Wall Street )?analysts?/i,/according to (\d+)/i]);
      const rk=(ft.match(/consensus (?:rating )?(?:of |is )?"?\*{0,2}(strong buy|buy|hold|underperform|sell)/i)||[])[1];
      if(mean)fd={targetMeanPrice:mean,targetHighPrice:hi,targetLowPrice:lo,
                  numberOfAnalystOpinions:n,recommendationKey:rk?rk.toLowerCase().replace(/\s+/,'_'):null};
    }
    const ct=await jinaRead(base+'company/');
    if(ct){
      let desc=null;
      const dm=ct.match(/#{1,3}\s*(?:About|Description|Company (?:Description|Profile))[^\n]*\n+([\s\S]{80,1500}?)\n\n/i);
      if(dm)desc=dm[1];
      if(!desc){
        const paras=ct.split(/\n{2,}/).filter(p=>p.length>160&&/[a-z]{4}/.test(p)&&!p.includes('|')&&!/^\[/.test(p.trim()));
        paras.sort((x,y)=>y.length-x.length);
        desc=paras[0]||null;
      }
      if(desc)desc=desc.replace(/\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/[*#_>]/g,'').trim();
      const emp=saNum(ct,[/Employees[^\d]{0,25}([\d,]{3,})/i]);
      const wm=ct.match(/\bWebsite\b[^\n]*?\]?\((https?:\/\/[^\s)]+)\)/i)||ct.match(/\bWebsite\b[^\n]*?(https?:\/\/[^\s|)\]]+)/i);
      let ind=(ct.match(/\bIndustry\b[^A-Za-z\u4e00-\u9fff]{0,10}([A-Za-z][A-Za-z &,\-\/]{1,40})/i)||[])[1];
      if(ind)ind=ind.replace(/x{4,}.*$/,'').trim();
      if(desc||emp)ap={longBusinessSummary:desc,industry:ind?ind.trim():null,
        website:wm?wm[1]:null,fullTimeEmployees:emp,city:null,country:null};
    }
    if(fd||(ap&&ap.longBusinessSummary))return {financialData:fd||{},assetProfile:ap||{}};
    // 零 Yahoo 鐵律:不再有 Yahoo 網頁萃取備援;stockanalysis 也拿不到就誠實回空
    return null;
  })();
  return YSUM[sym];
}

const RECO_ZH={strong_buy:'強力買進',buy:'買進',hold:'持有',underperform:'遜於大盤',sell:'賣出',none:'—'};
const ACT_ZH={up:['調升','up'],down:['調降','down'],init:['首次評等',''],main:['維持',''],reit:['重申','']};
function numRaw(x){return x==null?null:(typeof x==='object'?x.raw:x);}
async function loadAnalystDetail(s){
  const box=document.getElementById('anaBody');
  if(!box)return;
  let q=null;
  if(s.tp&&s.tp.m){  // 後端每日已抓好(yfinance):秒開
    q={financialData:{targetMeanPrice:s.tp.m,targetHighPrice:s.tp.h,targetLowPrice:s.tp.l,
       numberOfAnalystOpinions:null,recommendationKey:null},_daily:true};
  }else{
    q=await ySummary(s);
  }
  if(!document.getElementById('anaBody')||!location.hash.startsWith('#stock/'))return;
  const fd=q&&q.financialData;
  const tMean=numRaw(fd&&fd.targetMeanPrice),tHi=numRaw(fd&&fd.targetHighPrice),
        tLo=numRaw(fd&&fd.targetLowPrice),nA=numRaw(fd&&fd.numberOfAnalystOpinions);
  const reco=fd&&fd.recommendationKey;
  const price=s.price;
  let html='';
  if(tMean&&tHi&&tLo){
    const up=price?((tMean-price)/price*100):null;
    html+=`<div class="tp-grid">
      <div><dt>平均目標價</dt><dd style="color:var(--amber)">${tMean.toFixed(tMean>100?0:2)}</dd></div>
      <div><dt>最高 / 最低</dt><dd>${tHi.toFixed(tHi>100?0:2)} / ${tLo.toFixed(tLo>100?0:2)}</dd></div>
      ${up!=null?`<div><dt>隱含空間(vs 現價)</dt><dd class="${up>0?'pos':'neg'}">${up>0?'+':''}${up.toFixed(1)}%</dd></div>`:''}
      ${nA?`<div><dt>分析師家數</dt><dd>${nA} 家</dd></div>`:''}
      ${reco?`<div><dt>綜合評等</dt><dd>${RECO_ZH[reco]||reco}</dd></div>`:''}
    </div>`;
    // 目標價區間條:低─平均─高,直線為現價位置
    const lo=Math.min(tLo,price||tLo)*0.98, hi=Math.max(tHi,price||tHi)*1.02;
    const pos=v=>Math.max(1,Math.min(99,(v-lo)/(hi-lo)*100));
    html+=`<div class="tp-bar">
      <div class="tp-line"></div>
      <div class="tp-dot" style="left:${pos(tLo)}%"></div><span class="tp-lb" style="left:${pos(tLo)}%;top:34px">低 ${tLo.toFixed(tLo>100?0:1)}</span>
      <div class="tp-dot" style="left:${pos(tMean)}%"></div><span class="tp-lb" style="left:${pos(tMean)}%;top:0">平均 ${tMean.toFixed(tMean>100?0:1)}</span>
      <div class="tp-dot" style="left:${pos(tHi)}%"></div><span class="tp-lb" style="left:${pos(tHi)}%;top:34px">高 ${tHi.toFixed(tHi>100?0:1)}</span>
      ${price?`<div class="tp-now" style="left:${pos(price)}%"></div><span class="tp-lb" style="left:${pos(price)}%;top:0;color:var(--txt);font-weight:700">現價 ${price}</span>`:''}
    </div>
    <div class="dim-note" style="margin-top:8px">共識目標價${q._daily?'(每日自動更新)':''}:賣方分析師 12 個月預估彙整,並非保證;分歧度(高低差)越大代表市場看法越不一致。</div>`;
  }else{
    html+='<div class="dim-note">此檔暫無目標價資料:①每日更新(Actions)跑過後,綜合分前300名+精選股會自動有;②不在名單的小型股本來就少有分析師覆蓋——點下方 AI 按鈕上網彙整最準。</div>';
  }
  const hist=q&&q.upgradeDowngradeHistory&&q.upgradeDowngradeHistory.history;
  if(Array.isArray(hist)&&hist.length){
    const rows=hist.slice(0,6).map(h=>{
      const d=h.epochGradeDate?new Date(h.epochGradeDate*1000):null;
      const [az,ac]=ACT_ZH[h.action]||[h.action||'',''];
      return `<div><span class="ana-firm">${h.firm||''}</span>
        ${az?`<span class="ana-act ${ac}">${az}</span>`:''}
        <span style="color:var(--txt2)">${h.toGrade||''}${h.fromGrade&&h.fromGrade!==h.toGrade?`<span style="color:var(--dim)">(原 ${h.fromGrade})</span>`:''}</span>
        ${d?`<span class="ana-date">${d.getFullYear()}/${d.getMonth()+1}/${d.getDate()}</span>`:''}</div>`;
    }).join('');
    html+=`<h3 style="margin-top:16px;font-size:15px">外資/券商升降評紀錄(近幾筆)</h3><div class="ana-list">${rows}</div>`;
  }
  box.innerHTML=html;
  // 目標價相關新聞(即時)
  const nb=document.getElementById('anaNews');
  if(nb)(async()=>{
    // 券商研究報告動態:抓「目標價/評等/報告」相關報導,自動摘出券商與目標價
    const BROKERS=['摩根士丹利','大摩','高盛','摩根大通','小摩','花旗','美銀','美林','瑞銀','野村','麥格理','里昂','匯豐','巴克萊','德意志','凱基','元大','富邦','國泰','中信','統一','群益','永豐','台新','兆豐','第一金'];
    const its=await rssItems(`"${s.name}" (目標價 OR 評等 OR 研究報告)`,8,ySym(s));
    if(!nb.isConnected)return;
    if(!its.length){
      nb.innerHTML='<div class="dim-note">近期查無券商報告相關報導——點下方連結直接搜尋,或用 AI 彙整。</div>';
      return;
    }
    // 從標題摘取:券商名 + 目標價 X 元
    const picks=[];
    its.forEach(x=>{
      const b=BROKERS.find(k=>x.t.includes(k));
      const m=x.t.match(/目標價[至上調升降看]{0,3}\s*([0-9,]{2,7}(?:\.\d+)?)\s*元/);
      if(b&&m)picks.push({b,p:m[1],l:x.l});
    });
    const chips=picks.slice(0,4).map(p=>
      `<a class="btn-ghost" style="height:auto;padding:5px 12px;font-size:13.5px" href="${p.l}" target="_blank" rel="noopener">🎯 ${p.b} ${p.p} 元 ↗</a>`).join(' ');
    nb.innerHTML=(chips?`<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:9px">${chips}</div>`:'')+
      `<div class="news" style="border:none;padding:0">${its.map(x=>
      `<a href="${x.l}" target="_blank" rel="noopener"><span>${x.t}</span><span class="src">${x.s}${credBadge(x.s)}${x.d?' · '+x.d:''}</span></a>`).join('')}</div>
      <div class="dim-note" style="margin-top:6px">點標題可閱讀完整報導;🎯 為標題自動摘取之券商目標價,請以原文為準。</div>`;
  })();
}
const SEC2LEARN=[['半導體','semi'],['電子零組件','pcb'],['電腦及週邊','server'],['光電','cpo'],['其他電子','server'],['通信網路','cpo']];
/* 公司基本資料(全市場一次抓,快取一天;OpenAPI 支援瀏覽器直連) */
let CO_BASIC=null;
async function coBasic(){
  const good=d=>d&&Object.keys(d).length>300;   // 上市+上櫃應有 1700+ 檔;太少=抓失敗
  if(good(CO_BASIC))return CO_BASIC;
  try{
    const c=JSON.parse(localStorage.getItem('co_basic3')||'null');
    if(c&&c.exp>Date.now()&&good(c.d)){CO_BASIC=c.d;return CO_BASIC;}
  }catch(e){}
  const d={};
  for(const u of ['https://openapi.twse.com.tw/v1/opendata/t187ap03_L',
                  'https://www.tpex.org.tw/openapi/v1/mopsfin_t187ap03_O']){
    let arr=null;
    try{const r=await fT(u,20000);if(r.ok)arr=await r.json();}catch(e){}
    if(!arr){const t=await fetchTextProxy(u);try{arr=JSON.parse(t);}catch(e){}}
    if(!Array.isArray(arr)||!arr.length)continue;
    const keys=Object.keys(arr[0]);
    const k=(...ns)=>keys.find(x=>ns.some(n=>x.includes(n)));
    const kid=k('公司代號'),kch=k('董事長'),kest=k('成立日期'),kipo=k('上市日期','上櫃日期'),
          kcap=k('實收資本額'),kweb=k('網址'),kind=k('產業別'),kfull=k('公司名稱'),
          kbiz=k('主要經營業務','營業項目','所營事業');
    arr.forEach(r=>{
      const sid=String(r[kid]||'').trim();
      if(!sid)return;
      d[sid]={chair:r[kch]||'',est:r[kest]||'',ipo:r[kipo]||'',
              cap:r[kcap]||'',web:r[kweb]||'',ind:r[kind]||'',full:r[kfull]||'',
              biz:kbiz?String(r[kbiz]||'').trim().slice(0,600):''};
    });
  }
  CO_BASIC=d;
  if(good(d))try{localStorage.setItem('co_basic3',JSON.stringify({exp:Date.now()+864e5,d}));}catch(e){}
  return d;
}
/* 股本規模分類(台股慣例,與漲停8招 50 億門檻一致);v 可為「元字串」或「億數字」 */
function capSize(v){
  let n=parseFloat(String(v).replace(/,/g,''));
  if(!n||n<=0)return null;
  const e=n>1e6?n/1e8:n;                       // >百萬視為元,否則已是億
  return e<50?{t:'小型股',c:TONE.green,e}:e<100?{t:'中型股',c:'var(--amber)',e}:{t:'大型股',c:TONE.blue,e};
}
/* 股本快取:優先讀 repo 內的 cap.json(30KB,秒開);沒有才退回瀏覽器直抓證交所(慢) */
let CAPMAP=null;
async function capMap(){
  const good=d=>d&&Object.keys(d).length>300;
  if(good(CAPMAP))return CAPMAP;
  try{const c=JSON.parse(localStorage.getItem('capmap1')||'null');
    if(c&&c.exp>Date.now()&&good(c.d)){CAPMAP=c.d;return CAPMAP;}}catch(e){}
  try{
    const r=await fT('cap.json?'+Math.floor(Date.now()/864e5),10000);
    if(r.ok){const j=await r.json();const d=(j&&j.c)||{};
      if(good(d)){CAPMAP=d;
        try{localStorage.setItem('capmap1',JSON.stringify({exp:Date.now()+864e5,d}));}catch(e){}
        return d;}}
  }catch(e){}
  try{                                          // 深度備援:瀏覽器直抓(cap.json 尚未產生時)
    const cb=await coBasic();const d={};
    Object.keys(cb||{}).forEach(id=>{const z=capSize(cb[id]&&cb[id].cap);if(z)d[id]=z.e;});
    if(good(d))CAPMAP=d;
    return d;
  }catch(e){return {};}
}
function fmtCap(v){
  const n=parseFloat(String(v).replace(/,/g,''));
  if(!n)return null;
  return n>=1e8?(n/1e8).toFixed(1).replace(/\.0$/,'')+' 億':Math.round(n/1e4).toLocaleString()+' 萬';
}
function fmtRocDate(v){
  const s=String(v||'').replace(/[^\d]/g,'');
  if(s.length===7)return (+s.slice(0,3)+1911)+'/'+s.slice(3,5)+'/'+s.slice(5);
  if(s.length===8)return s.slice(0,4)+'/'+s.slice(4,6)+'/'+s.slice(6);
  return v||null;
}
/* 中文簡介:維基百科 REST API(官方開放 CORS,直連免代理) */
async function wikiSummary(cands,lang){
  const zh=(lang||'zh')==='zh';
  const looksCo=t=>zh?/(公司|企業|集團|股份|製造商|供應商|廠商|品牌)/.test(t)
                    :/(compan(y|ies)|corporation|manufacturer|holdings|conglomerate|firm)/i.test(t);
  for(const name of cands.filter(Boolean)){
    try{
      const r=await fT(`https://${zh?'zh':'en'}.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(name)}`,8000);
      if(!r.ok)continue;
      const j=await r.json();
      if(!j||!j.extract||j.type==='disambiguation'||j.extract.length<40)continue;
      if(!looksCo(j.extract+(j.description||'')))continue;   // 防同名錯配(如「中華」對到中國別稱)
      return {text:j.extract,url:(j.content_urls&&j.content_urls.desktop&&j.content_urls.desktop.page)||null};
    }catch(e){}
  }
  return null;
}
async function loadProfileDetail(s){
  const box=document.getElementById('profBody');
  if(!box)return;
  const isTW=s.market==='TW';
  const co=s.co||{};
  let facts='',desc='';
  const factRow=c=>`<div class="prof-kv">
      ${c.ind?`<span><b>產業別</b>${c.ind}</span>`:''}
      ${c.ch||c.chair?`<span><b>董事長</b>${c.ch||c.chair}</span>`:''}
      ${fmtRocDate(c.ipo)?`<span><b>掛牌</b>${fmtRocDate(c.ipo)}</span>`:''}
      ${fmtCap(c.cap)?`<span><b>實收資本額</b>${fmtCap(c.cap)}${(()=>{const z=capSize(c.cap);return z?` <span style="color:${z.c};font-weight:800">${z.t}</span>`:'';})()}</span>`:''}
      ${c.web?`<span><b>官網</b><a href="${/^http/.test(c.web)?c.web:'https://'+c.web}" target="_blank" rel="noopener">${String(c.web).replace(/^https?:\/\//,'')}</a></span>`:''}
    </div>`;
  if(co.ind||co.ch||co.web)facts=factRow(co);
  if(s.bz)desc=`<div class="prof-sum">${s.bz}</div>
    <div class="dim-note" style="margin-top:6px">來源:公司登記之主要經營業務(公開資訊觀測站,每日更新);想要「產品分類+白話版」點下方 AI 按鈕。</div>`;
  const paint=()=>{
    const el=document.getElementById('profBody');
    if(!el||!location.hash.startsWith('#stock/'))return;
    el.innerHTML=(facts+desc)||'<div class="dim-note">公司資料載入中…</div>';
  };
  paint();
  if(isTW&&!fmtCap(co.cap)){                   // 股本快速通道:cap.json 秒補
    try{
      const cm=await capMap();
      const e=cm&&cm[s.id];
      if(e){co={...co,cap:String(Math.round(e*1e8))};
        facts=factRow(co);paint();}
    }catch(e){}
  }
  if(facts&&desc&&fmtCap(co.cap))return;       // 後端資料齊全「且含股本」才秒開收工
  if(isTW){                                    // 備援:瀏覽器直連證交所補基本資料(含股本)
    try{
      const d=await coBasic();
      const c=d&&d[s.id];
      if(c){
        const m={...c,...co};                  // 後端欄位優先,股本等缺漏由證交所補
        if(!m.cap&&c.cap)m.cap=c.cap;
        if(m.ind||m.ch||m.chair||m.web||fmtCap(m.cap))facts=factRow(m);
        if(!desc&&c.biz&&c.biz.length>10)
          desc=`<div class="prof-sum">${c.biz}</div>
            <div class="dim-note" style="margin-top:6px">來源:公司登記之主要經營業務(證交所/櫃買)。</div>`;
      }
    }catch(e){}
  }
  if(!desc){try{                             // r535:站內簡介檔——美股 538 檔全覆蓋(繁中「做什麼・賣什麼」),台股缺官方簡介時也補位
    const cd=await coDescData();
    const t=cd&&cd[String(s.id).toUpperCase()];
    if(t)desc=`<div class="prof-sum">${t}</div>
      <div class="dim-note" style="margin-top:6px">站內簡介;想更深入商業模式與競爭格局,點下方「AI 白話解讀」。</div>`;
  }catch(e){}}
  if(!desc)desc=`<div class="dim-note">此檔尚未納入每日業務簡介掃描(僅涵蓋重點股)——點下方「AI 白話解讀」,AI 會直接為你介紹這家公司與產品分類,通常這個答案還更完整。</div>`;
  paint();
}
/* ══════════════ 建議進場點:左側 vs 右側交易者(規則化)══════════════ */
function entryPlan(lv,o,price){
  const vols=o.map(x=>x[4]);
  const volOk=avg(vols.slice(-5))>avg(vols.slice(-20));
  const brk=+(lv.h20*1.005).toFixed(2);
  const brkStop=+(lv.h20*0.965).toFixed(2);
  const target=+(lv.h60+(lv.h60-lv.l60)*0.618).toFixed(2);
  const aboveBrk=price>lv.h20*1.002;
  const right=aboveBrk?{title:'已在高檔 · 順勢不追高',rows:[
      ['進場方式','回測20日線 <b>'+lv.ma20.toFixed(1)+'</b> 不破且收紅,再進場/加碼'],
      ['停損',+(lv.ma20*0.96).toFixed(2)+'(跌破月線約4%)'],
      ['目標參考',target+'(平台高度投射)'],
      ['提醒','現價已過突破點,直接追價的風險報酬比不佳']]}
    :{title:'等待帶量突破再進場',rows:[
      ['進場價','<b>'+brk+'</b>(帶量站上近月高 '+lv.h20.toFixed(1)+')'],
      ['距現價',((brk-price)/price*100>=0?'+':'')+((brk-price)/price*100).toFixed(1)+'%'],
      ['停損',brkStop+'(跌回突破點之下即出場)'],
      ['目標參考',target+'(平台高度投射)'],
      ['量能條件','突破日成交量>20日均量 '+(volOk?'(近5日量能已放大 ✓)':'(目前量能不足,等放量)')]]};
  const left=lv.bull?{cls:'l',title:'多頭排列 · 拉回均線帶分批',rows:[
      ['第一批(1/3)','<b>'+lv.zone[1].toFixed(2)+'</b>(回測均線帶上緣)'],
      ['第二批(加碼)','<b>'+lv.zone[0].toFixed(2)+'</b>(均線帶下緣/季線)'],
      ['距現價',((lv.zone[1]-price)/price*100).toFixed(1)+'% ~ '+((lv.zone[0]-price)/price*100).toFixed(1)+'%'],
      ['停損(全部出場)',lv.stop+'(買進區下緣−3%)'],
      ['出場參考','跌破季線收盤兩日不收回,左側邏輯失效']]}
    :{cls:'l',title:'空頭排列 · 僅積極型小倉試單',rows:[
      ['觀察區',lv.l60.toFixed(2)+' ~ '+lv.l20.toFixed(2)+'(前波低支撐帶)'],
      ['進場條件','支撐帶出現止跌K棒(長下影/紅K吞噬)+量縮'],
      ['停損',+(lv.l60*0.97).toFixed(2)+'(跌破前波低)'],
      ['建議','趨勢未轉多,以觀望為主、倉位嚴控']]};
  return {right,left};
}
function entryHTML(lv,o,price){
  if(!lv||!o||o.length<60)return'';
  const ep=entryPlan(lv,o,price);
  const card=(cls,side,who,p)=>`<div class="entry-card ${cls}">
    <div class="entry-head"><span class="entry-side">${side}</span><b>${p.title}</b></div>
    <div class="entry-who">${who}</div>
    <div class="entry-rows">${p.rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</div></div>`;
  return `<div class="dim-block" style="border-left:4px solid var(--amber)">
    <h3>建議進場點|右側 vs 左側(規則化) <span class="ds">現價 ${price}</span></h3>
    <div class="entry-grid">
      ${card('r','右側交易者','適合:順勢操作、不猜底,用較高成本換「趨勢確認」的訊號,勝率優先。',ep.right)}
      ${card('l','左側交易者','適合:逢低分批佈局、能承受浮虧與等待,用時間換「成本優勢」。',ep.left)}
    </div>
    <div class="dim-note">右側=突破/趨勢確認後才進(買得貴、錯得少);左側=拉回支撐分批接(買得便宜、要忍浮虧)。兩者擇一貫徹即可,最忌右側的價進場、左側的心態凹單。以上為規則化推估、非投資建議——先想好停損,再想獲利。</div>
  </div>`;
}

/* ══════════════ 總經行事曆事件詳細頁(說明+即時相關新聞)══════════════ */
function fT(url,ms,opts){  // 帶逾時的 fetch:代理掛掉也不會讓畫面卡死
  const c=new AbortController();
  const t=setTimeout(()=>c.abort(),ms||9000);
  return fetch(url,Object.assign({cache:'no-store',signal:c.signal},opts||{})).finally(()=>clearTimeout(t));
}
const PROXY=[x=>x,
  x=>myWrap(x)||x,                                                       // 🏠 自家代理(於🔌診斷面板設定,最穩)
  x=>'https://corsproxy.io/?url='+encodeURIComponent(x),
  x=>'https://api.allorigins.win/raw?url='+encodeURIComponent(x),
  x=>'https://api.codetabs.com/v1/proxy?quest='+encodeURIComponent(x)];
async function fetchTextProxy(url){
  const routes=[
    x=>'https://api.allorigins.win/raw?url='+encodeURIComponent(x),
    x=>'https://corsproxy.io/?url='+encodeURIComponent(x),
    x=>'https://api.codetabs.com/v1/proxy?quest='+encodeURIComponent(x)];
  for(const r of routes){
    try{
      const res=await fT(r(url),9000);
      if(res.ok){const t=await res.text();if(t&&t.length>100)return t;}
    }catch(e){}
  }
  try{ // 最後備援:allorigins JSON 包裝版
    const res=await fT('https://api.allorigins.win/get?url='+encodeURIComponent(url),9000);
    if(res.ok){const j=await res.json();if(j&&j.contents&&j.contents.length>100)return j.contents;}
  }catch(e){}
  return null;
}
function pickNum(html,key){
  const m=html.match(new RegExp('"'+key+'":\\{"raw":(-?[\\d.]+)'))||html.match(new RegExp('"'+key+'":(-?[\\d.]+)'));
  return m?+m[1]:null;
}
function pickStr(html,key){
  const m=html.match(new RegExp('"'+key+'":"((?:[^"\\\\]|\\\\.)*)"'));
  try{return m?JSON.parse('"'+m[1]+'"'):null;}catch(e){return m?m[1]:null;}
}
