function evExplain(e){
  const hit=EV_KB.find(k=>{try{return k.m(e);}catch(x){return false;}});
  return hit||{q:e.name.replace(/\(.*?\)/g,'').trim(),rel:[],
    what:'重要總經/財經事件。',watch:'留意公布值與市場預估的落差——落差才是行情的來源。',
    tw:'透過市場情緒與資金面間接影響台股。'};
}
