function glbStocks(tagNames){
  const seen=new Set(),out=[];
  (tagNames||[]).forEach(tg=>(GLB_STOCKS[tg]||[]).forEach(([id,nm])=>{
    if(seen.has(id)||out.length>=6)return;seen.add(id);
    const inPool=!!(DATA&&DATA.stocks&&DATA.stocks.find(s=>s.id===id));
    out.push({id,nm,inPool});
  }));
  return out;
}
const GLB_HOT=/(shortage|price hike|price increase|price hikes|sold out|allocation|tight supply|supply crunch|surge|record|expand|expansion|capacity|ramp)/gi;
function glbAgo(pd){
  let ago='',hrs=null;
  try{hrs=(Date.now()-new Date(pd).getTime())/36e5;
      if(isNaN(hrs))hrs=null;
      else ago=hrs<1?'剛剛':hrs<24?Math.round(hrs)+' 小時前':Math.round(hrs/24)+' 天前';}catch(e){}
  return {ago,hrs};
}
function glbSplit(title){
  const p=String(title||'').split(' - ');
  return {t:p.length>1?p.slice(0,-1).join(' - '):title,s:p.length>1?p[p.length-1]:''};
}
function glbParseXml(xml,max){
  try{
    const doc=new DOMParser().parseFromString(xml,'text/xml');
    return [...doc.querySelectorAll('item')].slice(0,max).map(it=>{
      const {t,s}=glbSplit((it.querySelector('title')||{textContent:''}).textContent);
      const {ago,hrs}=glbAgo((it.querySelector('pubDate')||{textContent:''}).textContent);
      return {t,s,l:(it.querySelector('link')||{textContent:'#'}).textContent||'#',ago,hrs};
    }).filter(x=>x.t);
  }catch(e){return [];}
}
async function rssItemsEN(q,max){
  max=max||10;
  const u='https://news.google.com/rss/search?q='+encodeURIComponent(q)+'&hl=en-US&gl=US&ceid=US:en';
  const need=its=>{if(!its||!its.length)throw 0;return its;};
  // 兩路平行競速:誰先回有效資料用誰
  const rA=fT('https://api.rss2json.com/v1/api.json?rss_url='+encodeURIComponent(u),4000)
    .then(r=>{if(!r.ok)throw 0;return r.json();})
    .then(j=>{
      if(!(j&&j.status==='ok'&&Array.isArray(j.items)&&j.items.length))throw 0;
      return need(j.items.slice(0,max).map(it=>{
        const {t,s}=glbSplit(it.title),{ago,hrs}=glbAgo(it.pubDate);
        return {t,s,l:it.link||'#',ago,hrs};
      }).filter(x=>x.t));
    });
  const rB=fT('https://api.allorigins.win/get?url='+encodeURIComponent(u),4000)
    .then(r=>{if(!r.ok)throw 0;return r.json();})
    .then(j=>{
      if(!(j&&j.contents&&j.contents.length>200))throw 0;
      return need(glbParseXml(j.contents,max));
    });
  try{return await Promise.any([rA,rB]);}catch(e){}
  const xml=await fetchTextProxy(u);          // 最後保底
  return xml?glbParseXml(xml,max):[];
}
/* 重大外電分級:紅=供應中斷級事件;琥珀=重量級廠商的缺貨/漲價訊號 */
const GLB_CRIT=/(halt(s|ed)?|suspend(s|ed)?|shut(s)? down|shutdown|fire|earthquake|explosion|export (ban|control|controls|curb|curbs)|ban(s|ned)?|recall|disruption|strike)/i;
const GLB_BIG=/(TSMC|Nvidia|Samsung|SK [Hh]ynix|Micron|Intel|AMD|Apple|Foxconn|Broadcom|ASML)/;
function glbGrade(t){
  if(GLB_CRIT.test(t))return 'red';
  const hot=(t.match(GLB_HOT)||[]).length;
  if(hot>=2||(hot>=1&&GLB_BIG.test(t)))return 'amb';
  return null;
}
async function glbScanAlerts(){
  try{
    const its=await rssItemsEN('(halt OR suspend OR fire OR earthquake OR "export ban" OR "export controls" OR disruption OR recall OR "price hike" OR shortage) (semiconductor OR chip OR TSMC OR memory OR fab OR "supply chain" OR Nvidia)',12);
    const seen=new Set();
    const picks=its
      .map(x=>({...x,lv:glbGrade(x.t)}))
      .filter(x=>x.lv&&x.hrs!=null&&x.hrs<=48)          // 48 小時內才算「現在重要」
      .filter(x=>{const k=x.t.slice(0,40);if(seen.has(k))return false;seen.add(k);return true;})
      .sort((a,b)=>(a.lv==='red'?0:1)-(b.lv==='red'?0:1)||a.hrs-b.hrs)
      .slice(0,3)
      .map(x=>({lv:x.lv,l:x.l,ago:x.ago,
        tags:GLB_MAP.filter(([re])=>re.test(x.t)).slice(0,2).map(([,nm])=>nm),
        t:x.t.length>72?x.t.slice(0,70)+'…':x.t}));
    window.__glbAlerts=picks;
    try{renderMacroAlerts();}catch(e){}
  }catch(e){}
}
setTimeout(glbScanAlerts,12000);
setInterval(glbScanAlerts,15*60e3);
/* 規則式中文重點:標題 → 「誰 + 發生什麼 + 對台股方向」一句話 */
