function glbBrief(t,tags){
  const act=GLB_ACT.find(([re])=>re.test(t));
  const comps=GLB_COMP.filter(([re])=>re.test(t)).map(([,x])=>x).slice(0,2);
  const objs=GLB_OBJ.filter(([re])=>re.test(t)).map(([,x])=>x).slice(0,2);
  if(!act){
    const subj=[...comps,...objs].slice(0,3).join('、');
    const tg=(tags&&tags.length)?tags.join('/'):null;
    if(subj||tg)return `${subj||tg} 相關產業動態 → ${tg?`<b>${tg}</b> 族群`:'供應鏈'}題材面持續關注(標題無明確供需方向)`;
    return `供應鏈一般動態 → 產業氛圍觀察(標題無明確供需方向)`;
  }
  const pct=/漲價|降價/.test(act[1])?(t.match(/(\d+(?:\.\d+)?)\s?%/)||[])[1]:null;
  const subj=[...comps,...objs].slice(0,3).join('、')||'供應鏈';
  const tg=(tags&&tags.length)?tags.join('/'):null;
  const dir=act[2]==='bull'?`→ 供不應求氛圍,${tg?`台股 <b>${tg}</b> 族群`:'相關台股'}偏多解讀`
          :act[2]==='cut' ?`→ 供給中斷,留意${tg?` <b>${tg}</b> `:'同業'}轉單與漲價效應`
          :act[2]==='good'?`→ 基本面利多,${tg?`<b>${tg}</b> 族群`:'相關台股'}偏多解讀`
          :act[2]==='twp'?`→ 海外擴產卡關,<b>台廠製造/代工地位</b>相對受惠的解讀`
          :act[2]==='neu'?`→ 產業題材動態,${tg?`<b>${tg}</b> 族群`:'相關台股'}保持關注(方向中性)`
          :`→ 偏空/政策風險,${tg?`<b>${tg}</b> 族群`:'相關台股'}留意`;
  return `${subj} ${act[1]}${pct?`(約 ${pct}%)`:''} ${dir}`;
}
window.__glbCache={};
async function glbLoad(i){
  const tabs=document.getElementById('glbTabs'),list=document.getElementById('glbList');
  if(!tabs||!list)return;
  tabs.querySelectorAll('.glb-tab').forEach((b,k)=>b.classList.toggle('on',k===i));
  const c=window.__glbCache[i];
  const render=its=>{
    if(!document.getElementById('glbList'))return;
    if(!its.length){
      list.innerHTML=`<div class="dim-note">外電暫時載入不到(免費代理偶爾塞車,稍後自動可用)——<a href="https://news.google.com/search?q=${encodeURIComponent(GLB_TOPICS[i][1])}&hl=en-US&gl=US&ceid=US:en" target="_blank" rel="noopener" style="color:var(--amber)">直接開 Google News 看這個主題 ↗</a></div>`;
      return;
    }
    window.__glbActive=i;
    list.innerHTML=its.map((x,ix)=>{
      const lv=glbGrade(x.t);
      const tagNames=GLB_MAP.filter(([re])=>re.test(x.t)).slice(0,3).map(([,name])=>name);
      const tags=tagNames.map(name=>`<span class="glb-chip">→ ${name}</span>`).join('');
      const tt=x.t.replace(GLB_HOT,'<span class="hotw">$1</span>');
      const brief=glbBrief(x.t,tagNames);
      return `<div class="glb-row${lv==='red'?' crit':''}" style="flex-direction:column;align-items:stretch;gap:2px">
        <div style="display:flex;gap:10px;align-items:baseline"><span style="min-width:0">${lv==='red'?'🚨 ':''}<a href="${x.l}" target="_blank" rel="noopener">${tt}</a>${tags}</span><span class="meta" style="margin-left:auto">${x.s}${credBadge(x.s)}${x.ago?' · '+x.ago:''}</span></div>
        <div class="glb-brief">💡 <b>重點:</b>${brief}<button class="glb-aibtn" data-gix="${ix}">✦ AI 解讀</button></div>
        ${(()=>{const ss=glbStocks(tagNames);return ss.length?`<div style="margin-top:3px;font-size:13px"><span style="color:var(--mut);font-weight:800">🎯 相關個股:</span>${ss.map(s=>s.inPool?`<a class="glb-stk" href="#stock/${s.id}">${s.nm} ${s.id}</a>`:`<span class="glb-stk dim">${s.nm} ${s.id}</span>`).join('')}<span style="color:var(--dim);font-size:11.5px">(供應鏈代表參考,非投資建議)</span></div>`:'';})()}
      </div>`;
    }).join('');
  };
  if(c&&Date.now()-c.t<10*60e3){render(c.items);return;}
  try{const ls=JSON.parse(localStorage.getItem('glb_c_'+i)||'null');
    if(ls&&Date.now()-ls.t<10*60e3&&ls.items&&ls.items.length){
      window.__glbCache[i]=ls;render(ls.items);return;}}catch(e){}
  list.innerHTML='<div class="dim-note">外電載入中…</div>';
  const its=await Promise.race([
    rssItemsEN(GLB_TOPICS[i][1],10),
    new Promise(r=>setTimeout(()=>r([]),15000))]);
  if(its.length){
    window.__glbCache[i]={t:Date.now(),items:its};
    try{localStorage.setItem('glb_c_'+i,JSON.stringify(window.__glbCache[i]));}catch(e){}
  }
  render(its);
}
(function glbInit(){
  const tabs=document.getElementById('glbTabs');
  if(!tabs)return;
  tabs.innerHTML=GLB_TOPICS.map(([name],k)=>`<button class="glb-tab${k===0?' on':''}" data-g-i="${k}">${name}</button>`).join('');
  tabs.querySelectorAll('.glb-tab').forEach(b=>b.onclick=()=>glbLoad(+b.dataset.gI));
  const list=document.getElementById('glbList');
  if(list)list.addEventListener('click',e=>{
    const b=e.target.closest('.glb-aibtn');
    if(!b)return;
    const c=window.__glbCache[window.__glbActive];
    const it=c&&c.items&&c.items[+b.dataset.gix];
    if(!it)return;
    try{aiInline(b,`這是一則國際供應鏈外電:「${it.t}」(來源:${it.s||'外電'}${it.ago?'、'+it.ago:''})。請先上網搜尋這個標題、找到並閱讀原文內容後再回答。用繁體中文條列(直接開始不要開場白):\n1) 新聞內容重點(不只標題,講清楚脈絡與數字)\n2) 對應台股族群與 3~6 檔相關個股(股名+代號),各自關聯與利多/利空方向\n3) 值得追蹤的確認點(報價、法說、月營收、訂單)\n推測的部分請明說,結尾一行:非投資建議。`,true);}catch(err){}
  });
  setTimeout(async()=>{
    try{await glbLoad(0);}catch(e){}
    for(let i=1;i<GLB_TOPICS.length;i++){          // 背景預抓其餘主題
      await new Promise(r=>setTimeout(r,900));
      try{
        if(window.__glbCache[i])continue;
        let ls=null;try{ls=JSON.parse(localStorage.getItem('glb_c_'+i)||'null');}catch(e){}
        if(ls&&Date.now()-ls.t<10*60e3&&ls.items&&ls.items.length){window.__glbCache[i]=ls;continue;}
        const its=await rssItemsEN(GLB_TOPICS[i][1],10);
        if(its.length){
          window.__glbCache[i]={t:Date.now(),items:its};
          try{localStorage.setItem('glb_c_'+i,JSON.stringify(window.__glbCache[i]));}catch(e){}
        }
      }catch(e){}
    }
  },6000);
})();
async function rssItems(q,max,sym){
  // 主力:Yahoo 搜尋 API(直連可用);備援:Google/Bing RSS(需代理)
  for(const key of [sym,q].filter(Boolean)){
    const its=await yNews(key,max||8);
    if(its.length)return its;
  }
  const urls=[
    'https://news.google.com/rss/search?q='+encodeURIComponent(q)+'&hl=zh-TW&gl=TW&ceid=TW:zh-Hant',
    'https://www.bing.com/news/search?q='+encodeURIComponent(q)+'&format=rss&setlang=zh-TW'];  // 備援(需代理)
  for(const u of urls){
    const t=await fetchTextProxy(u);
    if(!t)continue;
    try{
      const doc=new DOMParser().parseFromString(t,'text/xml');
      const items=[...doc.querySelectorAll('item')].slice(0,max||8).map(it=>{
        const title=(it.querySelector('title')||{textContent:''}).textContent||'';
        const p=title.split(' - ');
        return {t:p.length>1?p.slice(0,-1).join(' - '):title,
                s:p.length>1?p[p.length-1]:'',
                l:(it.querySelector('link')||{textContent:'#'}).textContent||'#',
                d:((it.querySelector('pubDate')||{textContent:''}).textContent||'').slice(5,16)};
      }).filter(x=>x.t);
      if(items.length)return items;
    }catch(e){}
  }
  return [];
}
async function evNews(q,box){
  const items=await rssItems(q,6);
  if(!box||!box.isConnected)return;
  box.innerHTML=items.length?`<div class="news" style="border:none;padding:0">${items.map(x=>
    `<a href="${x.l}" target="_blank" rel="noopener"><span>${x.t}</span><span class="src">${x.s}${x.d?' · '+x.d:''}</span></a>`).join('')}</div>`
    :'<div class="dim-note">新聞暫時載入不到,點下方連結直接搜尋。</div>';
}
