let MMETA=null;
function mkLoadLS(){
  try{const h=JSON.parse(localStorage.getItem('mkt_hist')||'null');
      return (h&&Array.isArray(h.d))?h:{d:[],f:[],t:[],g:[]};}
  catch(e){return {d:[],f:[],t:[],g:[]};}
}
function mkSaveLS(h,skip){
  try{localStorage.setItem('mkt_hist',JSON.stringify(h));
      localStorage.setItem('mkt_skip',JSON.stringify(skip.slice(-140)));}catch(e){}
}
function tpNow(){return new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Taipei'}));}
function isoOf(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
async function getMktHist(onProg){
  const meta=await loadMMeta();
  const map={};
  const add=h=>{if(h&&Array.isArray(h.d))h.d.forEach((dd,i)=>{map[dd]=[h.f[i],h.t[i],h.g[i]];});};
  add(meta&&meta.mkt);          // 後端累積(若有)
  add(mkLoadLS());              // 本機快取
  let skip=[];try{skip=JSON.parse(localStorage.getItem('mkt_skip')||'[]');}catch(e){}
  const skipSet=new Set(skip);
  const todayIso=isoOf(tpNow());
  // 找出缺少的交易日(平日),往回最多 100 個日曆日、湊滿 65 個交易日
  const need=[];
  let d=tpNow();
  for(let w=0;w<100&&(Object.keys(map).length+need.length)<66;w++){
    const wd=d.getDay(),iso=isoOf(d);
    if(wd!==0&&wd!==6&&!map[iso]&&!skipSet.has(iso))need.push(new Date(d));
    d.setDate(d.getDate()-1);
  }
  let done=0;
  for(const dd of need){
    if(!location.hash.startsWith('#macro/'))break;  // 使用者離開就停,下次續補
    const iso=isoOf(dd);
    const ds=iso.replace(/-/g,'');
    const j=await fetchTWJSON(`https://www.twse.com.tw/rwd/zh/fund/BFI82U?dayDate=${ds}&type=day&response=json`);
    done++;if(onProg)onProg(done,need.length);
    if(j&&j.stat==='OK'&&Array.isArray(j.data)){
      let f=0,t=0,g=0;
      j.data.forEach(row=>{
        const name=String(row[0]||''),net=parseFloat(String(row[3]||'0').replace(/,/g,''))/1e8;
        if(name.includes('外資'))f+=net;
        else if(name.includes('投信'))t+=net;
        else if(name.includes('自營'))g+=net;});
      map[iso]=[+f.toFixed(1),+t.toFixed(1),+g.toFixed(1)];
    }else if(iso!==todayIso){   // 今天可能還沒公布(約15:00後),不列入永久略過
      skipSet.add(iso);          // 假日/休市:記下來以後不再重抓
    }
    await new Promise(r=>setTimeout(r,220));
  }
  const ds2=Object.keys(map).sort().slice(-65);
  const h={d:ds2,f:ds2.map(x=>map[x][0]),t:ds2.map(x=>map[x][1]),g:ds2.map(x=>map[x][2])};
  mkSaveLS(h,[...skipSet]);
  return h;
}
async function loadMMeta(){
  if(MMETA!==null)return MMETA;
  try{
    const r=await fetch('c/meta.json?v='+encodeURIComponent(DATA&&DATA.updated||''),{cache:'no-store'});
    MMETA=r.ok?await r.json():{};
  }catch(e){MMETA={};}
  return MMETA;
}
async function instTable(){
  try{
    const box=document.getElementById('instTblBox');if(!box)return;
    const m=await loadMMeta();
    const mk=m&&m.mkt;
    if(!mk||!mk.d||!mk.d.length){box.innerHTML='<div class="dim-note">尚無資料</div>';return;}
    const n=mk.d.length,st=Math.max(0,n-14);
    const cell=v=>{if(v==null)return '<td style="text-align:right;color:var(--dim)">—</td>';
      const c=v>=0?'var(--up)':'var(--down)';return `<td style="text-align:right;color:${c};font-variant-numeric:tabular-nums;padding:5px 10px;white-space:nowrap">${v>=0?'+':''}${v.toFixed(1)}</td>`;};
    let rows='';
    for(let i=st;i<n;i++){
      const last=i===n-1;
      const sum=(mk.f[i]||0)+(mk.t[i]||0)+(mk.g[i]||0);
      rows+=`<tr style="${last?'background:color-mix(in srgb,var(--gold,var(--amber)) 14%,var(--panel))':''}">
        <td style="padding:5px 10px;white-space:nowrap;font-weight:${last?'800':'600'}">${mk.d[i].slice(5).replace('-','/')}${last?' ★':''}</td>
        ${cell(mk.f[i])}${cell(mk.t[i])}${cell(mk.g[i])}${cell(+sum.toFixed(1))}</tr>`;
    }
    box.innerHTML=`<table style="border-collapse:collapse;width:100%;font-size:13.5px;min-width:420px">
      <thead><tr style="border-bottom:1px solid var(--line,#e5e0d8);color:var(--dim);font-size:12.5px">
        <th style="text-align:left;padding:5px 10px">日期</th>
        <th style="text-align:right;padding:5px 10px">外資</th>
        <th style="text-align:right;padding:5px 10px">投信</th>
        <th style="text-align:right;padding:5px 10px">自營</th>
        <th style="text-align:right;padding:5px 10px">合計</th></tr></thead>
      <tbody>${rows}</tbody></table>
      <div class="dim-note" style="margin-top:6px">單位:億元;正=淨買超(紅)、負=淨賣超(綠);★=最新交易日。來源:證交所 BFI82U 集中市場盤後,每日排程自動更新。</div>`;
  }catch(e){}
}
function drawMacroLine(domId,d,dg){
  const pts=[],dts=[];
  for(let i=0;i<d.t.length;i++){if(d.c[i]!=null){pts.push(+d.c[i].toFixed(dg));dts.push(new Date(d.t[i]*1000).toLocaleDateString('zh-TW',{month:'2-digit',day:'2-digit'}));}}
  const box=document.getElementById(domId);
  if(!box||!window.echarts)return pts;    // 圖表已移除:仍回傳收盤數列供規則化判讀使用
  echarts.dispose(box);
  const ch=echarts.init(box);chipCharts.push(ch);
  const ma=(p)=>pts.map((_,i)=>i<p-1?null:+(pts.slice(i-p+1,i+1).reduce((a,b)=>a+b,0)/p).toFixed(dg));
  const last=pts[pts.length-1],first=pts[0],up=last>=first;
  ch.setOption({
    tooltip:{trigger:'axis',backgroundColor:CT.ttBg,borderColor:CT.border,textStyle:{color:CT.ttText,fontSize:13}},
    legend:{data:['收盤','MA20','MA60'],textStyle:{color:CT.legend,fontSize:12},top:0},
    grid:{left:64,right:16,top:30,bottom:24},
    xAxis:{type:'category',data:dts,axisLabel:{color:CT.axis,fontSize:11,interval:Math.ceil(dts.length/8)},axisLine:{lineStyle:{color:CT.border}}},
    yAxis:{type:'value',scale:true,axisLabel:{color:CT.axis,fontSize:11},splitLine:{lineStyle:{color:CT.split}}},
    dataZoom:[{type:'inside'}],
    series:[
      {name:'收盤',type:'line',data:pts,showSymbol:false,lineStyle:{width:2,color:up?'#E5484D':'#21A466'},
       areaStyle:{color:up?'rgba(229,72,77,.08)':'rgba(33,164,102,.08)'}},
      {name:'MA20',type:'line',data:ma(20),showSymbol:false,lineStyle:{width:1.4,color:TONE.gold}},
      {name:'MA60',type:'line',data:ma(60),showSymbol:false,lineStyle:{width:1.4,color:TONE.blue}}
    ]});
  return pts;
}
function mkTrendText(pts,dg,def){
  if(!pts||pts.length<20)return'';
  const last=pts[pts.length-1];
  const avgN=n=>pts.slice(-n).reduce((a,b)=>a+b,0)/Math.min(n,pts.length);
  const ma20=avgN(20),ma60=avgN(60);
  const w=pts.slice(-60),hi=Math.max(...w),lo=Math.min(...w);
  const trend=last>ma20&&ma20>ma60?'<b style="color:var(--up)">短中期趨勢向上</b>(站上20日線且20日在60日之上,多頭排列)'
    :last<ma20&&ma20<ma60?'<b style="color:var(--down)">短中期趨勢向下</b>(20/60日線之下,空方排列)'
    :'<b>區間整理</b>(均線糾結,方向未明)';
  return `現值 <b>${last.toFixed(dg)}</b>,20日均 ${ma20.toFixed(dg)}、60日均 ${ma60.toFixed(dg)};距近三個月高點 ${((last-hi)/hi*100).toFixed(1)}%、低點 +${((last-lo)/lo*100).toFixed(1)}%。${trend}。`;
}
/* 加權/櫃買詳細頁:即時走勢(與首頁同一套 session-safe 資料) */
function drawMkLive(misKey){
  const d=idxPick(misKey);
  const stat=document.getElementById('mkIntraStat');
  const box=document.getElementById('mkIntra');
  const px=document.getElementById('mkPx'),cg=document.getElementById('mkChg');
  const last=IDX.last[misKey];
  const prev=accOf(misKey).prev||(d&&d.prev);          // 昨收以 MIS 官方 y 優先
  if(px&&last)px.textContent=Number((+last).toFixed(2)).toLocaleString();
  if(cg&&last&&prev){const c=(last-prev)/prev*100;
    cg.innerHTML=Math.abs(c)>11?'':` <span class="${c>=0?'pos':'neg'}" style="font-size:17px">${c>=0?'▲':'▼'} ${Math.abs(c).toFixed(2)}%</span>`;}   // 🛡 |漲跌|>11%=壞昨收,不顯示假值
  if(!box)return;
  if(d){
    window.__mkToday=!!(Array.isArray(d.t)&&d.t.length&&tpDay(d.t[d.t.length-1])===tpDay(Date.now()/1000));
    RT.mk=(window.LightweightCharts&&drawIntraLWC('mkIntra',d))||drawIntra('mkIntra',d);
  }else{
    window.__mkToday=false;
    if(stat)stat.textContent=marketOpen()?'今日走勢即時累積中,約 30 秒後出現':'走勢暫時載入不到';
  }
}
/* 基本面卡片即時同步:若營收趨勢圖(FinMind)月份比 data.json 新,直接更新卡片顯示,
   確保「三力檢視-基本面」與圖表永遠同月份;分數待後端下次排程重算 */
function syncRevCard(s,mm,yoy){
  if(!s||!s.f||!mm||!mm.length)return;
  let i=mm.length-1;
  while(i>=0&&(yoy[i]==null))i--;          // 找最後一筆有 YoY 的月份
  if(i<0)return;
  const full='20'+mm[i];                    // '26-06' → '2026-06'
  const cur=(s.f.kv&&s.f.kv['資料年月'])||'';
  if(cur&&full<=cur)return;                 // 卡片已是最新(或更新)就不動
  const v=+yoy[i], txt=(v>0?'+':'')+v.toFixed(1)+'%';
  s.f.kv=s.f.kv||{}; delete s.f.kv['月營收'];
  s.f.kv['月營收YoY']=txt; s.f.kv['資料年月']=full;
  s.f.note=(v>40?'營收動能強勁。':v>5?'營收平穩。':'營收轉弱。')+'(已同步最新公告)';
  document.querySelectorAll('#detailView .dim-block').forEach(b=>{
    const h=b.querySelector('h3');
    if(!h||h.textContent.indexOf('基本面')!==0)return;
    const kv=b.querySelector('.kv');
    if(kv)kv.innerHTML=Object.entries(s.f.kv).map(([k,val])=>`<div><dt>${k}</dt><dd>${val}</dd></div>`).join('');
    const n=b.querySelector('.dim-note'); if(n)n.textContent=s.f.note;
  });
}
/* ══════════ 白話辭典:全站數據名稱點一下就有大白話解釋 ══════════ */
const GLOSS={
'月營收YoY':'公司這個月的營收和「去年同一個月」比,成長或衰退了幾 %。+10% 就是生意比去年同月多做一成。<br><b>怎麼看:</b>正數且越大越好;連續好幾個月都正成長,代表生意越做越大。',
'資料年月':'上面那個營收數字是「哪一個月」的。台灣規定公司每月 10 日前要公布上個月的營收。',
'月營收':'公司一個月做了多少生意(還沒扣成本)。重點通常不是金額大小,而是和去年同月比的成長率。',
'財報':'公司每三個月交一次的成績單,常看三個獲利率:毛利率(產品好不好賺)、營益率(扣掉營運開銷後)、淨利率(最後真正賺的)。<b>三率同時比上一季進步=體質變好。</b>',
'外資5日':'外資=外國大型投資機構。這是他們最近 5 個交易日「合計買了還是賣了」多少張。<br><b>怎麼看:</b>正數=買超(看好)、負數=賣超(看壞或先獲利入袋)。',
'外資20日':'外資最近 20 個交易日(約一個月)的合計買賣超。和 5 日一起看:短期、中期方向一致時,訊號比較可靠。',
'外資60日':'外資最近 60 個交易日(約一季)的合計買賣超,看的是長線態度。',
'外資連買':'外資「連續買超」的天數。連買越多天,代表態度越明確,通常是偏多訊號。',
'投信5日':'投信=台灣的基金公司。他們買進的股票會直接影響基金績效,所以連續買超常帶出波段行情。正=買超、負=賣超。',
'投信20日':'投信最近一個月的合計買賣超。投信偏好中小型股,認養時的影響力常比外資更直接。',
'400張大戶':'持有這檔股票 400 張以上的大股東,合計抱著全部股份的百分比。<br><b>怎麼看:</b>比例上升=籌碼往大戶手裡集中(通常偏多);下降=大戶在慢慢出貨。每週更新一次。',
'融資餘額':'散戶「借錢買股票」還沒還的總張數,括號內是最新一天的增減。<br><b>怎麼看:</b>融資暴增=散戶在追價,籌碼變不穩;股價漲但融資反而減少,通常比較健康。',
'融券餘額':'「借股票先賣、賭它會跌」還沒買回來的張數。<br><b>怎麼看:</b>融券多=看空的人多;但若股價一直漲,這些人被迫回補反而推升股價(俗稱軋空)。',
'券資比':'融券 ÷ 融資的比例。<br><b>怎麼看:</b>超過 30% 代表看空的人很多,一旦轉漲容易軋空大漲;只有零點幾 % 就沒這個題材。',
'借券賣出':'法人版的「借股票來賣」,主角是外資等大資金,常用來看空或避險。餘額持續增加=有大錢在押它跌或對沖;持續下降=空方在撤退。',
'距波段高點':'現在股價離最近一段時間的最高價還差幾 %。-5% 表示再漲 5% 就回到前高;越接近 0 越強勢。',
'20/60MA':'均線=最近 N 天收盤價的平均,可以想成「這段時間買進的人的平均成本」。20MA≈近一個月、60MA≈近一季。<br><b>怎麼看:</b>股價站在均線上=多數人賺錢(偏多);跌破=平均套牢(偏空)。',
'淨未平倉':'期貨市場某一群人「押上漲的單」減「押下跌的單」後的淨部位(口數)。<br><b>怎麼看:</b>正=整體偏多、負=偏空;重點是方向的轉變(由空翻多/由多翻空),不是數字大小。',
'十大交易人':'期貨市場部位最大的前十名(法人+超級大戶),他們的淨部位方向代表市場最大資金的態度。',
'十大特定人':'十大交易人裡面的「特定法人」(銀行、券商、外資機構等),排除了個人大戶,是更純粹的法人籌碼指標。',
'散戶小台':'用小台指期貨反推的散戶多空傾向。<br><b>怎麼看:</b>散戶常常做反方向,所以很多人當「反向指標」——散戶一面倒看空時,行情反而容易漲。',
'殖利率':'現金股利 ÷ 股價,概念像利息。5% = 買 100 元的股票,一年配 5 元現金。<br><b>注意:</b>要「配得穩」而且除息後股價漲得回來(填息)才是真的賺。',
'現金殖利率':'現金股利 ÷ 股價,概念像利息。5% = 買 100 元股票一年領 5 元現金。要配得穩+會填息才算真報酬。',
'除息':'公司發現金股利那天,股價會同額往下調(配 2 元,開盤參考價就少 2 元),之後漲回原價才叫「填息」,填息了才是真的賺到股利。',
'除權':'公司發「股票股利」(配股),你的股數變多、股價按比例往下調,總價值當下不變。',
'綜合分數':'本站把基本面(40%)+籌碼面(35%)+技術面(25%)合成的 0~100 分。66 分以上代表三方面同時不差。<b>它是縮小範圍的篩子,不是買賣建議。</b>',
'基本面':'公司「生意做得好不好」:營收有沒有成長、賺不賺錢。',
'籌碼面':'「誰在買、誰在賣」:法人、大戶、散戶的資金動向。大資金的腳印通常比消息可靠。',
'技術面':'「價格走勢的慣性」:均線、突破、量能。反映的是市場所有人投票出來的結果。',
'5日累計':'三大法人(外資+投信+自營商)最近 5 個交易日合計買超或賣超的金額。正=資金流入市場、負=流出。',
'20日累計':'三大法人最近一個月的合計買賣超金額,看中期資金方向。',
'60日累計':'三大法人最近一季的合計買賣超金額,看長期資金方向。',
'分析師家數':'有出研究報告追蹤這檔股票的券商分析師人數,越多代表市場關注度越高、資訊越透明。',
'RSI':'0~100 的「過熱/過冷」溫度計。<br><b>怎麼看:</b>80 以上=短線漲太快,容易休息;20 以下=殺過頭,容易反彈。',
'MACD':'用兩條均線的距離變化看「動能」。柱狀圖縮短=原本的趨勢在減速;翻紅翻綠常是轉折的早期訊號。',
'箱型':'股價在一個固定區間上下震盪,像被關在箱子裡。<b>帶量突破箱頂</b>常是新一波起漲的訊號;跌破箱底則反之。',
'買進區':'本站定義的「月線~季線之間的均線帶」:多頭股回檔到這裡,是常見的分批留意區。<b>是參考區域,不是保證會漲的價位。</b>',
'停損參考':'跌破這個價位,代表原本看多的理由已被破壞,一般會先出場控制虧損,保留資金等下一次機會。',
'分批獲利':'不要想一次賣在最高點——到第一個壓力(如近月高)先賣一部分落袋,剩下的抱到下一個目標。就算後面回跌,你已經鎖住部分獲利;續漲也還有部位參與。',
'處置股':'短期漲跌或量能異常到觸發交易所警示標準,被「處置」的股票。最常見的措施是<b>改成每 5 或 20 分鐘才撮合一次</b>(平常是隨時撮合),有些還要全額交割。<br><b>怎麼看:</b>處置=籌碼過熱的官方認證,期間流動性差、掛單不會馬上成交,追高風險極大;處置期滿(通常10個交易日)恢復正常。',
'產業龍頭':'同產業中推算市值最大的公司(本站以股價×股本計算)。<br><b>怎麼看:</b>龍頭通常最能反映產業景氣、法人覆蓋最完整、流動性最好;產業行情啟動時常由龍頭先漲,再輪到中小型股。',
'成分股':'ETF 實際持有的股票清單。買一張 ETF = 按權重同時買進這一籃股票,所以看 ETF 先看它裝了什麼。前十大權重通常決定了八成的走勢。',
'ETF 規模':'這檔 ETF 管理的總資產(AUM)。規模太小(台股常以 1~2 億為警戒)有清算下市風險,規模大的流動性與買賣價差通常較好。',
'內扣費用':'經理費+保管費等,每年從淨值中自動扣除,你不會看到帳單但確實在付。長期持有時 0.3% 和 1% 的差距會被複利放大,越低越好。',
'報酬風險比':'如果照劇本走:「可能賺的空間 ÷ 可能賠的空間」。例如買在 100、目標 130、停損 90 → 賺 30 賠 10 = 3:1。<br><b>怎麼看:</b>大於 2 才值得出手是常見紀律——十次對五次也能賺錢;小於 1 代表賠率不划算,再看好也該等更好的價位。',
'本益比':'股價 ÷ 每股一年賺的錢(EPS),意思是「用現在的獲利速度,幾年回本」。20 倍=不成長的話 20 年回本。<br><b>怎麼看:</b>數字越低越便宜,但要跟「同產業」比才有意義——高成長產業天生比較貴。',
'預估本益比':'用「預估的未來一年 EPS」算的本益比。成長股常常「現在看很貴、用明年獲利看就合理」。<br><b>注意:</b>本站是用營收年增率簡易推算,不是分析師預估,參考方向就好。',
'EPS':'每股盈餘=公司一年幫「每一股」賺了多少元。EPS 10 元、股價 200 元 → 本益比 20 倍。EPS 持續成長是股價長期上漲最根本的燃料。',
'股價淨值比':'股價 ÷ 每股淨值(公司帳面上每股值多少)。低於 1 倍=用比帳面價值便宜的價格買到;但金融、景氣循環股常年低於 1 是常態,一樣要跟同業比。',
'同產業中位數':'把同一個產業所有股票的本益比排隊,取中間那一個。個股比它便宜=評價相對低;比它貴=市場給它更高期待。',
'收盤':'一天最後一筆成交的價格。技術分析幾乎都用收盤價,因為它是「多空吵了一整天的最終共識」,比盤中價有代表性。',
'站上20MA':'股價是否高於 20 日均線(月線)。站上=最近一個月買的人平均在賺錢,籌碼安定;跌破=套牢盤增加,反彈常遇到解套賣壓。',
'乖離':'股價偏離均線的百分比。乖離太大(例如高於月線 15%)=短線漲太急,像橡皮筋拉太開,隨時可能回彈修正;負乖離太深則常見超跌反彈。',
'壓力':'上方賣壓集中的價位——通常是前波高點或大量套牢區,漲到這裡容易遇到解套賣單,需要放量才過得去。',
'支撐':'下方買盤集中的價位——前波低點或均線所在,跌到這裡常有人接。跌破支撐=接的人不接了,通常要再找下一層。',
'右側進場':'不猜底,等股價「確認轉強」(例如帶量突破前高)才進場。買貴一點換確定性高一點,是勝率型打法;相對的「左側」是下跌中分批接,是賭轉折。',
'均線帶':'月線到季線之間的價格區間。多頭行情的回檔常在這個帶子被接住,所以拉回到均線帶=常見的分批買點;跌破整個帶子則趨勢轉弱。',
'三率三升':'毛利率、營益率、淨利率三個獲利指標同時比上一季高——代表公司不只營收成長,「賺錢的效率」也在變好,是基本面最扎實的訊號之一。',
'主力':'泛指有能力影響股價的大額資金(法人、大股東、實力派金主)。散戶跟主力的差別是資訊與資金;看籌碼的本質就是「跟著大錢的腳印走」。',
'跳空缺口':'今天的最低價比昨天的最高價還高(向上跳空),K棒之間出現「空白」——通常是重大利多/利空讓大家搶著用更高(低)價成交。<br><b>怎麼看:</b>缺口=多空力道特別強的位置;沒回補的缺口常變成日後的支撐或壓力,回補(股價走回缺口區)前色帶會一直顯示。',
'爆大量':'單日成交量超過近 20 根平均量的 2.5 倍(量能區的金色量柱,K棒下方有金色小三角定位)。<br><b>怎麼看:</b>大量=大資金在換手。低檔爆量收紅常是止跌起漲訊號;高檔爆量收黑要小心出貨。爆量那根K棒的最低點,常是日後多空的重要防線。',
'ATR':'平均真實波幅——這檔股票「平常一天大概會動多少錢」。海龜法則把它叫做 N,停損距離、加碼間距都用 N 來量,讓波動大的股票自動用比較寬的停損,不會被正常震盪洗出場。',
'停損':'跌破這個價位就出場控制虧損。海龜用「進場價 − 2N」:賠掉超過兩天的正常波動,代表判斷錯了,認賠保留資金等下一次。',
'金字塔加碼':'股票照劇本上漲時才加碼:每漲 0.5N 加一單,最多加 3 次(共 4 單)。<b>越漲越買(但每次量不變)、越跌絕不攤平</b>——讓賺錢的部位放大、賠錢的部位保持最小,是趨勢交易放大利潤的核心。',
'出場':'海龜的離場規則:收盤跌破「10 日低點」就出場,不預設目標價、不猜頭。<b>讓利潤奔跑,但趨勢一轉弱就走</b>,回吐一點沒關係,重點是抓住整段大趨勢。'
};
function glossFind(t){
  t=String(t||'').replace(/\(.*?\)|(.*?)|[|].*$/g,'').trim();
  if(!t)return null;
  if(GLOSS[t])return[t,GLOSS[t]];                    // 先查完全匹配(20/60MA 這種長得像日期的名詞優先命中)
  if(/^\d{2,4}[-\/]|^—/.test(t))return null;         // 再排除日期格式(2026-07-15、07/07)
  for(const k in GLOSS){if(t.indexOf(k)===0||(k.indexOf(t)===0&&t.length>=3))return[k,GLOSS[k]];}
  return null;
}
function showGloss(anchor,term,txt){
  let p=document.getElementById('glossPop');
  if(!p){p=document.createElement('div');p.id='glossPop';document.body.appendChild(p);
    p.addEventListener('click',e=>e.stopPropagation());}
  p.innerHTML=`<div style="display:flex;justify-content:space-between;gap:10px"><b style="color:var(--amber);font-size:14px">💡 ${term}</b><span style="cursor:pointer;color:var(--dim)" onclick="this.closest('#glossPop').style.display='none'">✕</span></div><div style="margin-top:6px">${txt}</div>`;
  p.style.cssText='position:fixed;z-index:998;max-width:min(330px,90vw);background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:12px 14px;font-size:13.5px;line-height:1.8;color:var(--txt2);box-shadow:0 8px 28px rgba(0,0,0,.25);display:block';
  const r=anchor.getBoundingClientRect(),w=Math.min(330,innerWidth*0.9);
  p.style.left=Math.min(Math.max(8,r.left),innerWidth-8-w)+'px';
  p.style.top=(r.bottom+8)+'px';
  requestAnimationFrame(()=>{const pr=p.getBoundingClientRect();
    if(pr.bottom>innerHeight-8)p.style.top=Math.max(8,r.top-pr.height-8)+'px';});
}
document.addEventListener('click',ev=>{
  const p=document.getElementById('glossPop');
  if(p&&p.contains(ev.target))return;
  const dt=ev.target.closest('.kv dt')||ev.target.closest('[data-g]');
  if(!dt){if(p)p.style.display='none';return;}
  const hit=glossFind((dt.dataset&&dt.dataset.g?dt.dataset.g:dt.textContent).replace('💡','').trim());
  if(hit)showGloss(dt,hit[0],hit[1]);
  else if(p)p.style.display='none';
});
/* 💡 白話燈泡:凡辭典有解釋的欄位,自動在旁邊加上可點的燈泡 */
function decorateGloss(root){
  (root||document).querySelectorAll('.kv dt,[data-g]').forEach(el=>{
    if(el.dataset.gb)return;
    const term=(el.dataset&&el.dataset.g)?el.dataset.g:el.textContent.replace('💡','').trim();
    if(!glossFind(term))return;
    el.dataset.gb='1';
    const b=document.createElement('span');
    b.className='gbulb';b.textContent='💡';b.title='點我看白話解釋';
    el.appendChild(b);
    el.style.cursor='help';
  });
}
(function(){
  if(window.MutationObserver){
    let tm;
    new MutationObserver(()=>{clearTimeout(tm);tm=setTimeout(()=>{try{decorateGloss(document);}catch(e){}},250);})
      .observe(document.body,{childList:true,subtree:true});
  }
  setTimeout(()=>{try{decorateGloss(document);}catch(e){}},1200);
})();

/* ══ 除權息與重大時間:FinMind 股利政策(近三年+已公告的未來場次)══ */
let curDivs=null;
async function loadDivEvents(s){
  if(s.market!=='TW'){curDivs=null;return;}
  let ev=[];
  try{
    const start=new Date(Date.now()-10.2*365*86400000).toISOString().slice(0,10);   // 10年:供連續配息年數統計
    const r=await fT(`https://api.finmindtrade.com/api/v4/data?dataset=TaiwanStockDividend&data_id=${s.id}&start_date=${start}`,12000);
    if(r&&r.ok){
      const j=await r.json();
      ((j&&j.data)||[]).forEach(x=>{
        const cash=(+x.CashEarningsDistribution||0)+(+x.CashStatutorySurplus||0);
        const stk=(+x.StockEarningsDistribution||0)+(+x.StockStatutorySurplus||0);
        const cd=String(x.CashExDividendTradingDate||'').slice(0,10);
        const sd=String(x.StockExDividendTradingDate||'').slice(0,10);
        const pd=String(x.CashDividendPaymentDate||'').slice(0,10);
        if(cash>0&&cd.length===10&&cd>'1990')ev.push({d:cd,t:'除息',v:cash,pay:(pd.length===10&&pd>'1990')?pd:null,yr:x.year||''});
        if(stk>0&&sd.length===10&&sd>'1990')ev.push({d:sd,t:'除權',v:stk,yr:x.year||''});
      });
      const seen={};
      ev=ev.filter(e=>{const k=e.d+e.t;if(seen[k])return false;seen[k]=1;return true;}).sort((a,b)=>a.d<b.d?-1:1);
    }
  }catch(e){}
  if(location.hash!=='#stock/'+s.id)return;
  curDivs=ev;
  const tryRender=n=>{
    if(location.hash!=='#stock/'+s.id)return;
    if(document.getElementById('divTL')){try{renderDivTimeline(s);}catch(e){}}
    else if(n>0)setTimeout(()=>tryRender(n-1),800);
  };
  tryRender(5);
  try{if(ev.length&&localStorage.getItem('kDV')!=='0'&&document.getElementById('kbox'))drawKChart();}catch(e){}
}
function renderDivTimeline(s){
  const el=document.getElementById('divTL');
  if(!el)return;
  if(!curDivs||!curDivs.length){
    el.innerHTML='<div class="dim-block"><h3>'+(s.etf?'📅 配息紀錄':'📅 除權息與重大時間')+'</h3><div class="dim-note">尚無已公告的除權息資料(新掛牌、不配息或公司尚未公告)。股東會/法說會等其他重大行事曆,請以公開資訊觀測站公告為準。</div></div>';
    return;
  }
  const today=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Taipei'})).toISOString().slice(0,10);
  const px=(s.price&&s.price>0)?s.price:null;
  let divSum='';                                        // 📜 股利政策連續性:連續配息年數+近一年發放率
  try{
    const byY={};
    curDivs.forEach(e2=>{if(e2.t==='除息'&&e2.d<=today){const y2=+String(e2.d).slice(0,4);byY[y2]=(byY[y2]||0)+e2.v;}});
    const ys=Object.keys(byY).map(Number).sort((a,b)=>b-a);
    if(ys.length){
      const nowY=+today.slice(0,4);
      let streak=0,y2=byY[nowY]?nowY:nowY-1;
      while(byY[y2]){streak++;y2--;}
      const lastY=ys[0],lastAmt=byY[lastY];
      const payout=(s.eps&&s.eps>0)?Math.round(lastAmt/s.eps*100):null;
      const pTag=payout==null?'':payout>100?`發放率 ${payout}%(超過EPS,恐吃老本,留意持續性)`:payout>=70?`發放率 ${payout}%(大方,成長再投資空間小)`:payout>=30?`發放率 ${payout}%(平衡)`:`發放率 ${payout}%(保守,盈餘多留作成長)`;
      divSum=`<div style="display:flex;gap:8px 16px;flex-wrap:wrap;align-items:baseline;margin:2px 0 8px;padding:9px 13px;background:var(--panel2);border-radius:10px;font-size:13.5px">
        <span>📜 <b style="color:${streak>=10?'var(--down)':streak>=5?'var(--txt)':'var(--mut)'}">連續配息 ${streak} 年</b>${streak>=10?'(存股體質)':streak>=5?'(政策穩定)':streak<=1?'(尚無連續紀錄)':''}</span>
        <span>近一年現金股利 <b style="font-family:var(--mono)">${lastAmt.toFixed(2)}</b> 元${s.eps?` · EPS ${s.eps}`:''}</span>
        ${pTag?`<span style="color:var(--mut)">${pTag}</span>`:''}
      </div>`;
    }
  }catch(e){}
  const pxBefore=d=>{                      // 除息前一日收盤價(用已載入的K線資料查)
    try{
      if(!baseK||!Array.isArray(baseK.dates))return null;
      const ds=baseK.dates;
      for(let j=ds.length-1;j>=0;j--){if(ds[j]<d)return baseK.ohlc[j][3]||null;}
    }catch(e){}
    return null;
  };
  const up=curDivs.filter(e=>e.d>=today);
  const past=curDivs.filter(e=>e.d<today).slice(-8).reverse();
  // 近一年(過去365天已除息 + 已公告未到的場次)現金股利合計 → 以現價計殖利率
  const yago=new Date(Date.now()-365*86400000).toISOString().slice(0,10);
  const cashTTM=curDivs.filter(e=>e.t==='除息'&&e.d>=yago).reduce((a,e)=>a+(+e.v||0),0);
  const ttmY=(px&&cashTTM>0)?(cashTTM/px*100):null;
  const line=e=>{
    let extra='';
    if(e.t==='除息'){
      const p0=pxBefore(e.d);
      if(p0)extra=` · 殖利率 ${((+e.v)/p0*100).toFixed(2)}%(除息前收盤 ${(+p0).toFixed(1)})`;
      else if(px)extra=` · 以現價計約 ${((+e.v)/px*100).toFixed(2)}%`;
    }
    return `<div><dt>${e.d}${e.yr?`(${e.yr} 年度)`:''}</dt><dd>${e.t==='除息'?'💰 除息':'🎁 除權'} ${(+e.v).toFixed(2)} 元${extra}${e.pay?` · 發放日 ${e.pay}`:''}</dd></div>`;
  };
  const upTxt=e=>`${e.d} ${e.t} ${(+e.v).toFixed(2)} 元`+
    (e.t==='除息'&&px?`(以現價 ${px} 計,殖利率約 ${((+e.v)/px*100).toFixed(2)}%)`:'')+
    (e.pay?`(發放日 ${e.pay})`:'');
  el.innerHTML=`<div class="dim-block" style="border-left:4px solid #C792EA">
    <h3>${s.etf?'📅 配息與殖利率':'📅 除權息與重大時間'} <span class="ds">${ttmY!=null?`近一年現金股利 ${cashTTM.toFixed(2)} 元 · 現金殖利率約 ${ttmY.toFixed(2)}%`:(up.length?'下一場 '+up[0].d:'近三年 '+curDivs.length+' 筆')}</span></h3>
    ${divSum}
    ${up.length?`<div class="thesis" style="border-color:var(--t-purple)"><b style="color:var(--t-purple)">⏰ 即將到來:</b>${up.map(upTxt).join('、')}——除權息日前一天為最後過戶基準,參與與否請留意稅務與貼息風險。</div>`:''}
    ${past.length?`<div class="kv">${past.map(line).join('')}</div>`:''}
    <div class="dim-note">殖利率說明:標題列為「近一年現金股利合計 ÷ 現價」;歷史各場次以「該次除息前一日收盤價」計算,較能反映當時的實際殖利率;若當日價格不在已載入的K線範圍內,則以現價概算。殖利率高低請搭配填息紀錄與獲利穩定度一起看,高殖利率若長年貼息反而侵蝕本金。來源:FinMind 股利政策。K 線圖上的 💰/🎁 垂直虛線為歷次除權息日,可用 K 線區「除權息」鈕開關;股東會、法說會以公開資訊觀測站為準。</div>
  </div>`;
}
/* 爆大量偵測:量 > 近20根均量×2.5,回傳索引集合(量柱高亮與主圖三角共用) */
function volSpikes(o){
  const s=new Set();
  if(!o||o.length<25)return s;
  for(let i=20;i<o.length;i++){
    let sum=0;for(let j=i-20;j<i;j++)sum+=(o[j][4]||0);
    const av=sum/20;
    if(av>0&&(o[i][4]||0)>av*2.5)s.add(i);
  }
  return s;
}
/* 跳空缺口(未回補色帶)+ 爆大量標記(量柱金色高亮+K棒下方金色小三角) */
function gapVolSeries(o,dates){
  if(localStorage.getItem('kGP')==='0'||!o||o.length<25||!dates)return[];
  const mob=innerWidth<640, mpts=[], areas=[];
  const gaps=[];
  for(let i=1;i<o.length;i++){
    const ph=o[i-1][1],pl=o[i-1][2];
    if(o[i][2]>ph*1.003)gaps.push({i,up:1,top:o[i][2],bot:ph});        // 向上跳空:今低>昨高
    else if(o[i][1]<pl*0.997)gaps.push({i,up:0,top:pl,bot:o[i][1]});   // 向下跳空:今高<昨低
  }
  const unfilled=gaps.filter(g=>{
    for(let j=g.i+1;j<o.length;j++)
      if(g.up?(o[j][2]<=g.bot):(o[j][1]>=g.top))return false;          // 已回補
    return true;
  });
  unfilled.slice(-6).forEach(g=>{
    const col=g.up?TONE.purple:TONE.red;
    areas.push([{name:(g.up?'⬆ 跳空缺口':'⬇ 跳空缺口'),xAxis:dates[g.i],yAxis:g.top,
      itemStyle:{color:hexA(col,.15),borderColor:hexA(col,.4),borderWidth:1,borderType:'dashed'},
      label:{show:true,position:mob?'insideLeft':'insideRight',fontSize:mob?8.5:9.5,color:col}},
      {xAxis:dates[o.length-1],yAxis:g.bot}]);
  });
  const _amb=cssVar('--amber')||TONE.gold;
  [...volSpikes(o)].slice(-10).forEach(i=>{
    mpts.push({name:'爆大量',coord:[dates[i],o[i][2]],
      symbol:'triangle',symbolSize:mob?5.5:7,symbolOffset:[0,9],
      itemStyle:{color:_amb,opacity:.9},
      label:{show:false},
      tooltip:{formatter:`爆大量 ${dates[i]}<br>成交量達近 20 根均量 2.5 倍以上(下方金色量柱)<br>當日低點 ${o[i][2]} 常是日後多空防線`}});
  });
  if(!areas.length&&!mpts.length)return[];
  return[{name:'缺口量能',type:'line',data:[],xAxisIndex:0,yAxisIndex:0,silent:false,showSymbol:false,
    markArea:{silent:true,data:areas,animation:false},
    markPoint:{silent:false,data:mpts,animation:false}}];
}
/* 跳空缺口(未回補色帶)佔位註解結束 */
function divMarkSeries(){
  if(!curDivs||!curDivs.length||localStorage.getItem('kDV')==='0'||!curDates||!curDates.length)return[];
  const mob=innerWidth<640;   // 手機:標籤只留圖示,避免互相蓋住
  const mk=[];
  curDivs.forEach(e=>{
    if(e.d<curDates[0]||e.d>curDates[curDates.length-1])return;   // 未來場次列在時間表,不畫進K線
    let lo=0,hi=curDates.length-1,idx=curDates.length-1;
    while(lo<=hi){const m2=(lo+hi)>>1;if(curDates[m2]>=e.d){idx=m2;hi=m2-1;}else lo=m2+1;}
    const col=e.t==='除息'?TONE.purple:TONE.green;
    mk.push({name:e.t,xAxis:curDates[idx],
      lineStyle:{color:col,type:'dashed',width:1.2},
      label:{show:true,position:'end',
        formatter:mob?(e.t==='除息'?'💰':'🎁'):`${e.t==='除息'?'💰':'🎁'}${(+e.v).toFixed(1)}`,
        fontSize:mob?9:10,color:col,backgroundColor:CT.ttBg,borderColor:CT.border,borderWidth:1,
        padding:mob?[1,3]:[2,6],borderRadius:5}});
  });
  if(!mk.length)return[];
  return [{name:'除權息',type:'line',xAxisIndex:0,yAxisIndex:0,data:[],showSymbol:false,silent:true,
    markLine:{symbol:'none',silent:true,animation:false,data:mk}}];
}
/* 信用交易歷史:FinMind 直連近一年 融資/融券(TaiwanStockMarginPurchaseShortSale)
   + 借券賣出餘額(TaiwanDailyShortSaleBalances);失敗回退站內每日累積(cd/mf/mv/sb) */
async function loadCreditTrend(s,e){
  const box=document.getElementById('credBox'),st=document.getElementById('credStat');
  if(!box)return;
  let d=[],mf=[],mv=[],sb=[],src='FinMind';
  try{
    const start=new Date(Date.now()-190*86400000).toISOString().slice(0,10);   // 近6個月
    const [r1,r2]=await Promise.all([
      fT(`https://api.finmindtrade.com/api/v4/data?dataset=TaiwanStockMarginPurchaseShortSale&data_id=${s.id}&start_date=${start}`,12000),
      fT(`https://api.finmindtrade.com/api/v4/data?dataset=TaiwanDailyShortSaleBalances&data_id=${s.id}&start_date=${start}`,12000)
    ]);
    const j1=r1&&r1.ok?await r1.json():null, j2=r2&&r2.ok?await r2.json():null;
    const m={};
    ((j1&&j1.data)||[]).forEach(x=>{
      const o=m[x.date]=m[x.date]||{};
      const f=+x.MarginPurchaseTodayBalance, v=+x.ShortSaleTodayBalance;   // 單位:張
      if(isFinite(f))o.f=f; if(isFinite(v))o.s=v;
    });
    ((j2&&j2.data)||[]).forEach(x=>{
      const o=m[x.date]=m[x.date]||{};
      const v=+x.SBLShortSalesCurrentDayBalance;                            // 單位:股 → 張
      if(isFinite(v))o.l=Math.round(v/1000);
    });
    const ks=Object.keys(m).sort();
    if(ks.length>=5)ks.forEach(k=>{d.push(k);mf.push(m[k].f!=null?m[k].f:null);mv.push(m[k].s!=null?m[k].s:null);sb.push(m[k].l!=null?m[k].l:null);});
  }catch(err){}
  if(!d.length&&e&&Array.isArray(e.cd)&&e.cd.length){                      // 站內累積回退
    src='站內累積';
    d=e.cd.slice();mf=e.mf||[];mv=e.mv||[];sb=e.sb||[];
  }
  if(location.hash!=='#stock/'+s.id)return;
  if(!d.length){if(st)st.textContent='信用交易資料暫缺(部分上櫃/新掛牌檔待累積)';return;}
  if(d.length>132){const cut=d.length-132;d=d.slice(cut);mf=mf.slice(cut);mv=mv.slice(cut);sb=sb.slice(cut);}
  let px=null;                                        // 疊股價:對照信用與價格的關係
  try{
    if(baseK&&baseK.dates&&baseK.ohlc){
      const pm={};baseK.dates.forEach((k,i)=>pm[k]=baseK.ohlc[i][3]);
      const arr=d.map(k=>pm[k]??null);
      if(arr.some(v=>v!=null))px=arr;
    }
  }catch(e){}
  try{window.__credData={id:s.id,d:d.slice(),mf:mf.slice(),mv:mv.slice(),sb:sb.slice()};   // r538:供籌碼健檢補判信用面
    chipHealth(s,e);}catch(e8){}
  const lastN=a=>{for(let i=a.length-1;i>=0;i--)if(a[i]!=null)return a[i];return null;};
  const lf=lastN(mf),ls=lastN(mv),ll=lastN(sb);
  const ratio=(lf&&ls!=null)?((ls/lf)*100).toFixed(1)+'%':'—';
  if(st)st.textContent=`${d.length} 日(${src})· 融資 ${lf!=null?lf.toLocaleString():'—'} · 融券 ${ls!=null?ls.toLocaleString():'—'} · 借券賣 ${ll!=null?ll.toLocaleString():'—'} 張 · 券資比 ${ratio}`;
  if(!window.echarts)return;
  echarts.dispose(box);box.innerHTML='';
  const ch=echarts.init(box);chipCharts.push(ch);
  ch.setOption({
    backgroundColor:'transparent',
    textStyle:{fontFamily:'IBM Plex Mono,monospace'},
    legend:{data:['融資餘額','融券餘額','借券賣出餘額'].concat(px?['股價']:[]),top:0,textStyle:{color:CT.legend,fontSize:12}},
    tooltip:{trigger:'axis',backgroundColor:CT.ttBg,borderColor:CT.border,textStyle:{color:CT.ttText,fontSize:13},
      valueFormatter:v=>v!=null?(+v).toLocaleString('zh-TW')+' 張':'—'},
    grid:{left:innerWidth<640?48:64,right:innerWidth<640?42:64,top:30,bottom:innerWidth<640?36:24},
    xAxis:{type:'category',data:d,axisLabel:{color:CT.axis,fontSize:10.5,rotate:innerWidth<640?30:0,showMinLabel:true,showMaxLabel:true,
      interval:Math.ceil(d.length/(innerWidth<640?6:9)),formatter:v=>String(v).slice(5).replace('-','/')},axisLine:{lineStyle:{color:CT.border}}},
    yAxis:[{type:'value',name:innerWidth<640?'':'融資(張)',axisLabel:{color:CT.axis,fontSize:11},splitLine:{lineStyle:{color:CT.split}}},
           {type:'value',name:innerWidth<640?'':'券/借券(張)',axisLabel:{color:CT.axis,fontSize:11},splitLine:{show:false}},
           {type:'value',show:false,scale:true}],
    dataZoom:[{type:'inside'}],
    series:[
      {name:'融資餘額',type:'line',color:TONE.gold,data:mf,symbol:'none',lineStyle:{width:2,color:TONE.gold},itemStyle:{color:TONE.gold},areaStyle:{color:hexA(TONE.gold,.08)}},
      {name:'融券餘額',type:'line',color:TONE.red,yAxisIndex:1,data:mv,symbol:'none',lineStyle:{width:1.6,color:TONE.red},itemStyle:{color:TONE.red}},
      {name:'借券賣出餘額',type:'line',color:TONE.blue,yAxisIndex:1,data:sb,symbol:'none',lineStyle:{width:1.6,color:TONE.blue},itemStyle:{color:TONE.blue}}
    ].concat(px?[{name:'股價',type:'line',color:CT.ma60,yAxisIndex:2,data:px,symbol:'none',connectNulls:true,
      lineStyle:{width:2,color:CT.ma60},itemStyle:{color:CT.ma60},z:5,
      tooltip:{valueFormatter:v=>v!=null?(+v).toLocaleString():'—'}}]:[])});
}
