function setHomeTab(t){
  ['macro','aipick','stocks','etf','gooaye','port'].forEach(k=>{
    const p=document.getElementById('tp-'+k);
    if(p)p.style.display=(k===t)?'':'none';
    const b=document.querySelector('#homeTabs [data-tab="'+k+'"]');
    if(b)b.classList.toggle('on',k===t);
  });
  try{localStorage.setItem('homeTab',t);}catch(e){}
  if(t==='aipick'){setTimeout(()=>{   // r745:延到本輪腳本跑完再碰 AIPK(啟動時還原分頁會早於 AIPK 宣告 → TDZ)
    try{aipLoad().then(()=>{try{renderAIPick();}catch(e){}});}catch(e){}
    try{setTimeout(aipSweep,600);}catch(e){}},0);}
  if(t==='etf'){try{renderEtf();}catch(e){}}
  if(t==='port'){try{renderPort();}catch(e){}try{setTimeout(portHeadRisk,500);}catch(e){}}
  if(t==='gooaye'){try{
    gaDot(false);
    const stale=!window.__gaRenderT||Date.now()-window.__gaRenderT>10*60e3;
    if(stale){const b=document.getElementById('gaEps');if(b)b.dataset.done='';}
    gooayeLoad(stale);
  }catch(e){}}
  setTimeout(()=>{const p=document.getElementById('tp-'+t);              // 補算被隱藏時初始化的圖表
    if(p&&window.echarts)p.querySelectorAll('div').forEach(el=>{
      try{const ch=echarts.getInstanceByDom(el);if(ch)ch.resize();}catch(e){}});},90);
}
