/* 📈 三種路線:純高息 / 市值型+自製配息 / 混搭 —— 總報酬視角 */
function cfRoutes(es,goal,blend){
  const cfDy4=s=>{const c=(window.__cfCustom||{})[s.id];if(c!=null)return c;
    const o=window.__dyJ&&window.__dyJ[s.id];if(o&&o.dy>0)return o.dy;
    return (s.hold&&s.hold.dy)||null;};
  let hiDy=blend>=4?blend:null;
  if(!hiDy){
    const top=DATA.stocks.filter(s=>s.etf&&s.price&&/^\d/.test(s.id)&&!/債/.test(s.name))
      .map(s=>cfDy4(s)).filter(d=>d&&d>=5&&d<15).sort((a,b)=>b-a).slice(0,5);
    hiDy=top.length?top.reduce((t,d)=>t+d,0)/top.length:7;
  }
  const WD=4;                                             // 總報酬提領率 4%(經典安全提領率)
  const yGoal=goal*12;
  const capHi=yGoal/(hiDy/100), capTR=yGoal/(WD/100);
  const capMix=(yGoal/2)/(hiDy/100)+(yGoal/2)/(WD/100);
  const F=w=>w>=10000?(w/10000).toFixed(2)+' 億':Math.round(w).toLocaleString()+' 萬';
  const per1000=r=>(1000*r/100/12).toFixed(1);
  const card=(t,cap,src2,trade,rate)=>`<div style="flex:1;min-width:250px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:13px 16px">
    <div style="font-weight:900;font-size:14.5px">${t}</div>
    <div style="font-family:var(--mono);font-weight:900;font-size:21px;color:var(--amber);margin:5px 0 2px">${F(cap)}</div>
    <div style="font-size:11.5px;color:var(--dim);margin-bottom:6px">每 1,000 萬 ≈ 月領 ${per1000(rate)} 萬</div>
    <div style="font-size:12.5px;color:var(--txt2);line-height:1.65">💰 ${src2}</div>
    <div style="font-size:12.5px;color:var(--mut);line-height:1.65;margin-top:4px">⚖️ ${trade}</div></div>`;
  return `<div style="margin-top:12px;background:var(--panel2);border:1px solid var(--line);border-radius:11px;padding:12px 14px">
    <div style="font-weight:900;font-size:13.5px;margin-bottom:2px">📈 別忘了價差也是報酬|月領 ${goal} 萬的三種路線</div>
    <div style="font-size:12px;color:var(--dim);margin-bottom:9px">市值型(如 0050)配息少但長期股價成長——用「總報酬提領法」(每月賣一小部分)一樣能造現金流。以下用 ${hiDy.toFixed(1)}% 高息殖利率與 ${WD}% 提領率對照:</div>
    <div style="display:flex;gap:10px;flex-wrap:wrap">
      ${card('① 純高息(全靠配息)',capHi,'現金 100% 來自配息,不用賣股','殖利率隨市況波動;高息 ETF 長期總報酬通常輸市值型——「領得穩」換「賺得少」',hiDy)}
      ${card('② 市值型+自製配息',capTR,`配息約 1~2%+每月賣股補足(年提領 ${WD}%)`,'需要的資金最多,但總報酬提領 4% < 市值型長期年化 ~7-9%,資產大概率越領越多;缺點:空頭年得賣在低點(序列風險),且要克服「賣股領錢」的心理關',WD)}
      ${card('③ 五五混搭',capMix,'一半配息、一半提領——現金流穩定度與成長性各取一半','折衷路線:高息給底氣、市值給成長;再平衡一年做一次即可',(yGoal/capMix*100))}
    </div>
    <div class="dim-note" style="margin-top:8px">4% 提領率源自美股歷史回測(Trinity 研究),台股適用性學界仍有討論,僅供概念對照;三條路線都假設長期持有並承受波動。非投資建議,取捨在你。</div>
  </div>`;
}
/* 🧭 組合調整思路:規則提示 + 一鍵試算(點了直接加入重算,用數字說話) */
function cfAdvice(es,yGoalW,totW){
  const cfDy3=s=>{const c=(window.__cfCustom||{})[s.id];return (c!=null)?c:((s.hold&&s.hold.dy)||null);};
  const pool=DATA.stocks.filter(s=>s.etf&&s.price&&/^\d/.test(s.id)
    &&(()=>{const d=cfDy3(s);return d!=null&&d>0.3&&d<25;})());
  const held=new Set(es.map(s=>s.id));
  const isBond=s=>/債/.test(s.name);
  const isMkt=s=>['0050','006208','00922','00923'].includes(s.id)||/市值|臺灣50|台灣50/.test(s.name);
  const notes=[],chips=[];
  const avgDy=es.reduce((t,s)=>t+s.hold.dy,0)/es.length;
  // 情境判讀
  if(es.length===1)
    notes.push('目前只有一檔——現金流全押單一 ETF 的配息政策上;多一兩檔不同邏輯的標的,單檔減配時比較不傷。');
  if(avgDy<4){
    const hi=pool.filter(s=>!held.has(s.id)&&!isBond(s)&&cfDy3(s)>=6).sort((a,b)=>cfDy3(b)-cfDy3(a))[0];
    if(hi){
      const mixCap=es.reduce((t,s)=>t+(yGoalW/(es.length+1))/(s.hold.dy/100),0)+(yGoalW/(es.length+1))/(cfDy3(hi)/100);
      notes.push(`組合殖利率僅 ${avgDy.toFixed(1)}%(偏市值型)——若目標是「月領現金」,資金效率偏低;試算加入一檔高息(如 ${hi.name}),總需資金可從 ${(totW/10000).toFixed(2)} 億 → 約 ${(mixCap/10000).toFixed(2)} 億。但注意:市值型長期總報酬通常較佳,「領得多」和「賺得多」是取捨。`);
    }
  }
  if(es.length>=2&&es.every(s=>!isBond(s)&&!isMkt(s))&&avgDy>=6)
    notes.push('全部是高股息型——同一種策略疊加,遇到高息退潮(景氣好、市場轉追成長股)會一起縮水;納入一檔市值型或債券型能讓現金流來源多元。');
  if(es.some(isBond))
    notes.push('含債券型——配息穩定度高,但淨值對利率敏感(降息利多、升息壓力),與股票型互補的效果正是來自這個特性。');
  if(!notes.length)
    notes.push('組合已混搭不同類型——記得檢查各檔配息月份(發行商行事曆),錯開月份才能真正做到每月有現金進帳。');
  // 一鍵試算候選:未選的 前2高息 + 1市值 + 1債券
  pool.filter(s=>!held.has(s.id)&&!isBond(s)&&!isMkt(s)).sort((a,b)=>cfDy3(b)-cfDy3(a)).slice(0,2)
    .forEach(s=>chips.push({s,tag:'高息'}));
  const mk=pool.find(s=>!held.has(s.id)&&isMkt(s));
  if(mk)chips.push({s:mk,tag:'市值'});
  const bd=pool.filter(s=>!held.has(s.id)&&isBond(s)).sort((a,b)=>cfDy3(b)-cfDy3(a))[0];
  if(bd)chips.push({s:bd,tag:'債券'});
  return `<div style="margin-top:12px;background:var(--panel2);border:1px solid var(--line);border-radius:11px;padding:11px 14px">
    <div style="font-weight:900;font-size:13.5px;margin-bottom:5px">🧭 調整思路 <span style="font-weight:400;font-size:11.5px;color:var(--dim)">規則提示,取捨自己拿——不是建議買進</span></div>
    ${notes.map(t=>`<div style="font-size:13px;color:var(--txt2);line-height:1.7;padding:3px 0">• ${t}</div>`).join('')}
    ${chips.length?`<div style="margin-top:7px;font-size:13px"><span style="color:var(--mut);font-weight:800">➕ 一鍵試算加入:</span>
      ${chips.map(({s,tag})=>`<span class="glb-stk" data-cfadd="${s.id}" style="cursor:pointer">${tag}|${s.name} ${cfDy3(s).toFixed(1)}%</span>`).join('')}
      <span style="font-size:11px;color:var(--dim)">點了立即重算,不喜歡取消勾選即可</span></div>`:''}
  </div>`;
}
/* 💼 持股分析 */

/* 💼×🔺 持股頭部風險體檢:對持股逐檔跑七腳印,機率≥50%點名警示 */
async function portHeadRisk(){
  const anchor=document.getElementById('ptDiag')||document.getElementById('ptList');
  if(!anchor||!anchor.parentNode)return;
  let box=document.getElementById('ptHead');
  if(!box){
    box=document.createElement('div');
    box.id='ptHead';
    box.style.cssText='background:var(--panel);border:1px solid var(--line);border-left:4px solid var(--amber);border-radius:12px;padding:13px 16px;margin:0 0 12px';
    anchor.parentNode.insertBefore(box,anchor);
  }
  const hold=portGet().map(p=>p.id);
  if(!hold.length){box.style.display='none';return;}
  box.style.display='';
  box.innerHTML='<b>🔺 持股頭部風險體檢</b><div class="dim-note">七腳印引擎逐檔判讀中…</div>';
  const rows=[];
  for(const id of hold){
    try{
      const st0=(DATA.stocks||[]).find(x=>x.id===id);
      const sh=st0?shardOf(st0):`k/tw${twShardKey(id)}.json`;
      await loadShard(KCACHE,sh);
      const e=(KCACHE[sh]||{})[id];
      if(!e||!e.o||e.o.length<50)continue;
      const hp=headprints({o:e.o.map(b=>b[0]),h:e.o.map(b=>b[1]),l:e.o.map(b=>b[2]),c:e.o.map(b=>b[3])});
      if(!hp)continue;
      const st=(DATA.stocks||[]).find(x=>x.id===id);
      rows.push({id,name:(st&&st.name)||id,prob:hp.prob,trend:hp.trend});
    }catch(err){}
  }
  if(!rows.length){box.innerHTML='<b>🔺 持股頭部風險體檢</b><div class="dim-note">持股日K資料尚未就緒,稍後自動重試。</div>';return;}
  rows.sort((a,b)=>b.prob-a.prob);
  const risk=rows.filter(r2=>r2.prob>=50);
  box.innerHTML=`<div style="font-weight:900;margin-bottom:7px">🔺 持股頭部風險體檢 <span style="font-weight:400;font-size:12px;color:var(--dim)">七腳印引擎逐檔判讀・點列看完整證據</span></div>
    ${risk.length?`<div style="color:var(--t-red);font-weight:800;font-size:13.5px;margin-bottom:7px">⚠ ${risk.length} 檔頭部機率 ≥50%——反彈宜視為減碼機會,防守線見個股頁</div>`
                 :`<div style="color:var(--t-green);font-weight:800;font-size:13.5px;margin-bottom:7px">✓ 持股皆未達頭部警戒線(50%),結構尚可</div>`}
    ${rows.map(r2=>`<div data-ph="${r2.id}" style="display:flex;justify-content:space-between;gap:8px;padding:5px 0;cursor:pointer;font-size:13.5px;border-bottom:1px dashed var(--line)">
      <span><b>${r2.name}</b> <span style="color:var(--dim)">${r2.id}</span> <span data-hspx="${r2.id}" style="font-family:var(--mono);font-size:12.5px"></span> · <span style="color:var(--mut)">${r2.trend}</span></span>
      <b style="font-family:var(--mono);color:${r2.prob>=70?TONE.red:r2.prob>=50?TONE.orange:'var(--mut)'}">${r2.prob}%</b></div>`).join('')}`;
  box.querySelectorAll('[data-ph]').forEach(el=>{el.onclick=()=>{location.hash='#stock/'+el.dataset.ph;};});
}

function portGet(){try{return JSON.parse(localStorage.getItem('port1')||'[]');}catch(e){return [];}}
function portSet(v){try{localStorage.setItem('port1',JSON.stringify(v));}catch(e){}}
function portDel(id){portSet(portGet().filter(x=>x.id!==id));renderPort();setTimeout(portHeadRisk,400);}
function portAdd(){
  const id=(document.getElementById('ptId').value||'').trim().toUpperCase();
  const sh=+document.getElementById('ptSh').value, cost=+document.getElementById('ptCost').value;
  const s=(DATA.stocks||[]).find(x=>x.id===id);
  if(!s){alert('找不到「'+id+'」——僅支援站內股池的台股/美股/ETF 代號');return;}
  if(!(sh>0)||!(cost>0)){alert('股數與成本價都要大於 0(台股 1 張 = 1000 股)');return;}
  const arr=portGet().filter(x=>x.id!==id);
  arr.push({id,sh,cost});
  portSet(arr);
  document.getElementById('ptId').value='';document.getElementById('ptSh').value='';document.getElementById('ptCost').value='';
  renderPort();
}
/* 🩺 組合健檢:結構診斷 + 規則式補角觀察名單(非投資建議) */
function portDiag(arr){
  const rows=arr.map(p=>({p,s:(DATA.stocks||[]).find(x=>x.id===p.id)})).filter(r=>r.s&&r.s.price);
  const tw=rows.filter(r=>r.s.market!=='US');
  const F=[];
  if(!tw.length)return {F,ws:[],sec:{}};
  const tot=tw.reduce((t,r)=>t+r.s.price*r.p.sh,0);
  const ws=tw.map(r=>({r,w:r.s.price*r.p.sh/tot*100})).sort((a,b)=>b.w-a.w);
  // 集中度(狀態會翻轉:警示 ↔ 健康)
  if(ws[0].w>=35)F.push({ico:'⚠️',lv:'amb',h:`${ws[0].r.s.name} 占 ${ws[0].w.toFixed(0)}%——集中度高`,
    d:'整體損益基本由它決定。集中是信念的展現、也是波動的來源——確認這是「有意識的選擇」而非「不小心變成這樣」。'});
  else F.push({ico:'✅',lv:'ok',h:`集中度健康——最大持股 ${ws[0].r.s.name} 僅 ${ws[0].w.toFixed(0)}%`,
    d:'沒有單一持股綁架整體損益,結構有韌性。'});
  // 族群
  const sec={};
  ws.forEach(({r,w})=>{const k=r.s.etf?'ETF':(r.s.sector||'其他');sec[k]=(sec[k]||0)+w;});
  const top=Object.entries(sec).sort((a,b)=>b[1]-a[1]);
  if(top[0]&&top[0][1]>=60&&top[0][0]!=='ETF')
    F.push({ico:'🧲',lv:'amb',h:`${top[0][0]} 占 ${top[0][1].toFixed(0)}%——族群重疊`,
      d:'高度同漲同跌,景氣反轉時沒有部位能幫你踩剎車;分散到不同邏輯的族群才有互補效果。'});
  else if(top.length>=2)
    F.push({ico:'✅',lv:'ok',h:`族群分佈健康——最大族群 ${top[0][0]} ${top[0][1].toFixed(0)}%`,
      d:'持股橫跨多個族群,單一產業風暴不至於全軍覆沒。'});
  // 體質
  const withF=ws.filter(({r})=>!r.s.etf&&r.s.f&&r.s.f.score!=null);
  if(withF.length){
    const avgF=withF.reduce((t,{r,w})=>t+r.s.f.score*w,0)/withF.reduce((t,{w})=>t+w,0);
    const weak=withF.filter(({r})=>r.s.f.score<55).map(({r})=>r.s.name);
    F.push({ico:'🧬',lv:avgF>=70?'ok':avgF>=60?'amb':'red',
      h:`加權基本面 ${avgF.toFixed(0)} 分${avgF>=70?'——體質紮實':avgF>=60?'——體質中等':'——體質偏弱'}`,
      d:weak.length?`偏弱持股(<55 分):${weak.join('、')}——弱體質靠題材撐,退潮時跌最快,值得優先重新檢視。`:'各持股基本面分數健康,底子撐得住波動。'});
  }
  // 虧損檢視
  const loss=tw.map(r=>({r,pct:(r.s.price-r.p.cost)/r.p.cost*100})).filter(x=>x.pct<=-15)
    .map(x=>`${x.r.s.name} ${x.pct.toFixed(1)}%`);
  if(loss.length)F.push({ico:'🔻',lv:'amb',h:`虧損部位:${loss.join('、')}`,
    d:'回頭檢查買進理由是否仍成立(基本面?籌碼?題材?)——理由消失才是出場的理由,帳面虧損本身不是。點進個股頁用三力與警示列重新驗證。'});
  // 結構
  const etfW=sec['ETF']||0;
  F.push({ico:'🧺',lv:'ok',h:`個股 ${(100-etfW).toFixed(0)}% / ETF ${etfW.toFixed(0)}%`,
    d:'個股拼超額報酬、ETF 給底盤;比例沒有標準答案,取決於你想花多少時間盯盤與能承受的波動。'});
  return {F,ws,sec:Object.fromEntries(top)};
}
function portWatch(arr,sec){
  const held=new Set(arr.map(p=>p.id));
  const topSecs=Object.entries(sec).filter(([k,v])=>k!=='ETF'&&v>=30).map(([k])=>k);
  return (DATA.stocks||[])
    .filter(s=>s.market==='TW'&&!s.etf&&!held.has(s.id)&&s.f&&s.f.score>=75
      &&s.sector&&!topSecs.includes(s.sector)&&s.price)
    .sort((a,b)=>total(b)-total(a)).slice(0,5);
}
/* ══ 🧭 r583 資產配置顧問:總資金 → 個股/ETF 分配 → 依偏好推薦具體標的與張數(規則化,非投顧) ══ */
function advDy(s){
  const o=window.__dyJ&&window.__dyJ[s.id];
  if(o&&o.ps>0&&s.price>0)return +(o.ps/s.price*100).toFixed(2);
  if(o&&o.dy>0)return o.dy;
  return (s.hold&&s.hold.dy)||null;
}
function advEtfType(s){
  if(/債/.test(s.name))return 'bond';
  if(/不動產|REIT/i.test(s.name))return 'reit';
  if(/半導體|科技|費半|電動車|綠能|AI|創新|那斯達克|NASDAQ|尖牙/i.test(s.name))return 'tech';
  if(/高股息|高息|優息|存股|精選高|填息|收益/.test(s.name))return 'div';
  return 'mkt';
}
